local function decodeWallpaperBase64(encoded)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local values = {}
    for index = 1, #alphabet do
        values[alphabet:sub(index, index)] = index - 1
    end

    encoded = encoded:gsub("%s", "")
    local chunks = {}
    local blockSize = 16384
    for startIndex = 1, #encoded, blockSize do
        local stopIndex = math.min(startIndex + blockSize - 1, #encoded)
        local bytes = {}
        for index = startIndex, stopIndex, 4 do
            local a = values[encoded:sub(index, index)] or 0
            local b = values[encoded:sub(index + 1, index + 1)] or 0
            local c = values[encoded:sub(index + 2, index + 2)] or 0
            local d = values[encoded:sub(index + 3, index + 3)] or 0
            local number = a * 262144 + b * 4096 + c * 64 + d
            local first = math.floor(number / 65536) % 256
            local second = math.floor(number / 256) % 256
            local third = number % 256

            if encoded:sub(index + 2, index + 2) == "=" then
                bytes[#bytes + 1] = string.char(first)
            elseif encoded:sub(index + 3, index + 3) == "=" then
                bytes[#bytes + 1] = string.char(first, second)
            else
                bytes[#bytes + 1] = string.char(first, second, third)
            end
        end
        chunks[#chunks + 1] = table.concat(bytes)
    end

    return table.concat(chunks)
end
local function ensureWorkspaceFolder(path)
    local ok, exists = pcall(isfolder, path)
    if ok and exists then
        return true
    end

    local normalized = path:gsub("\\", "/")
    local parent = normalized:match("^(.*)/[^/]+$")
    if parent and parent ~= "" and parent ~= normalized then
        ensureWorkspaceFolder(parent)
    end

    pcall(makefolder, path)
    local made, isMade = pcall(isfolder, path)
    return made and isMade
end

local function copyWorkspaceFile(source, destination)
    local sourceOk, sourceExists = pcall(isfile, source)
    if not sourceOk or not sourceExists then
        return
    end

    local destinationOk, destinationExists = pcall(isfile, destination)
    if destinationOk and destinationExists then
        return
    end

    local normalized = destination:gsub("\\", "/")
    local parent = normalized:match("^(.*)/[^/]+$")
    if parent then
        ensureWorkspaceFolder(parent)
    end

    local readOk, contents = pcall(readfile, source)
    if readOk then
        pcall(writefile, destination, contents)
    end
end

local function copyWorkspaceFolder(source, destination)
    local sourceOk, sourceExists = pcall(isfolder, source)
    if not sourceOk or not sourceExists then
        return
    end

    ensureWorkspaceFolder(destination)
    local listOk, entries = pcall(listfiles, source)
    if not listOk or type(entries) ~= "table" then
        return
    end

    for _, sourcePath in pairs(entries) do
        if type(sourcePath) == "string" then
            local normalized = sourcePath:gsub("\\", "/")
            local name = normalized:match("([^/]+)$")
            if name then
                local destinationPath = destination .. "/" .. name
                local folderOk, isFolder = pcall(isfolder, sourcePath)
                if folderOk and isFolder then
                    copyWorkspaceFolder(sourcePath, destinationPath)
                else
                    copyWorkspaceFile(sourcePath, destinationPath)
                end
            end
        end
    end
end

local function installBundledWallpaper()
    local path = "Jawless Jockey Hub/JawlessJockeyHubBackground.png"
    local checkOk, exists = pcall(isfile, path)
    if checkOk and exists then
        return true
    end

    local decodeOk, imageBytes = pcall(decodeWallpaperBase64, WALLPAPER_BASE64)
    if not decodeOk or type(imageBytes) ~= "string" then
        warn("[Jawless Jockey Hub] Could not decode the bundled wallpaper.")
        return false
    end

    local writeOk = pcall(writefile, path, imageBytes)
    if not writeOk then
        warn("[Jawless Jockey Hub] Could not save the wallpaper to the executor workspace.")
        return false
    end

    return true
end
local function migrateWorkspaceData()
    if type(isfolder) ~= "function"
        or type(makefolder) ~= "function"
        or type(listfiles) ~= "function"
        or type(isfile) ~= "function"
        or type(readfile) ~= "function"
        or type(writefile) ~= "function"
    then
        return
    end

    ensureWorkspaceFolder("Jawless Jockey Hub")

    local newFolders = {
        "Jawless Jockey Hub/Modules",
        "Jawless Jockey Hub/Timings",
        "Jawless Jockey Hub/Configs",
        "Jawless Jockey Hub/Themes",
        "Jawless Jockey Hub/Spotify",
        "Jawless Jockey Hub/Spotify/Art",
        "Jawless Jockey Hub/Stolen Builds",
        "Jawless Jockey Hub/Settings",
    }
    for _, folder in ipairs(newFolders) do
        ensureWorkspaceFolder(folder)
    end

    local folderCopies = {
        { "Lycoris", "Jawless Jockey Hub" },
        { "Lycoris-Rewrite-Modules", "Jawless Jockey Hub/Modules" },
        { "Lycoris-Rewrite-Timings", "Jawless Jockey Hub/Timings" },
        { "Lycoris-Rewrite-Configs", "Jawless Jockey Hub/Configs" },
        { "Lycoris-Rewrite-Themes", "Jawless Jockey Hub/Themes" },
    }

    for _, paths in ipairs(folderCopies) do
        copyWorkspaceFolder(paths[1], paths[2])
    end

    local fileCopies = {
        { "smarker.txt", "Jawless Jockey Hub/Settings/smarker.txt" },
        { "dpscanning.txt", "Jawless Jockey Hub/Settings/dpscanning.txt" },
        { "norpc.txt", "Jawless Jockey Hub/Settings/norpc.txt" },
        { "verbose.txt", "Jawless Jockey Hub/Settings/verbose.txt" },
    }

    for _, paths in ipairs(fileCopies) do
        copyWorkspaceFile(paths[1], paths[2])
    end

    installBundledWallpaper()
end

---Find existing instances and initialize the script.
local function initializeScript()
	-- Check if there's already another instance.
	if shared.Lycoris then
		-- Detach previous instance.
		shared.Lycoris.detach()

		-- Share the previous state.
		Lycoris.queued = shared.Lycoris.queued
	end

	migrateWorkspaceData()
	-- Re-initialize under the new state.
	shared.Lycoris = Lycoris
	shared.Lycoris.init()
end

---This is called when the initalization errors.
---@param error string
local function onInitializeError(error)
	-- Warn that an error happened while initializing.
	warn("Failed to initialize.")
	warn(error)

	-- Warn traceback.
	warn(debug.traceback())

	-- Detach the current instance.
	Lycoris.detach()
end

-- Safely profile and initialize the script aswell as handle errors.
Profiler.run("Main_InitializeScript", function(...)
	return xpcall(initializeScript, onInitializeError, ...)
end)

end)
__bundle_register("Lycoris", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Detach and initialize a Lycoris instance.
local Lycoris = { queued = false, silent = false, dpscanning = false, norpc = false, verbose = false }

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Environment
local Environment = require("Utility/Environment")

---@module Game.Hooking
local Hooking = require("Game/Hooking")

---@module Menu
local Menu = require("Menu")

---@module Features
local Features = require("Features")

---@module Utility.ControlModule
local ControlModule = require("Utility/ControlModule")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.PlayerScanning
local PlayerScanning = require("Game/PlayerScanning")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Game.Timings.ModuleManager
local ModuleManager = require("Game/Timings/ModuleManager")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Game.Wipe
local Wipe = require("Game/Wipe")

---@module Features.Automation.EchoFarm
local EchoFarm = require("Features/Automation/EchoFarm")

-- Lycoris maid.
local lycorisMaid = Maid.new()

-- Constants.
local LOBBY_PLACE_ID = 4111023553
local DEPTHS_PLACE_ID = 5735553160
local CHIME_LOBBY_PLACE_ID = 12559711136

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local playersService = game:GetService("Players")

-- Timestamp.
local startTimestamp = os.clock()

---Initialize instance.
function Lycoris.init()
	local localPlayer = nil

	repeat
		task.wait()
	until game:IsLoaded()

	-- Install the hooks immediately; none of this needs LocalPlayer to exist yet.
	if game.PlaceId ~= LOBBY_PLACE_ID then
		Hooking.earlyInit()
	end

	repeat
		localPlayer = playersService.LocalPlayer
	until localPlayer ~= nil

	if isfile and isfile("Jawless Jockey Hub/Settings/smarker.txt") then
		Lycoris.silent = true
	end

	if isfile and isfile("Jawless Jockey Hub/Settings/dpscanning.txt") then
		Lycoris.dpscanning = true
	end

	if isfile and isfile("Jawless Jockey Hub/Settings/norpc.txt") then
		Lycoris.norpc = true
	end

	if isfile and isfile("Jawless Jockey Hub/Settings/verbose.txt") then
		Lycoris.verbose = true
	end

	if game.PlaceId == CHIME_LOBBY_PLACE_ID then
		return Logger.warn("Script has initialized in the Chime lobby.")
	end

	if game.PlaceId ~= LOBBY_PLACE_ID then
		-- Attempt to initialize KeyHandling.
		KeyHandling.init()

		-- Attempt to initialize Hooking.
		Hooking.init()
	end

	CoreGuiManager.set()

	PersistentData.init()

	if game.PlaceId == LOBBY_PLACE_ID then
		Logger.warn("Script has initialized in the lobby.")
	end

	if game.PlaceId == LOBBY_PLACE_ID then
		-- Handle lobby state for server hopping. This takes priority over everything else.
		if PersistentData.get("shslot") then
			return ServerHop.lobby()
		end

		-- Handle lobby state for wiping. This takes priority over every farm.
		if PersistentData.get("wdata") then
			return Wipe.lobby()
		end
	end

	-- Okay, clear server hop slot.
	PersistentData.set("shslot", nil)

	if game.PlaceId == DEPTHS_PLACE_ID then
		-- Handle depths state for wiping. This takes priority over every other farm.
		if PersistentData.get("wdata") then
			Wipe.depths()
		end
	end

	-- Finally, handle Echo Farming.
	if PersistentData.get("efdata") then
		EchoFarm.start()
	end

	if game.PlaceId == LOBBY_PLACE_ID then
		return
	end

	QueuedBlocking.init()

	SaveManager.init()

	ModuleManager.refresh()

	ControlModule.init()

	Features.init()

	Menu.init()

	PlayerScanning.init()

	StateListener.init()

	-- Resume Auto Ferryman after a server hop (afdata survives the teleport via MemStorage). Wait
	-- until we're actually in the Eastern Luminant (ValleyExit may still be streaming in) before
	-- restarting the farm.
	if PersistentData.get("afdata") then
		task.spawn(function()
			local AutoFerryman = require("Features/Automation/AutoFerryman")
			local deadline = os.clock() + 60
			repeat
				task.wait(1)
			until AutoFerryman.inEasternLuminant() or AutoFerryman.inBossDungeon() or os.clock() >= deadline

			if AutoFerryman.inEasternLuminant() or AutoFerryman.inBossDungeon() then
				AutoFerryman.start()
			end
		end)
	end

	-- Resume Titus Farm after a server hop or wipe (tfdata survives the teleport via MemStorage).
	if PersistentData.get("tfdata") then
		task.spawn(function()
			require("Features/Automation/TitusFarm").start()
		end)
	end

	-- Resume Auto Saramed / Auto Moon's Eyrie after a server hop or dungeon teleport (pfdata survives via MemStorage).
	if PersistentData.get("pfdata") then
		task.spawn(function()
			require("Features/Automation/PveFarm").start()
		end)
	end

	Logger.notify("Script has been initialized in %ims.", (os.clock() - startTimestamp) * 1000)

	if not PersistentData.get("fli") then
		PersistentData.set("fli", os.time())
	end

	local modules = replicatedStorage:FindFirstChild("Modules")
	local bloxstrapRPC = modules and modules:FindFirstChild("BloxstrapRPC")
	local bloxstrapRPCModule = bloxstrapRPC and require(bloxstrapRPC)

	if not bloxstrapRPCModule then
		return
	end

	if Lycoris.norpc then
		return
	end

	bloxstrapRPCModule.SetRichPresence({
		details = "Jawless Jockey Hub (Attached)",
		state = string.format(
			"Currently attached to the script - time elapsed is a session of %s time spent.",
			Environment.isTester() and "developing" or "using"
		),
		timeStart = PersistentData.get("fli") or os.time(),
		largeImage = {
			assetId = Environment.isTester() and 11289930484 or 109802578297970,
			hoverText = Environment.isTester() and "Developing Deepwoken" or "Using Deepwoken",
		},
		smallImage = {
			assetId = Environment.isTester() and 15828456271 or 17278571027,
			hoverText = Environment.isTester() and "Developing Deepwoken" or "Using Deepwoken",
		},
	})

	local playerRemovingSignal = lycorisMaid:mark(Signal.new(playersService.PlayerRemoving))

	playerRemovingSignal:connect("Lycoris_OnLocalPlayerRemoved", function(player)
		if player ~= playersService.LocalPlayer then
			return
		end

		-- Clear BloxstrapRPC.
		bloxstrapRPCModule.SetRichPresence({
			details = "",
			state = "",
			timeStart = 0,
			timeEnd = 0,
			largeImage = {
				clear = true,
			},
			smallImage = {
				clear = true,
			},
		})
	end)
end

---Detach instance.
function Lycoris.detach()
	lycorisMaid:clean()

	ModuleManager.detach()

	Menu.detach()

	QueuedBlocking.detach()

	ControlModule.detach()

	Features.detach()

	SaveManager.detach()

	PlayerScanning.detach()

	CoreGuiManager.clear()

	StateListener.detach()

	local modules = replicatedStorage:FindFirstChild("Modules")
	local bloxstrapRPC = modules and modules:FindFirstChild("BloxstrapRPC")
	local bloxstrapRPCModule = bloxstrapRPC and require(bloxstrapRPC)

	if bloxstrapRPCModule then
		bloxstrapRPCModule.SetRichPresence({
			details = "Jawless Jockey Hub (Detached)",
			state = Environment.isTester() and "Detached from script - something broke, fixing a bug, or a hot-reload."
				or "Detached from script - something broke or a hot-reload.",
			timeStart = PersistentData.get("fli") or os.time(),
			largeImage = {
