---@param boss Instance
---@return boolean
local function bossDoingAction(boss)
	local animator = boss:FindFirstChildWhichIsA("Animator", true)
	if not animator then
		return false
	end

	local ok, tracks = pcall(function()
		return animator:GetPlayingAnimationTracks()
	end)
	if not ok or not tracks then
		return false
	end

	for _, track in next, tracks do
		local anim = track.Animation
		if anim and tostring(anim.AnimationId):find(BOSS_HOLD_ANIM_ID, 1, true) then
			return true
		end
	end

	return false
end

---@return boolean
local function isWeaponDrawn()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local module = effectReplicator and require(effectReplicator)
	if not module then
		return false
	end
	local ok, has = pcall(function()
		return module:HasEffect("Equipped")
	end)
	return ok and has == true
end

---@return Tool?
local function equipWeapon()
	local character = localPlayer and localPlayer.Character
	if not character then
		return nil
	end

	local tool = character:FindFirstChild(WEAPON_NAME)
	if not (tool and tool:IsA("Tool")) then
		local backpack = localPlayer:FindFirstChild("Backpack")
		tool = backpack and backpack:FindFirstChild(WEAPON_NAME)
	end
	if not (tool and tool:IsA("Tool")) then
		return nil
	end

	if not isWeaponDrawn() then
		local handler = character:FindFirstChild("CharacterHandler")
		local requests = handler and handler:FindFirstChild("Requests")
		local drawEvent = requests and requests:FindFirstChild("DrawWeapon")
		if drawEvent then
			pcall(function()
				drawEvent:FireServer(true)
			end)
		end
	end

	return tool
end

local function enableBossCombat()
	if Options then
		if Options.BlockInputAllowedTargets then
			Options.BlockInputAllowedTargets:SetValue({ PVE = true })
		end
		if Options.BlockedSafeInputUserMoves then
			Options.BlockedSafeInputUserMoves:SetValue({ M1s = true, Criticals = true, Mantras = true })
		end
		if Options.AutoFeintOwnTags then
			Options.AutoFeintOwnTags:SetValue({ M1s = true, Mantras = true })
		end
		if Options.AutoFeintAgainstTags then
			Options.AutoFeintAgainstTags:SetValue({ M1s = true, Mantras = true, Criticals = true })
		end
	end

	if Toggles then
		if Toggles.EnableAutoDefense then
			Toggles.EnableAutoDefense:SetValue(true)
		end
		if Toggles.BlockInput then
			Toggles.BlockInput:SetValue(true)
		end
		if Toggles.AutoFeint then
			Toggles.AutoFeint:SetValue(true)
		end
		if Toggles.PathfindBreaker then
			Toggles.PathfindBreaker:SetValue(true)
		end
	end
end

---@param choicePrompt Instance
---@param names table
---@return boolean selected
local function lootMatchingItems(choicePrompt, names)
	local frame = choicePrompt:FindFirstChild("ChoiceFrame")
	local options = frame and frame:FindFirstChild("Options")
	local choice = choicePrompt:FindFirstChild("Choice")
	if not options or not choice then
		return false
	end

	local selected = false
	for _, button in next, options:GetChildren() do
		if not button:IsA("TextButton") then
			continue
		end
		local title = button:FindFirstChild("Title")
		local text = title and title.Text
		if not text then
			continue
		end
		local lower = text:lower()
		for _, name in next, names do
			if type(name) == "string" and lower:find(name:lower(), 1, true) then
				pcall(function()
					choice:FireServer(button.Name)
				end)
				selected = true
				task.wait(0.1)
				break
			end
		end
	end
	return selected
end

---@param looted table<Instance, boolean>
---@return Model?
local function nextChest(looted)
	local thrown = workspace:FindFirstChild(THROWN_FOLDER)
	if not thrown then
		return nil
	end
	for _, model in next, thrown:GetChildren() do
		if
			model:IsA("Model")
			and model.Name == CHEST_MODEL_NAME
			and not looted[model]
			and not collectionService:HasTag(model, LOOTED_TAG)
			and model:FindFirstChild(INTERACT_PROMPT_NAME, true)
		then
			return model
		end
	end
	return nil
end

local function lootChests()
	AutoFerryman.setAction(TEXT.lootingChests)

	local wanted = Configuration.expectOptionValues("ItemNameList") or {}
	local starsMin = Configuration.expectOptionValue("AutoLootStarsMin") or 0
	local starsMax = Configuration.expectOptionValue("AutoLootStarsMax") or 4
	local lootAll = Configuration.expectToggleValue("AutoLootAll") or false
	local always = { ALWAYS_LOOT }

	local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")

	AutoLoot.ignore = true

	local looted = {}
	local attempts = {}
	local lootedCount = 0
	local spawnDeadline = os.clock() + 30
	while AutoFerryman.running and lootedCount < CHEST_COUNT and os.clock() < spawnDeadline do
		local chest = nextChest(looted)
		if not chest then
			AutoFerryman.setAction(TEXT.waitingForChests)
			task.wait(0.5)
			continue
		end

		attempts[chest] = (attempts[chest] or 0) + 1
		if attempts[chest] > 4 then
			looted[chest] = true
			pcall(function()
				collectionService:AddTag(chest, LOOTED_TAG)
			end)
			continue
		end

		AutoFerryman.setAction(TEXT.lootingChest)

		local ok, pivot = pcall(function()
			return chest:GetPivot().Position
		end)
		if ok then
			moveTo(CFrame.new(pivot))
		end
		if not AutoFerryman.running then
			break
		end

		local prompt = chest:FindFirstChild(INTERACT_PROMPT_NAME, true)
		local choicePrompt = nil
		local deadline = os.clock() + 6
		repeat
			Prompt.fire(prompt)
			choicePrompt = playerGui and playerGui:FindFirstChild("ChoicePrompt")
			task.wait(0.2)
		until choicePrompt or os.clock() >= deadline or not AutoFerryman.running

		if choicePrompt and AutoFerryman.running then
			pcall(function()
				choicePrompt:WaitForChild("ChoiceFrame", 3):WaitForChild("Options", 3)
			end)

			local names = {}
			for _, name in next, wanted do
				names[#names + 1] = name
			end
			names[#names + 1] = ALWAYS_LOOT
			pcall(function()
				lootMatchingItems(choicePrompt, names)
			end)

			AutoLoot.process(choicePrompt, AutoLootOptions.new(starsMin, starsMax, wanted, lootAll, always))

			local lootDeadline = os.clock() + 15
			repeat
				task.wait(0.1)
			until (not choicePrompt.Parent) or os.clock() >= lootDeadline or not AutoFerryman.running

			looted[chest] = true
			pcall(function()
				collectionService:AddTag(chest, LOOTED_TAG)
			end)
			lootedCount = lootedCount + 1
			spawnDeadline = os.clock() + 30
		end

		task.wait(0.3)
	end

	AutoLoot.ignore = false
end

local function bossRoutine()
	local ferryman = findFerrymanNpc()
	if not ferryman then
		AutoFerryman.setAction(TEXT.ferrymanNotFound)
		AutoFerryman.stop()
		return
	end

	AutoFerryman.setAction(TEXT.tweeningToFerryman)
	local ok, pivot = pcall(function()
		return ferryman:GetPivot().Position
	end)
	if ok then
		moveTo(CFrame.new(pivot))
	end
	if not AutoFerryman.running then
		return
	end

	AutoFerryman.setAction(TEXT.talkingToFerryman)

	local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")

	while AutoFerryman.running do
		local currentFerryman = findFerrymanNpc()
		if not currentFerryman then
			break
		end

		if timeoutDeadline and os.clock() >= timeoutDeadline then
			AutoFerryman.hop(TEXT.reasonTimeout)
			return
		end

		local dialogueGui = playerGui and playerGui:FindFirstChild("DialogueGui")
		if dialogueGui and dialogueGui.Enabled then
			break
		end

		Prompt.fire(currentFerryman:FindFirstChild(INTERACT_PROMPT_NAME, true))

		setActionText(TEXT.talkingToFerryman)
		task.wait(0.5)
	end

	if not AutoFerryman.running then
		return
	end

	setActionText(TEXT.advancingDialogue)
	local requests = replicatedStorage:FindFirstChild("Requests")
	local sendDialogue = requests and requests:FindFirstChild("SendDialogue")
	for index, choice in ipairs(FERRYMAN_DIALOGUE_CHOICES) do
		if not AutoFerryman.running then
			return
		end
		if sendDialogue then
			pcall(function()
				sendDialogue:FireServer({ choice = choice })
			end)
		end
		if index < #FERRYMAN_DIALOGUE_CHOICES then
			task.wait(0.5)
		end
	end

	AutoFerryman.setAction(TEXT.dialogueComplete)

	AutoFerryman.setAction(TEXT.waitingForBoss)
	while AutoFerryman.running and not findBossModel() do
		task.wait(0.5)
	end
	if not AutoFerryman.running then
		return
	end

	enableBossCombat()

	local weapon = equipWeapon()
	if not weapon then
		AutoFerryman.setAction(TEXT.noWeapon)
		Logger.notify(TEXT.noWeaponNotify)
		AutoFerryman.stop()
		return
	end

	armTimeout(BOSS_FIGHT_TIMEOUT)
	while AutoFerryman.running do
		if timeoutDeadline and os.clock() >= timeoutDeadline then
			AutoFerryman.setAction(TEXT.bossFightTimedOut)
			Logger.notify(TEXT.bossTimedOutNotify)
			AutoFerryman.stop()
			return
		end

		local boss = findBossModel()
		if not boss then
			break
		end

		local ok, bossPos = pcall(function()
			return boss:GetPivot().Position
		end)
		if ok then
			local root = localPlayer and localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")

			if bossDoingAction(boss) then
				Tweening.stop(CHOP_TWEEN_IDENTIFIER)
			else
				local underPos = bossPos - Vector3.new(0, BOSS_UNDER_OFFSET, 0) + Vector3.new(0.1, 0, 0)
				Tweening.goal(CHOP_TWEEN_IDENTIFIER, CFrame.lookAt(underPos, bossPos), false)

				equipWeapon()
				setActionText(TEXT.fightingFerryman)
				local aim = root and CFrame.new(root.Position, bossPos) or CFrame.new(bossPos)
				pcall(function()
					InputClient.left(aim, true)
				end)
			end
		end

		task.wait(CHOP_SWING_INTERVAL)
	end

	Tweening.stop(CHOP_TWEEN_IDENTIFIER)

	if not AutoFerryman.running then
		return
	end

	cycles = cycles + 1
	saveState()
	AutoFerryman.setAction(TEXT.bossDefeated)

	lootChests()

	if not AutoFerryman.running then
		return
	end

	AutoFerryman.setAction(TEXT.chestsLooted)

	AutoFerryman.hop(TEXT.reasonCycleComplete)
end

---@param text string?
function AutoFerryman.setAction(text)
	setActionText(text)
	armTimeout(DEFAULT_TIMEOUT)
end

---@param name string
---@return boolean
local function toolPresent(name)
	local character = localPlayer and localPlayer.Character
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	if character and character:FindFirstChild(name) then
		return true
	end
	if backpack and backpack:FindFirstChild(name) then
		return true
	end
	return false
end

---@return boolean
local function requirementsMet()
	local character = localPlayer and localPlayer.Character
	if not character then
		return false
	end
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	return backpack ~= nil and #backpack:GetChildren() > 0
end

---@param timeout number?
---@return boolean loaded
local function waitForBackpack(timeout)
	local deadline = os.clock() + (timeout or 10)
	while os.clock() < deadline do
		local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
		if backpack and #backpack:GetChildren() > 0 then
			return true
		end
		task.wait(0.1)
	end
	return false
end

function AutoFerryman.start()
	if AutoFerryman.running then
		return
	end

	if game.PlaceId == DEPTHS_PLACE_ID then
		AutoFerryman.stop()
		pcall(function()
			localPlayer:Kick(TEXT.kickDepths)
		end)
		return
	end

	local mode
	if AutoFerryman.inEasternLuminant() then
		mode = "gather"
	elseif AutoFerryman.inBossDungeon() then
		mode = "boss"
	else
		return Logger.notify(TEXT.notInPlace)
	end

	hopping = false
	flying = false
	timeoutDeadline = nil
	lastDescentClock = nil
	startClock = os.clock()

	local resumeData = PersistentData.get("afdata") or {}
	cycles = resumeData.cycles or 0
	baseElapsed = resumeData.elapsed or 0

	local firstStart = not resumeData.active

	if firstStart then
		startSlot = currentSlot()
	else
		startSlot = resumeData.slot
	end

	local loadingGuiParent = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
	if loadingGuiParent and loadingGuiParent:FindFirstChild("LoadingGui") then
		local deadline = os.clock() + 10
		while not requirementsMet() and os.clock() < deadline do
			pressKey(Enum.KeyCode.A)
			task.wait(0.25)
		end

		if not requirementsMet() then
			AutoFerryman.running = true
			return AutoFerryman.hop(TEXT.reasonLoadingTimeout)
		end
	end

	waitForBackpack(10)

	if firstStart and not (toolPresent("Pickaxe") and toolPresent("Lumber Axe")) then
		return Logger.notify(TEXT.needTools)
	end

	AutoFerryman.running = true

	saveState()

	buildOverlay()
	AutoFerryman.setAction(nil)
	if timerLabel then
		timerLabel.Text = formatElapsed(baseElapsed)
	end
	if timeoutLabel then
		timeoutLabel.Text = TEXT.timeoutNone
	end
	if cyclesLabel then
		cyclesLabel.Text = string.format(TEXT.cycles, cycles)
	end
	if screenGui then
		screenGui.Enabled = true
	end

	applyHighlight()
	applyTweenSpeed()
	applyNoFallDamage()
	applyFly()
	applyDefenseFilter()
	applyNoClip()

	characterAddedConnection = localPlayer.CharacterAdded:Connect(function()
		if not AutoFerryman.running then
			return
		end
		task.wait(0.2)
		applyHighlight()
	end)

	timerConnection = runService.Heartbeat:Connect(function()
		if not AutoFerryman.running then
			return
		end
		if timerLabel then
			timerLabel.Text = formatElapsed(currentElapsed())
		end
		if cyclesLabel then
			cyclesLabel.Text = string.format(TEXT.cycles, cycles)
		end
		if timeoutLabel then
			if timeoutDeadline then
				local remaining = math.max(0, timeoutDeadline - os.clock())
				timeoutLabel.Text = string.format(TEXT.timeout, math.floor(remaining / 60), math.floor(remaining % 60))
			else
				timeoutLabel.Text = TEXT.timeoutNone
			end
		end
	end)

	weaponConnection = runService.Heartbeat:Connect(function()
		if not AutoFerryman.running then
			return
		end
		if not findBossModel() then
			return
		end
		if not isWeaponDrawn() then
			equipWeapon()
		end
	end)

	if mode == "boss" then
		task.spawn(function()
			task.wait(2)
			if AutoFerryman.running then
				bossRoutine()
			end
		end)
	else
		task.spawn(watchForNearbyPlayers)
		task.spawn(function()
			task.wait(2)
			if AutoFerryman.running then
				runRoutine()
			end
		end)
	end

	Logger.notify(TEXT.started)
end

local function teardown()
	AutoFerryman.running = false
	timeoutDeadline = nil

	if flying then
		Tweening.stop(TWEEN_IDENTIFIER)
		local character = localPlayer and localPlayer.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if root then
			pcall(function()
				root.CFrame = CFrame.new(FERRYMAN_TARGET.X, FERRYMAN_DESCENT_Y, FERRYMAN_TARGET.Z)
			end)
		end
	end
	flying = false

	if timerConnection then
		pcall(function()
			timerConnection:Disconnect()
		end)
		timerConnection = nil
	end

	if characterAddedConnection then
		pcall(function()
			characterAddedConnection:Disconnect()
		end)
		characterAddedConnection = nil
	end

	if weaponConnection then
		pcall(function()
			weaponConnection:Disconnect()
		end)
		weaponConnection = nil
	end

	removeHighlight()

	Tweening.stop(TWEEN_IDENTIFIER)
	Tweening.stop(CHOP_TWEEN_IDENTIFIER)
	restoreTweenSpeed()
	restoreNoFallDamage()
	restoreFly()
	restoreDefenseFilter()
	restoreNoClip()

	if screenGui then
		screenGui.Enabled = false
	end
end

---@param reason string
function AutoFerryman.hop(reason)
	if hopping then
		return
	end
	hopping = true

	Logger.notify(TEXT.hopNotify, reason)

	local blacklist = PersistentData.get("sblacklist") or {}
	blacklist[game.JobId] = tick()
	PersistentData.set("sblacklist", blacklist)

	saveState()

	teardown()

	local slot = startSlot or (localPlayer and localPlayer:GetAttribute("DataSlot"))
	ServerHop.hop(slot, false)
end

function AutoFerryman.stop()
	if not AutoFerryman.running and not PersistentData.get("afdata") then
		return
	end

	teardown()

	PersistentData.set("afdata", nil)

	Logger.notify(TEXT.stopped)
end

return AutoFerryman

end)
__bundle_register("Features/Automation/TitusFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
-- TitusFarm module. Titus relic farm & Titus echo farm, ported from Project Rain.
local TitusFarm = { running = false, mode = nil }

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Game.Wipe
local Wipe = require("Game/Wipe")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Features.Automation.AutoLoot
local AutoLoot = require("Features/Automation/AutoLoot")

---@module Features.Automation.Objects.AutoLootOptions
local AutoLootOptions = require("Features/Automation/Objects/AutoLootOptions")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")

local localPlayer = players.LocalPlayer

-- Constants.
local EASTERN_PLACE_ID = 6473861193
local DUNGEON_PLACE_ID = 8668476218
local DEPTHS_PLACE_ID = 5735553160
local ETREAN_PLACE_ID = 6032399813

local MERIT_GATE = CFrame.new(-6875.86, 336.20, 2827.95)
local PLAYER_CHECK_RANGE = 200
local BANK_THRESHOLD = 25
local BANK_COOLDOWN = 45
local FIGHT_TIMEOUT = 30
local MAX_CONSECUTIVE_ERRORS = 3

TitusFarm.RELICS = { "Moonseye Tome", "Idol of Yun'Shul", "Armorer's Needle", "Smith's Alloy" }

local CHARACTER_OPTIONS = {
	relic = { origin = "Merit" },
	echo = { origin = "Merit", weapon = "Sword", modifiers = { "All" } },
}

local TEXT = {
	relicTitle = "Titus Relic Farm",
	echoTitle = "Titus Echo Farm",
	stage = "Stage: %s",
	cycles = "Cycles: %d",
	elapsed = "Elapsed: %d:%02d:%02d",
	stopButton = "Stop",

	started = "%s started.",
	stopped = "Titus Farm stopped.",
	notInPlace = "Titus Farm: Not in a supported place, stopping.",
	wrongSlot = "Titus Farm: On a different slot than started, stopping.",
	inDepths = "Titus Farm: Ended up in the depths, stopping.",
	bankFull = "Titus Farm: Bank is full, stopping.",
	tooManyErrors = "Titus Farm: Too many errors in a row, stopping.",
	hopNotify = "Titus Farm: %s: Server hopping",
	wipeNotify = "Titus Farm: %s: Wiping character",

	reasonPlayerNearby = "player nearby",
	reasonTimeout = "timeout",
	reasonDied = "died",
	reasonTitusFlung = "titus flung",
	reasonCycleComplete = "cycle complete",
	reasonDepths = "in depths",
	reasonEtrean = "in etrean luminant",
	reasonError = "error",

	stageLoading = "loading in",
	stageCreating = "creating character",
	stageBanking = "banking relics",
	stageWater = "refilling water",
	stageTravel = "travelling to gate",
	stageEntering = "entering dungeon",
	stageWaiting = "waiting for arena",
	stageFighting = "fighting titus",
	stageLooting = "looting chest",
	stageItems = "using idol & enchant stone",
	stageLeaving = "leaving dungeon",
}

-- State.
local hopping = false
local startSlot = nil
local startedAt = 0
local cycles = 0
local errors = 0
local relicList = {}
local bankList = {}
local lastBank = 0
local connections = {}
local threads = {}
local previousToggles = {}

-- Overlay.
local screenGui, titleLabel, stageLabel, cyclesLabel, elapsedLabel = nil, nil, nil, nil, nil

-- Used to press Q while attached to Titus.
local virtualInput = nil

pcall(function()
	virtualInput = Instance.new("VirtualInputManager")
end)

if not virtualInput then
	pcall(function()
		virtualInput = game:GetService("VirtualInputManager")
	end)
end

---@return any
local function currentSlot()
	return localPlayer and localPlayer:GetAttribute("DataSlot")
end

---@return Model?
local function getCharacter()
	return localPlayer and localPlayer.Character
end

---@return BasePart?
local function getRoot()
	local character = getCharacter()
	return character and character:FindFirstChild("HumanoidRootPart")
end

---@return Humanoid?
local function getHumanoid()
	local character = getCharacter()
	return character and character:FindFirstChildOfClass("Humanoid")
end

---@return string
local function currentArea()
	return localPlayer:GetAttribute("CurrentArea") or ""
end

---@param connection RBXScriptConnection
---@return RBXScriptConnection
local function track(connection)
	connections[#connections + 1] = connection
	return connection
end

---@param fn function
---@return thread
local function spawnTracked(fn, ...)
	local thread = task.spawn(fn, ...)
	threads[#threads + 1] = thread
	return thread
end

---@param name string
---@return string[]
local function selectedList(name)
	local list = {}
	local option = Options and Options[name]
	if not option or type(option.Value) ~= "table" then
		return list
	end

	for value, selected in next, option.Value do
		if selected then
			list[#list + 1] = value
		end
	end

	return list
end

local function saveState()
	PersistentData.set("tfdata", {
		mode = TitusFarm.mode,
		slot = startSlot,
		started = startedAt,
		cycles = cycles,
		errors = errors,
		relics = relicList,
		bank = bankList,
	})
end

---@param name string
---@param value boolean
local function setToggle(name, value)
	local toggle = Toggles and Toggles[name]
	if not toggle then
		return
	end

	if previousToggles[name] == nil then
		previousToggles[name] = toggle.Value
	end

	if toggle.Value ~= value then
		toggle:SetValue(value)
	end
end

local function restoreToggles()
	for name, value in next, previousToggles do
		local toggle = Toggles and Toggles[name]
		if toggle and toggle.Value ~= value then
			toggle:SetValue(value)
		end
	end

	table.clear(previousToggles)
end

---@return Instance?
local function guiParent()
	local ok, hui = pcall(function()
		return gethui and gethui()
	end)
	if ok and hui then
		return hui
	end

	return game:GetService("CoreGui")
end

---@param class string
---@param props table
---@param parent Instance?
---@return Instance
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in next, props do
		instance[key] = value
	end
	instance.Parent = parent
	return instance
end

---@param y number
---@param text string
---@param parent Instance
---@return TextLabel
local function mkLabel(y, text, parent)
	local label = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, y),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = text,
		ZIndex = 201,
	}, parent)
	Library:AddToRegistry(label, { TextColor3 = "FontColor" })
	return label
end

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "TitusFarmOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 260, 0, 126),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	titleLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = TEXT.relicTitle,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(titleLabel, { TextColor3 = "AccentColor" })

	stageLabel = mkLabel(28, string.format(TEXT.stage, TEXT.stageLoading), outer)
	cyclesLabel = mkLabel(48, string.format(TEXT.cycles, 0), outer)
	elapsedLabel = mkLabel(68, string.format(TEXT.elapsed, 0, 0, 0), outer)

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = TEXT.stopButton,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})

	stopButton.MouseButton1Click:Connect(function()
		TitusFarm.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)

	screenGui.Enabled = false
end

---@param text string
local function setStage(text)
	if stageLabel then
		stageLabel.Text = string.format(TEXT.stage, text)
	end
end

local function updateOverlay()
	if cyclesLabel then
		cyclesLabel.Text = string.format(TEXT.cycles, cycles)
	end

	if elapsedLabel then
		local elapsed = math.max(0, os.time() - startedAt)
		elapsedLabel.Text = string.format(
			TEXT.elapsed,
			math.floor(elapsed / 3600),
			math.floor((elapsed % 3600) / 60),
			math.floor(elapsed % 60)
		)
	end
end

local function teardown()
	TitusFarm.running = false

	for _, connection in next, connections do
		pcall(function()
			connection:Disconnect()
		end)
	end
	table.clear(connections)

	local current = coroutine.running()
	for _, thread in next, threads do
		if thread ~= current then
			pcall(task.cancel, thread)
		end
	end
	table.clear(threads)

	restoreToggles()

	AutoLoot.ignore = false

	AntiAFK.stop("TitusFarm")

	if screenGui then
		screenGui.Enabled = false
	end
end

---Server hop and resume the farm in the new server.
---@param reason string
function TitusFarm.hop(reason)
	if hopping or not TitusFarm.running then
		return
	end

	hopping = true

	Logger.notify(TEXT.hopNotify, reason)

	local blacklist = PersistentData.get("sblacklist") or {}
	blacklist[game.JobId] = tick()
	PersistentData.set("sblacklist", blacklist)

	saveState()

	teardown()

	task.spawn(ServerHop.hop, startSlot or currentSlot(), false)
end

---Wipe the slot and resume the farm on the fresh character.
---@param reason string
function TitusFarm.wipe(reason)
	if hopping or not TitusFarm.running then
		return
	end

	hopping = true

	Logger.notify(TEXT.wipeNotify, reason)

	saveState()

	teardown()

	task.spawn(Wipe.invoke, startSlot or currentSlot(), {})
end

---Move towards a goal at a fixed speed. The height is matched instantly, like Project Rain's tween.
---@param goal CFrame
---@param speed number
---@return table
local function tween(goal, speed)
	local connection = nil

	connection = track(runService.Heartbeat:Connect(function(dt)
		local root = getRoot()
		if not root then
			return
		end

		local offset = Vector3.new(goal.X - root.Position.X, 0, goal.Z - root.Position.Z)

		root.AssemblyLinearVelocity = Vector3.zero

		if offset.Magnitude <= 10 then
			root.CFrame = goal
			return connection:Disconnect()
		end

		local step = math.min(speed * dt, offset.Magnitude)

		root.CFrame = CFrame.new(root.Position.X, goal.Y, root.Position.Z) + offset.Unit * step
	end))

	return {
		stop = function()
			connection:Disconnect()
		end,
		wait = function()
			while connection.Connected and TitusFarm.running do
				task.wait()
			end
		end,
	}
end

---Is another player within range of a position (defaults to us)?
---@param position Vector3?
---@return boolean
local function playerNear(position)
	local root = getRoot()
	local origin = position or (root and root.Position)
	return origin ~= nil and Finder.pnear(origin, PLAYER_CHECK_RANGE) ~= nil
end

---Tween somewhere while avoiding players. Relic mode travels high in the sky, echo mode travels at Y = 0.
---@param goal CFrame
---@param speed number
local function safeTween(goal, speed)
	if playerNear() then
		return TitusFarm.hop(TEXT.reasonPlayerNearby)
	end

	local root = getRoot()
	if not root then
		return
	end

	if TitusFarm.mode == "relic" then
		local height = math.random(8000, 10000)
		root.CFrame = root.CFrame + Vector3.new(0, height, 0)
		tween(goal + Vector3.new(0, height, 0), speed).wait()
	else
		root.CFrame = CFrame.new(root.Position.X, 0, root.Position.Z)
		tween(CFrame.new(goal.X, 0, goal.Z), speed).wait()
	end

	if not TitusFarm.running then
		return
	end

	if playerNear(goal.Position) then
		return TitusFarm.hop(TEXT.reasonPlayerNearby)
	end

	root.CFrame = goal
end

---@return boolean
local function inCharacterCreation()
	if localPlayer:GetAttribute("GameLoaded") == "CharacterCreation" then
		return true
	end

	local creator = workspace:FindFirstChild("CharacterCreator")
	local character = getCharacter()
	return creator ~= nil and character ~= nil and character.Parent == creator
end

---@return boolean
local function inLive()
	local character = getCharacter()
	return character ~= nil and character.Parent ~= nil and character.Parent.Name == "Live"
end

---Keep requesting to spawn in until our character is loaded.
local function requestStart()
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:FindFirstChild("StartMenu")
	local start = startMenu and startMenu:FindFirstChild("Start")
	local deadline = os.clock() + 60

	while TitusFarm.running and not inLive() and not inCharacterCreation() do
		if os.clock() >= deadline then
			return TitusFarm.hop(TEXT.reasonTimeout)
		end

		if start then
			start:FireServer(true)
		end

		task.wait(0.25)
	end
end

---Create a new character using Project Rain's character creator flow.
local function createCharacter()
	local options = CHARACTER_OPTIONS[TitusFarm.mode]
	local requests = replicatedStorage:WaitForChild("Requests")
	local characterCreator = requests:WaitForChild("CharacterCreator")
	local pickSpawn = characterCreator:WaitForChild("PickSpawn")
	local changeWeapon = characterCreator:WaitForChild("ChangeWeapon")
	local finishCreation = characterCreator:WaitForChild("FinishCreation")
	local pickBoon = characterCreator:WaitForChild("PickBoon")
	local pickFlaw = characterCreator:WaitForChild("PickFlaw")
	local toggleMetaModifier = requests:WaitForChild("ToggleMetaModifier", 20)
	local playerGui = localPlayer:WaitForChild("PlayerGui")

	pcall(function()
		local characterGui = playerGui:WaitForChild("CharacterCreator", 10)
		local standard = characterGui.GameMode.Options.Standard.Element

		for _ = 1, 5 do
			firesignal(standard.MouseButton1Click)
			task.wait(0.1)
		end
	end)

	if options.origin then
		for _ = 1, 10 do
			if pickSpawn:InvokeServer(options.origin) then
				break
			end

			task.wait(0.1)
		end
	end

	if options.weapon then
		for _ = 1, 10 do
			if changeWeapon:InvokeServer(options.weapon) then
				break
			end

			task.wait(0.1)
		end
	end

	if options.modifiers and toggleMetaModifier then
		for idx, modifier in next, options.modifiers do
			toggleMetaModifier:FireServer(modifier)

			if idx < #options.modifiers then
				task.wait(1)
			end
		end
	end

	pcall(function()
		local dataReplication = require(replicatedStorage:WaitForChild("Info"):WaitForChild("DataReplication")).GetData()

		for _, flaw in next, dataReplication.Flaws do
			pickFlaw:InvokeServer(tostring(flaw))
		end

		for _, boon in next, dataReplication.Boons do
			pickBoon:InvokeServer(tostring(boon))
		end
	end)

	pickBoon:InvokeServer("Autodidact")
	task.wait(1.5)
	pickFlaw:InvokeServer("Obvious")

	task.spawn(function()
		finishCreation:InvokeServer()
	end)

	task.spawn(function()
		local choicePrompt = playerGui:WaitForChild("ChoicePrompt", 30)
		local choice = choicePrompt and choicePrompt:WaitForChild("Choice", 30)
		if choice then
			choice:FireServer(true)
		end
	end)

	local deadline = os.clock() + 60

	while TitusFarm.running and not inLive() do
		if os.clock() >= deadline then
			return TitusFarm.hop(TEXT.reasonTimeout)
		end

		task.wait()
	end
end

---@param name string
---@return Tool[]
local function relicTools(name)
	local backpack = localPlayer:FindFirstChild("Backpack")
	local tools = {}
	if not backpack then
		return tools
	end

	for _, item in next, backpack:GetChildren() do
		if item.Name == name then
			tools[#tools + 1] = item
		end
	end

	return tools
end

---@return boolean
local function shouldBank()
	if tick() - lastBank <= BANK_COOLDOWN then
		return false
	end

	for _, name in next, bankList do
		if #relicTools(name) >= BANK_THRESHOLD then
			return true
		end
	end

	return false
end

---@return boolean
local function bankFull()
	local prompt = localPlayer.PlayerGui:FindFirstChild("ChoicePrompt")
	local sheet = prompt and prompt:FindFirstChild("DescSheet", true)
	if not sheet or not sheet:FindFirstChild("Ok") then
		return false
	end

	local desc = sheet:FindFirstChild("Desc", true)
	return desc ~= nil and desc.Text == "You don't have any bank slots free."
end

---Submit the maximum amount in the bank's amount prompt.
local function submitAmount()
	local prompt = localPlayer.PlayerGui:FindFirstChild("ChoicePrompt")
	local max = prompt and prompt:GetAttribute("Max")
	local choice = prompt and prompt:FindFirstChild("Choice")
	if not max or not choice then
		return
	end

	task.spawn(pcall, function()
		choice:InvokeServer(max)
	end)
end

---Deposit every selected relic we have 25+ of at the nearest Banker.
local function bankRelics()
	lastBank = tick()

	setStage(TEXT.stageBanking)

	local npcs = workspace:WaitForChild("NPCs")
	local banker = npcs:WaitForChild("Banker", 10)
	local bankerRoot = banker and banker:FindFirstChild("HumanoidRootPart")
	if not bankerRoot then
		return
	end

	local standCFrame = bankerRoot.CFrame * CFrame.new(0, -6, 0)

	safeTween(standCFrame, 150)

	if not TitusFarm.running then
		return
	end

	local root = getRoot()
	if root then
		root.CFrame = standCFrame
	end

	local playerGui = localPlayer:WaitForChild("PlayerGui")
	local sendDialogue = replicatedStorage.Requests:FindFirstChild("SendDialogue")
	local deadline = os.clock() + 15

	while TitusFarm.running and not playerGui:FindFirstChild("BankGui") and os.clock() < deadline do
		local dialogueGui = playerGui:FindFirstChild("DialogueGui")

		if dialogueGui and dialogueGui.Enabled and sendDialogue then
			sendDialogue:FireServer({ choice = "Can I access my account?" })
		else
			pcall(fireproximityprompt, banker:FindFirstChild("InteractPrompt"))
		end

		task.wait(0.5)
	end

	local bankGui = playerGui:FindFirstChild("BankGui")
	local bankChoice = bankGui and bankGui:WaitForChild("Choice", 5)
	if not bankChoice then
		return
	end

	for _, name in next, bankList do
		if #relicTools(name) < BANK_THRESHOLD then
			continue
		end

		for _ = 1, 6 do
			local tools = relicTools(name)
			if #tools == 0 or not TitusFarm.running then
				break
			end

			local before = #tools
			local depositDeadline = os.clock() + 8

			bankChoice:FireServer("deposit", tools)

			repeat
				if bankFull() then
					Logger.notify(TEXT.bankFull)
					TitusFarm.stop()
					task.spawn(ServerHop.rlobby)
					return
				end

				submitAmount()

				task.wait(0.3)
			until #relicTools(name) < before or os.clock() >= depositDeadline
		end
	end
end

---@return boolean
local function needFood()
	local character = getCharacter()
	local water = character and character:FindFirstChild("Water")
	local stomach = character and character:FindFirstChild("Stomach")
	if not water or not stomach then
		return false
	end

	return water.Value <= water.MaxValue * 0.3 and stomach.Value <= stomach.MaxValue * 0.3
end

---@return Instance?
local function nearestWell()
	local root = getRoot()
	local folder = workspace.Terrain:FindFirstChild("Water")
	if not root or not folder then
		return nil
	end

	local closest, closestDistance = nil, nil

	for _, well in next, folder:GetChildren() do
		if not well.Name:match("DrinkingWater") then
			continue
		end

		local distance = (root.Position - well:GetPivot().Position).Magnitude

		if not closestDistance or distance < closestDistance then
			closest, closestDistance = well, distance
		end
	end

	return closest
end

---Drink from the nearest well until our water is at 75%.
local function refillWater()
	local character = getCharacter()
	local water = character and character:FindFirstChild("Water")
	local well = nearestWell()
	if not water or not well or water.Value >= water.MaxValue * 0.75 then
		return
	end

	setStage(TEXT.stageWater)

	safeTween(well:GetPivot(), 250)

	local deadline = os.clock() + 30

	while TitusFarm.running and water.Value < water.MaxValue * 0.75 and os.clock() < deadline do
		pcall(fireproximityprompt, well:FindFirstChild("InteractPrompt"))
		task.wait(0.2)
	end
end

local function setFriendlyFire()
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)
end

---Travel to the Fort Merit gate and enter the Titus dungeon.
local function enterDungeon()
	setStage(TEXT.stageTravel)

	setFriendlyFire()

	safeTween(MERIT_GATE, TitusFarm.mode == "echo" and 225 or 170)

	if not TitusFarm.running then
		return
	end

	setFriendlyFire()

	setStage(TEXT.stageEntering)

	local map = workspace:WaitForChild("Map")
	local entry = map:WaitForChild("MeritEntry", 10)
	local deadline = os.clock() + (TitusFarm.mode == "echo" and 15 or 30)

	while TitusFarm.running and os.clock() < deadline do
		if playerNear(MERIT_GATE.Position) then
			return TitusFarm.hop(TEXT.reasonPlayerNearby)
		end

		if TitusFarm.mode == "echo" then
			tween(MERIT_GATE, 200).wait()
		end

		local prompt = entry and entry:FindFirstChild("InteractPrompt")
		if prompt then
			fireproximityprompt(prompt)
		end

		task.wait(0.1)
	end

	-- We should have been teleported into the dungeon by now.
	TitusFarm.hop(TEXT.reasonTimeout)
end

local function pressQ()
	if not virtualInput then
		return
	end

	pcall(function()
		virtualInput:SendKeyEvent(true, Enum.KeyCode.Q, false, game)
		task.wait(0.05)
		virtualInput:SendKeyEvent(false, Enum.KeyCode.Q, false, game)
	end)
end

local function drawWeapon()
	pcall(function()
		getCharacter().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end

---Sit under Titus and keep pressing Q until the fight is over.
local function attachToTitus()
	local live = workspace:WaitForChild("Live")
	local titus = nil

	while TitusFarm.running and not titus do
		for _, entity in next, live:GetChildren() do
			if entity.Name:sub(1, 1) == "." and entity.Name:lower():find("titus") then
				titus = entity
				break
			end
		end

		task.wait()
	end

	if not titus then
		return
	end

	local torso = titus:WaitForChild("Torso", 10)
	if not torso then
		return
	end

	spawnTracked(function()
		while TitusFarm.running and titus.Parent do
			pressQ()
			task.wait(0.3)
		end
	end)

	spawnTracked(function()
		local root = getRoot()
		if not root then
			return
		end

		local above = CFrame.new(torso.Position.X, 288, torso.Position.Z)

		root.AssemblyLinearVelocity = Vector3.zero

		tween(above, 250).wait()
		task.wait(0.5)
		tween(above, 250).wait()

		local active = nil

		while TitusFarm.running and titus.Parent and torso.Parent do
			if torso.Position.Y > 2000 then
				return TitusFarm.hop(TEXT.reasonTitusFlung)
			end

			root = getRoot()

			if root then
				local target = CFrame.new((torso.CFrame * CFrame.new(0, 1, 0)).Position) * CFrame.Angles(math.rad(-90), 0, 0)

				root.AssemblyLinearVelocity = Vector3.zero

				if target.Y < -3 then
					target = CFrame.new(target.X, -3, target.Z)
					root.CFrame = CFrame.new(root.Position.X, -3, root.Position.Z)
				end

				local distance = (Vector3.new(root.Position.X, 0, root.Position.Z) - Vector3.new(target.X, 0, target.Z)).Magnitude

				if distance > 35 then
					if active then
						active.stop()
					end

					active = tween(target, 200)

					drawWeapon()
				else
					if active then
						active.stop()
						active = nil
					end

					root.CFrame = target
				end
			end

			task.wait()
		end

		if active then
			active.stop()
		end
	end)
end

---@param maxDistance number
---@return Model?
local function findChest(maxDistance)
	local thrown = workspace:FindFirstChild("Thrown")
	local root = getRoot()
	if not thrown or not root then
		return nil
	end

	local closest, closestDistance = nil, nil

	for _, object in next, thrown:GetDescendants() do
		if object.Name ~= "Lid" or not object:IsA("BasePart") then
			continue
		end

		local distance = (root.Position - object.Position).Magnitude
		if distance > maxDistance then
			continue
		end

		if not closestDistance or distance < closestDistance then
			closest, closestDistance = object.Parent, distance
		end
	end

	return closest
end

---Open the Titus chest. Relic mode loots the selected relics, echo mode loots everything.
local function grabChest()
	local chest = nil
	local deadline = os.clock() + 15

	repeat
		chest = findChest(1000)
		task.wait()
	until chest or not TitusFarm.running or os.clock() >= deadline

	local lid = chest and chest:FindFirstChild("Lid")
	if not lid then
		return
	end

	local playerGui = localPlayer:WaitForChild("PlayerGui")

	deadline = os.clock() + 15

	repeat
		pcall(function()
			tween(lid.CFrame, 150).wait()
		end)

		pcall(function()
			fireproximityprompt(chest:FindFirstChild("InteractPrompt") or chest:FindFirstChildWhichIsA("ProximityPrompt", true))
		end)

		task.wait(0.1)
	until playerGui:FindFirstChild("ChoicePrompt") or not TitusFarm.running or os.clock() >= deadline

	local prompt = playerGui:FindFirstChild("ChoicePrompt")
	local choice = prompt and prompt:FindFirstChild("Choice")
	if not choice then
		return
	end

	if TitusFarm.mode == "relic" then
		prompt:WaitForChild("ChoiceFrame", 5)

		AutoLoot.process(prompt, AutoLootOptions.new(0, 4, relicList, false))

		deadline = os.clock() + 5

		repeat
			task.wait()
		until not prompt.Parent or os.clock() >= deadline
	else
		deadline = os.clock() + 3

		repeat
			pcall(function()
				choice:FireServer("LOOT_ALL")
			end)

			task.wait()
		until not prompt.Parent or os.clock() >= deadline
	end

	if prompt.Parent then
		pcall(function()
			choice:FireServer("EXIT")
		end)
	end

	tween(CFrame.new(lid.Position.X, 0, lid.Position.Z), 150).wait()
end

---Use the Idol of Yun'Shul and the Enchant Stone from the chest before wiping.
local function useEchoItems()
	local backpack = localPlayer:FindFirstChild("Backpack")
	local humanoid = getHumanoid()
	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	if not backpack or not humanoid or not playerGui then
		return
	end

	local idol = backpack:FindFirstChild("Idol of Yun'Shul")

	if idol and TitusFarm.running then
		humanoid:EquipTool(idol)
		task.wait(0.3)

		for _ = 1, 3 do
			idol:Activate()
			task.wait(0.1)

			if playerGui:FindFirstChild("ChoicePrompt") then
				break
			end
		end

		local prompt = playerGui:WaitForChild("ChoicePrompt", 5)
		local choice = prompt and prompt:FindFirstChild("Choice")

		if choice then
			choice:FireServer("Give me relief from my Flaws.")

			local deadline = os.clock() + 5

			repeat
				task.wait(0.1)
			until not prompt.Parent or os.clock() >= deadline
		end
	end

	local stone = Finder.tool("Enchant", false)
	if not stone or not TitusFarm.running then
		return
	end

	local weaponTool = backpack:FindFirstChild("Weapon")
	local weaponValue = weaponTool and weaponTool:FindFirstChild("Weapon")
	local weaponName = weaponValue and weaponValue.Value

	pcall(function()
		replicatedStorage.Requests.Unequip:InvokeServer("Weapon", true)
	end)

	task.wait(0.5)

	if type(weaponName) == "string" and #weaponName > 0 then
		for _, tool in next, backpack:GetChildren() do
			if tool:IsA("Tool") and tool.Name:find(weaponName, 1, true) then
				humanoid:EquipTool(tool)
				task.wait(0.1)
				tool:Activate()
				break
			end
		end
	end

	humanoid:EquipTool(stone)
	task.wait(0.5)
	stone:Activate()

	local prompt = playerGui:WaitForChild("ChoicePrompt", 5)
	local choice = prompt and prompt:WaitForChild("Choice", 5)

	if choice then
		choice:FireServer(true)
		task.wait(1)
	end
end

---Project Rain's echo farm marks the realm as the depths while fighting.
local function spoofDepths()
	pcall(function()
		if not localPlayer:HasTag("CharacterCreation") then
			localPlayer:AddTag("CharacterCreation")
		end
	end)

	while TitusFarm.running do
		pcall(function()
			require(replicatedStorage.Info.RealmInfo).IsDepths = true
		end)

		task.wait(5)
	end
end

local function waitForDanger()
	local deadline = os.clock() + 60

	while TitusFarm.running and os.clock() < deadline do
		local humanoid = getHumanoid()
		local expiration = humanoid and humanoid:GetAttribute("DangerExpiration")

		if not expiration or expiration <= 0 then
			return
		end

		task.wait()
	end
end

local function killSelf()
	pcall(function()
		replicatesignal(localPlayer.Kill)
	end)

	task.delay(1, function()
		local humanoid = getHumanoid()
		local root = getRoot()

		if humanoid and humanoid.Health > 1 and root then
			root.CFrame = root.CFrame * CFrame.new(0, 9e9, 0)
		end
	end)
end

---Fight Titus, loot the chest, then either leave (relic) or wipe (echo).
local function runDungeon()
	local echo = TitusFarm.mode == "echo"
	local startTime = os.clock()

	if echo then
		spawnTracked(spoofDepths)
	end

	setStage(TEXT.stageWaiting)

	while TitusFarm.running and not currentArea():match("Detainment") do
		if os.clock() - startTime > 60 then
			return TitusFarm.hop(TEXT.reasonTimeout)
		end

		task.wait(0.2)
	end

	if not TitusFarm.running then
		return
	end

	if not echo then
		task.wait(1)
	end

	setToggle("PathfindBreaker", true)

	setStage(TEXT.stageFighting)

	attachToTitus()

	local humanoid = getHumanoid()

	if humanoid then
		track(humanoid.Died:Connect(function()
			if echo then
				TitusFarm.wipe(TEXT.reasonDied)
			else
				TitusFarm.hop(TEXT.reasonDied)
			end
		end))
	end

	local core = workspace:WaitForChild("DetainmentCore", 30)
	if not core then
		return TitusFarm.hop(TEXT.reasonTimeout)
	end

	local finished = core:FindFirstChild("DungeonExitFinal") ~= nil

	track(core.ChildAdded:Connect(function(child)
		if child.Name == "DungeonExitFinal" then
			finished = true
		end
	end))

	while TitusFarm.running and not finished do
		if os.clock() - startTime > FIGHT_TIMEOUT then
			return TitusFarm.hop(TEXT.reasonTimeout)
		end

		task.wait(0.2)
	end

	if not TitusFarm.running then
		return
	end

	task.wait(0.5)

	setToggle("PathfindBreaker", false)

	setStage(TEXT.stageLooting)

	grabChest()

	if not TitusFarm.running then
		return
	end

	if echo then
		setStage(TEXT.stageItems)
		useEchoItems()
	end

	cycles = cycles + 1
	errors = 0

	saveState()

	if echo then
		task.wait(3.75)
		return TitusFarm.wipe(TEXT.reasonCycleComplete)
	end

	setStage(TEXT.stageLeaving)

	local root = getRoot()
	if root then
		root.CFrame = root.CFrame * CFrame.new(0, 8000, 0)
	end

	task.wait(2)

	root = getRoot()
	if root then
		root.CFrame = root.CFrame * CFrame.new(0, 10000, 0)
	end

	waitForDanger()

	if not TitusFarm.running then
		return
	end

	-- Dying sends us back to the Eastern Luminant, and the Died handler above hops us to a fresh server.
	killSelf()

	task.wait(10)

	TitusFarm.hop(TEXT.reasonCycleComplete)
end

---Figure out where we are and what to do next.
local function checkArea()
	requestStart()

	if not TitusFarm.running then
		return
	end

	if inCharacterCreation() then
		setStage(TEXT.stageCreating)
		createCharacter()

		if not TitusFarm.running then
			return
		end
	end

	local echo = TitusFarm.mode == "echo"

	if game.PlaceId == DEPTHS_PLACE_ID then
		if echo then
			return TitusFarm.wipe(TEXT.reasonDepths)
		end

		Logger.notify(TEXT.inDepths)
		return TitusFarm.stop()
	end

	if game.PlaceId == ETREAN_PLACE_ID and echo then
		return TitusFarm.wipe(TEXT.reasonEtrean)
	end

	if game.PlaceId == EASTERN_PLACE_ID then
		setToggle("PathfindBreaker", echo)

		if not echo and shouldBank() then
			bankRelics()

			if not TitusFarm.running then
				return
			end
		end

		if not echo and needFood() then
			refillWater()

			if not TitusFarm.running then
				return
			end
		end

		return enterDungeon()
	end

	if game.PlaceId == DUNGEON_PLACE_ID then
		return runDungeon()
	end

	Logger.notify(TEXT.notInPlace)
	TitusFarm.stop()
end

local function runRoutine()
	local ok, err = pcall(checkArea)
	if ok or not TitusFarm.running then
		return
	end

	Logger.warn("(TitusFarm) %s", tostring(err))

	errors = errors + 1

	if errors >= MAX_CONSECUTIVE_ERRORS then
		Logger.notify(TEXT.tooManyErrors)
		return TitusFarm.stop()
	end

	TitusFarm.hop(TEXT.reasonError)
end

---Start the Titus farm. Pass a mode to start fresh, or nothing to resume after a hop or wipe.
---@param mode string? "relic" or "echo"
function TitusFarm.start(mode)
	if TitusFarm.running then
		return
	end

	-- A wipe is in progress; the Wipe module will bring us back afterwards.
	if PersistentData.get("wdata") then
		return
	end

	local data = PersistentData.get("tfdata")

	if mode then
		data = {
			mode = mode,
			slot = currentSlot(),
			started = os.time(),
			cycles = 0,
			errors = 0,
			relics = selectedList("TitusRelicList"),
			bank = selectedList("TitusBankList"),
		}
	elseif not data then
		return
	elseif data.slot and currentSlot() and data.slot ~= currentSlot() then
		Logger.notify(TEXT.wrongSlot)
		return TitusFarm.stop()
	end

	TitusFarm.mode = data.mode
	startSlot = data.slot
	startedAt = data.started or os.time()
	cycles = data.cycles or 0
	errors = data.errors or 0
	relicList = data.relics or {}
	bankList = data.bank or {}
	hopping = false

	TitusFarm.running = true

	saveState()

	AntiAFK.start("TitusFarm")

	AutoLoot.ignore = true

	setToggle("Fly", true)
	setToggle("NoClip", true)
	setToggle("NoFallDamage", true)

	buildOverlay()

	titleLabel.Text = TitusFarm.mode == "echo" and TEXT.echoTitle or TEXT.relicTitle

	setStage(TEXT.stageLoading)
	updateOverlay()

	screenGui.Enabled = true

	track(runService.Heartbeat:Connect(updateOverlay))

	spawnTracked(runRoutine)

	Logger.notify(TEXT.started, titleLabel.Text)
end

---Stop the Titus farm and clear its saved state.
function TitusFarm.stop()
	if not TitusFarm.running and not PersistentData.get("tfdata") then
		return
	end

	teardown()

	PersistentData.set("tfdata", nil)

	Logger.notify(TEXT.stopped)
end

-- Return TitusFarm module.
return TitusFarm

end)
__bundle_register("Features/Automation/PveFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
-- PveFarm module. Auto Saramed (Deepdrill dungeon) & Auto Moon's Eyrie (Moonseye knight), ported from Project Rain.
local PveFarm = { running = false, mode = nil }

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")

local localPlayer = players.LocalPlayer

-- Constants.
local EASTERN_PLACE_ID = 6473861193
local DUNGEON_PLACE_ID = 8668476218
local DEPTHS_PLACE_ID = 5735553160

local SARAMED_NPC = CFrame.new(-2856.81, 135.67, 3375.38)
local SARAMED_WELL = CFrame.new(-2814.17, 145.32, 3119.74)
local EYRIE_CAMPFIRE = CFrame.new(-7632.28, 980.37, 421.91)

local PLAYER_CHECK_RANGE = 200
local STAGE_TIMEOUT = 240
local MOB_TIMEOUT = 60
local KNIGHT_STALL_TIMEOUT = 20
local EYRIE_MIN_HEALTH = 0.35
local REST_HEALTH = 0.5
local MAX_CONSECUTIVE_ERRORS = 3
local FUEL_FULL_COLOR = Color3.fromRGB(141, 239, 112):ToHex()
local KNIGHT_KICK_ANIMATIONS = { "106711913879378", "111024000122473" }
local FOODS = { "Pomar", "Mushroom Soup", "Bread" }

local TEXT = {
	saramedTitle = "Auto Saramed",
	eyrieTitle = "Auto Moon's Eyrie",
	stage = "Stage: %s",
	cycles = "Cycles: %d",
	elapsed = "Elapsed: %d:%02d:%02d",
	stopButton = "Stop",

	started = "%s started.",
	stopped = "PvE Farm stopped.",
	otherFarm = "PvE Farm: Another farm (Titus / Ferryman) is still active, stop it first.",
	notInPlace = "PvE Farm: Not in a supported place, stopping.",
	wrongSlot = "PvE Farm: On a different slot than started, stopping.",
	inDepths = "PvE Farm: Ended up in the depths, stopping.",
	needCharacter = "PvE Farm: Start this on an existing character, stopping.",
	needPickaxe = "PvE Farm: Auto Saramed needs a Pickaxe in your inventory.",
	tooManyErrors = "PvE Farm: Too many errors in a row, stopping.",
	hopNotify = "PvE Farm: %s: Server hopping",

	reasonPlayerNearby = "player nearby",
	reasonTimeout = "timeout",
	reasonStuck = "stuck on a stage",
	reasonCycleComplete = "cycle complete",
	reasonError = "error",

	stageLoading = "loading in",
	stageFood = "refilling food & water",
	stageTravel = "travelling",
	stageEntering = "entering dungeon",
	stageDescending = "descending",
	stageFighting = "fighting mobs",
	stageMining = "mining magma ore",
	stageLooting = "looting chest",
	stageResetting = "resetting drill",
	stageResting = "resting at campfire",
	stageLeaving = "leaving dungeon",
	stageDoor = "opening moonseye door",
	stageKnight = "fighting moonknight",
	stageSafety = "escaping danger",
	stageDead = "waiting for respawn",
	stagePickaxe = "waiting for a pickaxe",
}

-- State.
local hopping = false
local startSlot = nil
local startedAt = 0
local cycles = 0
local errors = 0
local minHealth = 0.25
local attachDistance = 8
local stageDeadline = 0
local connections = {}
local threads = {}
local previousToggles = {}

-- Overlay.
local screenGui, titleLabel, stageLabel, cyclesLabel, elapsedLabel = nil, nil, nil, nil, nil

-- Used to press E (campfire rest / well).
local virtualInput = nil

pcall(function()
	virtualInput = Instance.new("VirtualInputManager")
end)

if not virtualInput then
	pcall(function()
		virtualInput = game:GetService("VirtualInputManager")
	end)
end

---@return any
local function currentSlot()
	return localPlayer and localPlayer:GetAttribute("DataSlot")
end

---@return Model?
local function getCharacter()
	return localPlayer and localPlayer.Character
end

---@return BasePart?
local function getRoot()
	local character = getCharacter()
	return character and character:FindFirstChild("HumanoidRootPart")
end

---@return Humanoid?
local function getHumanoid()
	local character = getCharacter()
	return character and character:FindFirstChildOfClass("Humanoid")
end

---@return boolean
local function alive()
	local humanoid = getHumanoid()
	return humanoid ~= nil and humanoid.Health > 0 and getRoot() ~= nil
end

---Should the current routine keep going?
---@return boolean
local function active()
	return PveFarm.running and not hopping and alive()
end

---@param percent number
---@return boolean
local function healthBelow(percent)
	local humanoid = getHumanoid()
	return humanoid ~= nil and humanoid.Health <= humanoid.MaxHealth * percent
end

---@param name string
---@return boolean
local function hasEffect(name)
	local ok, result = pcall(function()
		return require(replicatedStorage.EffectReplicator):FindEffect(name)
	end)
	return ok and result ~= nil and result ~= false
end

---@param connection RBXScriptConnection
---@return RBXScriptConnection
local function track(connection)
	connections[#connections + 1] = connection
	return connection
end

---@param fn function
---@return thread
local function spawnTracked(fn, ...)
	local thread = task.spawn(fn, ...)
	threads[#threads + 1] = thread
	return thread
end

---@param name string
---@param default number
---@return number
local function optionNumber(name, default)
	local option = Options and Options[name]
	local value = option and tonumber(option.Value)
	return value or default
end

local function saveState()
	PersistentData.set("pfdata", {
		mode = PveFarm.mode,
		slot = startSlot,
		started = startedAt,
		cycles = cycles,
		errors = errors,
		health = minHealth,
		attach = attachDistance,
	})
end

---@param name string
---@param value boolean
local function setToggle(name, value)
	local toggle = Toggles and Toggles[name]
	if not toggle then
		return
	end

	if previousToggles[name] == nil then
		previousToggles[name] = toggle.Value
	end

	if toggle.Value ~= value then
		toggle:SetValue(value)
	end
end

local function restoreToggles()
	for name, value in next, previousToggles do
		local toggle = Toggles and Toggles[name]
		if toggle and toggle.Value ~= value then
			toggle:SetValue(value)
		end
	end

	table.clear(previousToggles)
end

---@return Instance?
local function guiParent()
	local ok, hui = pcall(function()
		return gethui and gethui()
	end)
	if ok and hui then
		return hui
	end

	return game:GetService("CoreGui")
end

---@param class string
---@param props table
---@param parent Instance?
---@return Instance
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in next, props do
		instance[key] = value
	end
	instance.Parent = parent
	return instance
end

---@param y number
---@param text string
---@param parent Instance
---@return TextLabel
local function mkLabel(y, text, parent)
	local label = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, y),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = text,
		ZIndex = 201,
	}, parent)
	Library:AddToRegistry(label, { TextColor3 = "FontColor" })
	return label
end

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "PveFarmOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 260, 0, 126),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	titleLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = TEXT.saramedTitle,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(titleLabel, { TextColor3 = "AccentColor" })

	stageLabel = mkLabel(28, string.format(TEXT.stage, TEXT.stageLoading), outer)
	cyclesLabel = mkLabel(48, string.format(TEXT.cycles, 0), outer)
	elapsedLabel = mkLabel(68, string.format(TEXT.elapsed, 0, 0, 0), outer)

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = TEXT.stopButton,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})

	stopButton.MouseButton1Click:Connect(function()
		PveFarm.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)

	screenGui.Enabled = false
end

---Set the overlay stage and reset the stuck watchdog.
---@param text string
local function setStage(text)
	stageDeadline = os.clock() + STAGE_TIMEOUT

	if stageLabel then
		stageLabel.Text = string.format(TEXT.stage, text)
	end
end

local function teardown()
	PveFarm.running = false

	for _, connection in next, connections do
		pcall(function()
			connection:Disconnect()
		end)
	end
	table.clear(connections)

	local current = coroutine.running()
	for _, thread in next, threads do
		if thread ~= current then
			pcall(task.cancel, thread)
		end
	end
	table.clear(threads)

	restoreToggles()

	AntiAFK.stop("PveFarm")

	if screenGui then
		screenGui.Enabled = false
	end
end

---Server hop and resume the farm in the new server.
---@param reason string
function PveFarm.hop(reason)
	if hopping or not PveFarm.running then
		return
	end

	hopping = true

	Logger.notify(TEXT.hopNotify, reason)

	local blacklist = PersistentData.get("sblacklist") or {}
	blacklist[game.JobId] = tick()
	PersistentData.set("sblacklist", blacklist)

	saveState()

	teardown()

	task.spawn(ServerHop.hop, startSlot or currentSlot(), false)
end

local function updateOverlay()
	if PveFarm.running and not hopping and os.clock() >= stageDeadline then
		return PveFarm.hop(TEXT.reasonStuck)
	end

	if cyclesLabel then
		cyclesLabel.Text = string.format(TEXT.cycles, cycles)
	end

	if elapsedLabel then
		local elapsed = math.max(0, os.time() - startedAt)
		elapsedLabel.Text = string.format(
			TEXT.elapsed,
			math.floor(elapsed / 3600),
			math.floor((elapsed % 3600) / 60),
			math.floor(elapsed % 60)
		)
	end
end

---Move towards a goal at a fixed speed. The height is matched instantly, like Project Rain's tween.
---@param goal CFrame
---@param speed number
---@return table
local function tween(goal, speed)
	local connection = nil

	connection = track(runService.Heartbeat:Connect(function(dt)
		local root = getRoot()
		if not root then
			return
		end

		local offset = Vector3.new(goal.X - root.Position.X, 0, goal.Z - root.Position.Z)

		root.AssemblyLinearVelocity = Vector3.zero

		if offset.Magnitude <= 10 then
			root.CFrame = goal
			return connection:Disconnect()
		end

		local step = math.min(speed * dt, offset.Magnitude)

		root.CFrame = CFrame.new(root.Position.X, goal.Y, root.Position.Z) + offset.Unit * step
	end))

	return {
		stop = function()
			connection:Disconnect()
		end,
		wait = function()
			while connection.Connected and active() do
				task.wait()
			end

			connection:Disconnect()
		end,
	}
end

---Is another player within range of a position (defaults to us)?
---@param position Vector3?
---@param range number?
---@return boolean
local function playerNear(position, range)
	local root = getRoot()
	local origin = position or (root and root.Position)
	return origin ~= nil and Finder.pnear(origin, range or PLAYER_CHECK_RANGE) ~= nil
end

---Tween somewhere high in the sky, hopping if a player is near us or the goal.
---@param goal CFrame
---@param speed number
local function safeTween(goal, speed)
	if playerNear() then
		return PveFarm.hop(TEXT.reasonPlayerNearby)
	end

	local root = getRoot()
	if not root then
		return
	end

	local height = math.random(8000, 10000)
	root.CFrame = root.CFrame + Vector3.new(0, height, 0)
	tween(goal + Vector3.new(0, height, 0), speed).wait()

	if not active() then
		return
	end

	if playerNear(goal.Position) then
		return PveFarm.hop(TEXT.reasonPlayerNearby)
	end

	root.CFrame = goal
	task.wait(0.3)
end

---@param keyCode Enum.KeyCode
local function pressKey(keyCode)
	if not virtualInput then
		return
	end

	pcall(function()
		virtualInput:SendKeyEvent(true, keyCode, false, game)
		task.wait(0.1)
		virtualInput:SendKeyEvent(false, keyCode, false, game)
	end)
end

---@param prompt Instance?
local function firePrompt(prompt)
	if prompt then
		pcall(fireproximityprompt, prompt)
	end
end

---@param a BasePart
---@param b BasePart
local function touch(a, b)
	pcall(function()
		firetouchinterest(a, b, 0)
		firetouchinterest(a, b, 1)
	end)
end

local function drawWeapon()
	if hasEffect("Equipped") then
		return
	end

	pcall(function()
		getCharacter().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end

---@param condition function
---@param timeout number
---@return boolean met
local function waitUntil(condition, timeout)
	local deadline = os.clock() + timeout

	while active() and os.clock() < deadline do
		if condition() then
			return true
		end

		task.wait(0.1)
	end

	return false
end

---@return boolean
local function inCharacterCreation()
	if localPlayer:GetAttribute("GameLoaded") == "CharacterCreation" then
		return true
	end

	local creator = workspace:FindFirstChild("CharacterCreator")
	local character = getCharacter()
	return creator ~= nil and character ~= nil and character.Parent == creator
end

---@return boolean
local function inLive()
	local character = getCharacter()
	return character ~= nil and character.Parent ~= nil and character.Parent.Name == "Live"
end

---Keep requesting to spawn in until our character is loaded and alive.
local function requestStart()
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:FindFirstChild("StartMenu")
	local start = startMenu and startMenu:FindFirstChild("Start")
	local deadline = os.clock() + 60

	while PveFarm.running and not hopping and not (inLive() and alive()) and not inCharacterCreation() do
		if os.clock() >= deadline then
			return PveFarm.hop(TEXT.reasonTimeout)
		end

		if start and not inLive() then
			start:FireServer(true)
		end

		task.wait(0.25)
	end
end

---Sit on the closest campfire and rest until we're back to half health.
---@param campfirePart BasePart
local function restAt(campfirePart)
	setStage(TEXT.stageResting)

	local prompt = campfirePart.Parent and campfirePart.Parent:FindFirstChild("InteractPrompt", true)

	waitUntil(function()
		local root = getRoot()
		if root then
			root.CFrame = campfirePart.CFrame * CFrame.new(0, 1, 0)
		end

		firePrompt(prompt)
		task.wait(0.9)

		return hasEffect("Resting")
	end, 20)

	waitUntil(function()
		return not healthBelow(REST_HEALTH)
	end, 180)

	pressKey(Enum.KeyCode.E)
	task.wait(1)
end

---@param parent Instance
---@return BasePart?
local function closestCampfire(parent)
	local root = getRoot()
	if not root then
		return nil
	end

	local closest, closestDistance = nil, nil

	for _, campfire in next, parent:GetChildren() do
		if not campfire:IsA("Model") or not campfire.Name:match("Campfire") then
			continue
		end

		local part = campfire:FindFirstChildWhichIsA("BasePart")
		if not part then
			continue
		end

		local distance = (root.Position - part.Position).Magnitude

		if not closestDistance or distance < closestDistance then
			closest, closestDistance = part, distance
		end
	end

	return closest
end

---Open the closest chest and let Auto Loot decide what to take.
---@param maxDistance number
local function grabChest(maxDistance)
	local thrown = workspace:FindFirstChild("Thrown")
	local root = getRoot()
	if not thrown or not root then
		return
	end

	local chest, closestDistance = nil, nil

	for _, object in next, thrown:GetChildren() do
		local lid = object:FindFirstChild("Lid")
		if not lid or not lid:IsA("BasePart") then
			continue
		end

		local distance = (root.Position - lid.Position).Magnitude

		if distance <= maxDistance and (not closestDistance or distance < closestDistance) then
			chest, closestDistance = object, distance
		end
	end

	if not chest then
		return
	end

	setStage(TEXT.stageLooting)

	local lid = chest.Lid
	local playerGui = localPlayer:WaitForChild("PlayerGui")

	tween(lid.CFrame, 170).wait()

	waitUntil(function()
		local current = getRoot()
		if current then
			current.CFrame = lid.CFrame
		end

		firePrompt(chest:FindFirstChildWhichIsA("ProximityPrompt", true))

		return playerGui:FindFirstChild("ChoicePrompt") ~= nil
	end, 5)

	local prompt = playerGui:FindFirstChild("ChoicePrompt")
	if not prompt then
		return
	end

	-- Auto Loot (if enabled) takes what it wants, then we close whatever is left.
	waitUntil(function()
		return not prompt.Parent
	end, 5)

	if prompt.Parent then
		pcall(function()
			prompt.Choice:FireServer("EXIT")
		end)
	end
end

---Swing at a target until the condition says stop.
---@param target Model
---@param shouldStop function
local function swingAt(target, shouldStop)
	while active() and target.Parent and not shouldStop() do
		local root = getRoot()
		local targetRoot = target:FindFirstChild("HumanoidRootPart")
		local humanoid = target:FindFirstChildOfClass("Humanoid")
		if not targetRoot or not humanoid or humanoid.Health <= 0 then
			break
		end

		drawWeapon()

		pcall(function()
			InputClient.left(CFrame.new(root.Position, targetRoot.Position), true)
		end)

		task.wait(0.15)
	end
end

---------------------------------------------------------------------------------------------------
-- Auto Saramed.
---------------------------------------------------------------------------------------------------

---@param name string
---@return NumberValue?
local function stat(name)
	local character = getCharacter()
	return character and character:FindFirstChild(name)
end

---@param name string
---@param percent number
---@return boolean
local function statBelow(name, percent)
	local value = stat(name)
	return value ~= nil and value.Value <= value.MaxValue * percent
end

---@return boolean
local function isCarnivore()
	local character = getCharacter()
	local passives = character and character:GetAttribute("ssv_Passives")
	return type(passives) == "string" and passives:find("Carnivore") ~= nil
end

---Carnivores can't eat plants, so only thirst counts for them.
---@return boolean
local function needsFood()
	return statBelow("Water", 0.25) or (statBelow("Stomach", 0.25) and not isCarnivore())
end

---Eat food from our inventory until our stomach is full.
local function eatFromInventory()
	local backpack = localPlayer:FindFirstChild("Backpack")
	local humanoid = getHumanoid()
	if not backpack or not humanoid or isCarnivore() then
		return
	end

	for _, name in next, FOODS do
		local tool = backpack:FindFirstChild(name)
		if not tool or not statBelow("Stomach", 0.95) then
			continue
		end

		humanoid:EquipTool(tool)
		task.wait(0.3)

		for _ = 1, 30 do
			if not tool.Parent or not active() or not statBelow("Stomach", 0.95) then
				break
			end

			pcall(function()
				tool:Activate()
			end)

			task.wait(1)
		end

		pcall(function()
			humanoid:UnequipTools()
		end)
	end
end

---@return Instance?
local function nearestWell()
	local root = getRoot()
	local folder = workspace.Terrain:FindFirstChild("Water")
	if not root or not folder then
		return nil
	end

	local closest, closestDistance = nil, nil

	for _, well in next, folder:GetChildren() do
		if not well.Name:match("DrinkingWater") then
			continue
		end

		local distance = (root.Position - well:GetPivot().Position).Magnitude

		if not closestDistance or distance < closestDistance then
			closest, closestDistance = well, distance
		end
	end

	return closest
end

---Refill hunger (pomars) and thirst (well) in the Eastern Luminant.
local function refillFood()
	setStage(TEXT.stageFood)

	eatFromInventory()

	if statBelow("Stomach", 0.95) and not isCarnivore() then
		local ingredients = workspace:FindFirstChild("Ingredients")

		for _, pomar in next, ingredients and ingredients:GetChildren() or {} do
			if not active() or not statBelow("Stomach", 0.95) then
				break
			end

			local prompt = pomar:IsA("BasePart") and pomar.Name:match("Pomar") and pomar:FindFirstChild("InteractPrompt")
			if not prompt then
				continue
			end

			safeTween(pomar.CFrame, 170)

			waitUntil(function()
				local root = getRoot()
				if root then
					root.CFrame = pomar.CFrame
				end

				firePrompt(prompt)

				return not prompt.Parent
			end, 5)

			eatFromInventory()
		end
	end

	if not active() or not statBelow("Water", 0.95) then
		return
	end

	local well = nearestWell()

	safeTween(well and well:GetPivot() or SARAMED_WELL, 170)

	waitUntil(function()
		if well then
			firePrompt(well:FindFirstChild("InteractPrompt", true))
		else
			pressKey(Enum.KeyCode.E)
		end

		return not statBelow("Water", 0.95)
	end, 30)
end

---Travel to Malisae and enter the Saramed dungeon alone.
local function enterSaramed()
	if needsFood() then
		refillFood()

		if not active() then
			return
		end
	end

	setStage(TEXT.stageTravel)

	safeTween(SARAMED_NPC, 170)

	if not active() then
		return
	end

	setStage(TEXT.stageEntering)

	local npcs = workspace:WaitForChild("NPCs")
	local malisae = npcs:WaitForChild("Malisae", 15)
	if not malisae then
		return PveFarm.hop(TEXT.reasonTimeout)
	end

	local playerGui = localPlayer:WaitForChild("PlayerGui")

	waitUntil(function()
		firePrompt(malisae:FindFirstChild("InteractPrompt"))
		task.wait(0.4)

		local dialogue = playerGui:FindFirstChild("DialogueGui")
		return dialogue ~= nil and dialogue.Enabled
	end, 15)

	task.wait(1)

	pcall(function()
		replicatedStorage.Requests.SendDialogue:FireServer({ choice = "Enter alone." })
	end)

	-- We should be teleported into the dungeon; the script resumes from pfdata there.
	task.wait(30)

	PveFarm.hop(TEXT.reasonTimeout)
end

---@return boolean
local function hasPickaxe()
	local backpack = localPlayer:FindFirstChild("Backpack")
	local character = getCharacter()
	return (backpack and backpack:FindFirstChild("Pickaxe")) ~= nil or (character and character:FindFirstChild("Pickaxe")) ~= nil
end

---@return boolean
local function mobsExist()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return false
	end

	for _, model in next, live:GetChildren() do
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		if model:GetAttribute("MOB_rich_name") and humanoid and humanoid.Health > 0 then
			return true
		end
	end

	return false
end

---@return Model?
local function closestMob()
	local live = workspace:FindFirstChild("Live")
	local root = getRoot()
	if not live or not root then
		return nil
	end

	local closest, closestDistance = nil, math.huge

	for _, model in next, live:GetChildren() do
		if not model:IsA("Model") or model == getCharacter() then
			continue
		end

		if model.Name:sub(1, 1) ~= "." and not model:GetAttribute("MOB_rich_name") then
			continue
		end

		local mobRoot = model:FindFirstChild("HumanoidRootPart")
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		if not mobRoot or not humanoid or humanoid.Health <= 0 then
			continue
		end

		local torso = model:FindFirstChild("Torso")
		if torso and torso:FindFirstChild("RagdollAttach") then
			continue
		end

		local distance = (mobRoot.Position - root.Position).Magnitude

		if distance < closestDistance then
			closest, closestDistance = model, distance
		end
	end

	return closest
end

---Sit above (or under, for buncles & knights) a mob and swing until it dies or we're low.
---@param target Model
local function killMob(target)
	local targetRoot = target:FindFirstChild("HumanoidRootPart")
	if not targetRoot then
		return
	end

	drawWeapon()

	tween(targetRoot.CFrame, 170).wait()

	local name = target.Name:lower()
	local under = name:find("buncle") ~= nil or name:find("knight") ~= nil
	local deadline = os.clock() + MOB_TIMEOUT

	spawnTracked(function()
		while active() and target.Parent and targetRoot.Parent do
			local dt = task.wait()
			local root = getRoot()
			local position = targetRoot.Position
			local clamped = CFrame.new(position.X, math.clamp(position.Y, 0, 1000), position.Z)
			local goal = under and clamped * CFrame.new(0, -attachDistance, 0) * CFrame.Angles(math.rad(90), 0, 0)
				or clamped * CFrame.new(0, attachDistance, 0) * CFrame.Angles(math.rad(-90), 0, 0)

			if root then
				local offset = goal.Position - root.Position

				root.AssemblyLinearVelocity = Vector3.zero

				-- Far away (mob got knocked back): move at 100 studs/s instead of snapping.
				if offset.Magnitude > 30 then
					root.CFrame = CFrame.new(root.Position + offset.Unit * math.min(100 * dt, offset.Magnitude))
				else
					root.CFrame = goal
				end
			end
		end
	end)

	swingAt(target, function()
		return healthBelow(minHealth) or os.clock() >= deadline
	end)
end

---@param target BasePart
local function mineOre(target)
	tween(target.CFrame, 170).wait()

	local prompt = target:FindFirstChild("InteractPrompt")

	for _ = 1, 60 do
		if not active() or not target.Parent then
			return
		end

		local root = getRoot()
		if root then
			root.CFrame = target.CFrame
		end

		firePrompt(prompt)
		task.wait()
	end

	waitUntil(function()
		return not target:FindFirstChild("InteractPrompt")
	end, 5)
end

---@return BasePart?
local function closestOre()
	local root = getRoot()
	if not root then
		return nil
	end

	local closest, closestDistance = nil, math.huge

	for _, ore in next, workspace:GetDescendants() do
		if not ore:IsA("MeshPart") or not ore.Name:match("MagmaOre") or not ore:FindFirstChild("InteractPrompt") then
			continue
		end

		local distance = (root.Position - ore.Position).Magnitude

		if distance < closestDistance then
			closest, closestDistance = ore, distance
		end
	end

	return closest
end

---@return Instance
local function deepdrill()
	return workspace:WaitForChild("Deepdrill", 30)
end

---@return boolean
local function fuelFull()
	local ok, full = pcall(function()
		return deepdrill().DungeonDrill.FuelPort.Display.SurfaceGui.Bar.BackgroundColor3:ToHex() == FUEL_FULL_COLOR
	end)
	return ok and full
end

local function depositOre()
	local hit = deepdrill().DungeonDrill.FuelPort.Hit

	tween(hit.CFrame, 170).wait()
	task.wait(1)
end

---Press the closest drill switch to go down a floor.
local function startFloor()
	setStage(TEXT.stageDescending)

	local drill = deepdrill()
	local root = getRoot()
	local dungeonSwitch = drill.DungeonDrill.Switch
	local elevatorSwitch = drill.Drillevator.Switch
	local switch = dungeonSwitch

	if (elevatorSwitch.Case.Position - root.Position).Magnitude < (dungeonSwitch.Case.Position - root.Position).Magnitude then
		switch = elevatorSwitch
	end

	tween(switch.Case.CFrame, 170).wait()
	task.wait(1)
	firePrompt(switch:FindFirstChild("InteractPrompt"))
	task.wait(2)
end

---Clear the floor's mobs, mine ore until the drill is fuelled, then loot the chest.
local function clearFloor()
	setStage(TEXT.stageFighting)

	waitUntil(mobsExist, 45)

	local deadline = os.clock() + 300

	while active() and mobsExist() and not healthBelow(minHealth) and os.clock() < deadline do
		local mob = closestMob()

		if mob then
			setStage(TEXT.stageFighting)
			killMob(mob)
		end

		task.wait(0.1)
	end

	if not active() or healthBelow(minHealth) then
		return
	end

	setStage(TEXT.stageMining)

	for _ = 1, 6 do
		local ore = nil

		waitUntil(function()
			ore = closestOre()
			return ore ~= nil
		end, 15)

		if not ore or not active() then
			break
		end

		setStage(TEXT.stageMining)
		mineOre(ore)
	end

	depositOre()

	-- Sanity itching can make us drop ore, so keep mining until the fuel bar is full.
	deadline = os.clock() + 120

	while active() and not fuelFull() and os.clock() < deadline do
		local ore = closestOre()

		setStage(TEXT.stageMining)

		if ore then
			mineOre(ore)
		end

		depositOre()
	end

	if not active() then
		return
	end

	grabChest(1000)

	cycles = cycles + 1
	errors = 0

	saveState()
end

---Ride the radio back up to the surface and rest if we're hurt.
local function resetDrill()
	setStage(TEXT.stageResetting)

	local drill = deepdrill()
	local switch = drill.DungeonDrill.Switch
	local radio = drill.DungeonDrill.Radio
	local playerGui = localPlayer:WaitForChild("PlayerGui")

	waitUntil(function()
		tween(switch.Case.CFrame, 170).wait()
		firePrompt(radio:FindFirstChild("InteractPrompt"))

		return playerGui:FindFirstChild("ChoicePrompt") ~= nil
	end, 20)

	local prompt = playerGui:FindFirstChild("ChoicePrompt")
	if prompt then
		pcall(function()
			prompt.Choice:FireServer(true)
		end)
	end

	local destructibles = workspace:WaitForChild("Destructibles", 30)
	local campfire = destructibles and destructibles:WaitForChild("Campfire", 30)
	local campfirePart = campfire and campfire:FindFirstChildWhichIsA("BasePart")
	if not campfirePart then
		return
	end

	waitUntil(function()
		local root = getRoot()
		return root ~= nil and (campfirePart.Position - root.Position).Magnitude <= 150
	end, 180)

	if active() and healthBelow(REST_HEALTH) then
		tween(campfirePart.CFrame, 170).wait()
		restAt(campfirePart)
	end
end

---Leave the dungeon by dying at the exit so we can eat in the overworld.
local function leaveDungeon()
	setStage(TEXT.stageLeaving)

	local exit = deepdrill():FindFirstChild("DungeonExit")
	if exit then
		tween(exit.CFrame, 170).wait()
	end

	task.wait(3)

	pcall(function()
		replicatesignal(localPlayer.Kill)
	end)

	task.delay(1, function()
		local humanoid = getHumanoid()
		local root = getRoot()

		if humanoid and humanoid.Health > 1 and root then
			root.CFrame = root.CFrame * CFrame.new(0, 9e9, 0)
		end
	end)

	waitUntil(function()
		return false
	end, 15)
end

local function runSaramedDungeon()
	if not deepdrill() then
		return PveFarm.hop(TEXT.reasonTimeout)
	end

	if not hasPickaxe() then
		Logger.notify(TEXT.needPickaxe)
		setStage(TEXT.stagePickaxe)

		while PveFarm.running and not hasPickaxe() do
			stageDeadline = os.clock() + STAGE_TIMEOUT
			task.wait(1)
		end
	end

	-- Drop any ore we're holding into the fuel port.
	spawnTracked(function()
		while PveFarm.running do
			local character = getCharacter()
			local ore = character and character:FindFirstChild("MagmaOre")
			local ok, hit = pcall(function()
				return workspace.Deepdrill.DungeonDrill.FuelPort.Hit
			end)

			if ore and ok and hit then
				touch(ore:FindFirstChildWhichIsA("BasePart") or ore, hit)
			end

			task.wait(0.2)
		end
	end)

	while active() do
		if needsFood() then
			eatFromInventory()

			if needsFood() then
				return leaveDungeon()
			end
		end

		startFloor()

		if not active() then
			return
		end

		clearFloor()

		if not active() then
			return
		end

		local depthText = ""
		pcall(function()
			depthText = deepdrill().DungeonDrill.DepthDisplay.SurfaceGui.TextLabel.Text
		end)

		if healthBelow(minHealth) or depthText:find("2.00", 1, true) then
			resetDrill()
		end
	end
end

---------------------------------------------------------------------------------------------------
-- Auto Moon's Eyrie.
---------------------------------------------------------------------------------------------------

---@param range number
---@return Model?
local function closestKnight(range)
	local live = workspace:FindFirstChild("Live")
	local root = getRoot()
	if not live or not root then
		return nil
	end

	local closest, closestDistance = nil, range

	for _, mob in next, live:GetChildren() do
		local mobRoot = mob:IsA("Model") and mob.Name:lower():find("moonknight") and mob:FindFirstChild("HumanoidRootPart")
		if not mobRoot then
			continue
		end

		local distance = (root.Position - mobRoot.Position).Magnitude

		if distance < closestDistance then
			closest, closestDistance = mob, distance
		end
	end

	return closest
end

---@return boolean
local function inDanger()
	local humanoid = getHumanoid()
	local expiration = humanoid and humanoid:GetAttribute("DangerExpiration")
	return expiration ~= nil and expiration > 0
end

---Pick up loot drops near us.
local function collectDrops()
	local thrown = workspace:FindFirstChild("Thrown")
	local root = getRoot()
	if not thrown or not root then
		return
	end

	for _, model in next, thrown:GetChildren() do
		local drop = model:IsA("Model") and model:FindFirstChild("LootDrop")
		if not drop or (root.Position - drop.Position).Magnitude > 100 or playerNear(drop.Position) then
			continue
		end

		tween(drop.CFrame, 120).wait()

		waitUntil(function()
			local current = getRoot()
			if current then
				touch(drop, current)
			end

			return not drop.Parent
		end, 3)
	end
end

---Fight a moonknight from above, jumping higher while it kicks.
---@param knight Model
local function killKnight(knight)
	local knightRoot = knight:FindFirstChild("HumanoidRootPart")
	local humanoid = knight:FindFirstChildOfClass("Humanoid")
	if not knightRoot or not humanoid then
		return
	end

	setStage(TEXT.stageKnight)

	drawWeapon()

	tween(knightRoot.CFrame, 170).wait()

	local kicking = false
	local animator = knight:FindFirstChild("Animator", true)

	if animator then
		track(animator.AnimationPlayed:Connect(function(animationTrack)
			local id = animationTrack.Animation and animationTrack.Animation.AnimationId or ""

			for _, kick in next, KNIGHT_KICK_ANIMATIONS do
				if id:find(kick, 1, true) then
					kicking = true

					task.delay(2, function()
						kicking = false
					end)
				end
			end
		end))
	end

	spawnTracked(function()
		while active() and knight.Parent and knightRoot.Parent do
			local root = getRoot()

			if root then
				root.AssemblyLinearVelocity = Vector3.zero
				root.CFrame = knightRoot.CFrame * CFrame.new(0, kicking and 60 or 10, 0) * CFrame.Angles(math.rad(-90), 0, 0)
			end

			task.wait()
		end
	end)

	local lastHealth = humanoid.Health
	local lastChange = os.clock()

	swingAt(knight, function()
		if humanoid.Health ~= lastHealth then
			lastHealth = humanoid.Health
			lastChange = os.clock()
		end

		return playerNear() or healthBelow(EYRIE_MIN_HEALTH) or os.clock() - lastChange >= KNIGHT_STALL_TIMEOUT
	end)

	if not active() or playerNear() then
		return
	end

	task.wait(2)

	collectDrops()
end

---Fly straight up until the danger timer runs out.
local function toSafety()
	setStage(TEXT.stageSafety)

	local deadline = os.clock() + 90

	while PveFarm.running and not hopping and alive() and inDanger() and os.clock() < deadline do
		local root = getRoot()
		if root then
			root.AssemblyLinearVelocity = Vector3.zero
			root.CFrame = root.CFrame * CFrame.new(0, math.random(8000, 10000), 0)
		end

		task.wait(0.5)
	end
end

local function runEyrie()
	if healthBelow(EYRIE_MIN_HEALTH) then
		setStage(TEXT.stageTravel)
		safeTween(EYRIE_CAMPFIRE, 170)

		local thrown = workspace:FindFirstChild("Thrown")
		local campfirePart = active() and thrown and closestCampfire(thrown)

		if campfirePart then
			restAt(campfirePart)
		end
	end

	if not active() then
		return
	end

	setStage(TEXT.stageTravel)

	local marker = replicatedStorage.MarkerWorkspace.AreaMarkers["Moon's Eyrie"].AreaMarker
	safeTween(marker.CFrame, 170)

	if not active() then
		return
	end

	setStage(TEXT.stageDoor)

	local door = workspace:WaitForChild("MoonseyeDoor", 30)
	if not door then
		return PveFarm.hop(TEXT.reasonTimeout)
	end

	drawWeapon()

	safeTween(door.CFrame * CFrame.new(0, -5, 0), 170)

	if not active() then
		return
	end

	local playerGui = localPlayer:WaitForChild("PlayerGui")

	waitUntil(function()
		local npc = workspace.NPCs:FindFirstChild("MoonDoor")
		firePrompt(npc and npc:FindFirstChild("InteractPrompt"))
		task.wait(0.4)

		local dialogue = playerGui:FindFirstChild("DialogueGui")
		return dialogue ~= nil and dialogue.Enabled
	end, 15)

	pcall(function()
		replicatedStorage.Requests.SendDialogue:FireServer({ choice = "[Interact]" })
	end)

	tween(door.CFrame * CFrame.new(0, 0, -100), 170).wait()

	waitUntil(function()
		return playerNear() or closestKnight(60) ~= nil
	end, 3)

	if not active() or playerNear() then
		return
	end

	local knight = closestKnight(60)

	if knight then
		killKnight(knight)

		if active() and not playerNear() and not healthBelow(EYRIE_MIN_HEALTH) then
			task.wait(0.5)
			grabChest(300)
		end
	end

	-- Finish off any other knight that showed up.
	local other = active() and not playerNear() and closestKnight(3000)

	if other then
		killKnight(other)
	end

	if knight then
		cycles = cycles + 1
		errors = 0
		saveState()
	end
end

---------------------------------------------------------------------------------------------------
-- Routine.
---------------------------------------------------------------------------------------------------

---Figure out where we are and run one pass of the farm.
local function checkArea()
	requestStart()

	if not PveFarm.running or hopping then
		return
	end

	if inCharacterCreation() then
		Logger.notify(TEXT.needCharacter)
		return PveFarm.stop()
	end

	if game.PlaceId == DEPTHS_PLACE_ID then
		Logger.notify(TEXT.inDepths)
		return PveFarm.stop()
	end

	setToggle("NoStun", true)

	if PveFarm.mode == "saramed" then
		if game.PlaceId == EASTERN_PLACE_ID then
			return enterSaramed()
		end

		if game.PlaceId == DUNGEON_PLACE_ID and workspace:WaitForChild("Deepdrill", 30) then
			return runSaramedDungeon()
		end
	elseif game.PlaceId == EASTERN_PLACE_ID then
		runEyrie()

		if not PveFarm.running or hopping then
			return
		end

		if alive() and inDanger() then
			toSafety()
		end

		return PveFarm.hop(TEXT.reasonCycleComplete)
	end

	Logger.notify(TEXT.notInPlace)
	PveFarm.stop()
end

local function runRoutine()
	while PveFarm.running and not hopping do
		local ok, err = pcall(checkArea)

		if not PveFarm.running or hopping then
			return
		end

		if not ok then
			Logger.warn("(PveFarm) %s", tostring(err))

			errors = errors + 1
			saveState()

			if errors >= MAX_CONSECUTIVE_ERRORS then
				Logger.notify(TEXT.tooManyErrors)
				return PveFarm.stop()
			end

			if alive() then
				return PveFarm.hop(TEXT.reasonError)
			end
		end

		-- We died (or the pass finished) without leaving the server, so wait to respawn and go again.
		if not alive() then
			setStage(TEXT.stageDead)
		end

		task.wait(1)
	end
end

---Start a PvE farm. Pass a mode to start fresh, or nothing to resume after a hop.
---@param mode string? "saramed" or "eyrie"
function PveFarm.start(mode)
	if PveFarm.running then
		return
	end

	-- A wipe is in progress; the Wipe module will bring us back afterwards.
	if PersistentData.get("wdata") then
		return
	end

	local data = PersistentData.get("pfdata")

	if mode then
		if PersistentData.get("tfdata") or PersistentData.get("afdata") then
			return Logger.notify(TEXT.otherFarm)
		end

		data = {
			mode = mode,
			slot = currentSlot(),
			started = os.time(),
			cycles = 0,
			errors = 0,
			health = optionNumber("SaramedMinHealth", 25) / 100,
			attach = optionNumber("SaramedAttachDistance", 8),
		}
	elseif not data then
		return
	elseif data.slot and currentSlot() and data.slot ~= currentSlot() then
		Logger.notify(TEXT.wrongSlot)
		return PveFarm.stop()
	end

	PveFarm.mode = data.mode
	startSlot = data.slot
	startedAt = data.started or os.time()
	cycles = data.cycles or 0
	errors = data.errors or 0
	minHealth = data.health or 0.25
	attachDistance = data.attach or 8
	hopping = false

	PveFarm.running = true

	saveState()

	AntiAFK.start("PveFarm")

	setToggle("Fly", true)
	setToggle("NoClip", true)
	setToggle("NoFallDamage", true)

	buildOverlay()

	titleLabel.Text = PveFarm.mode == "eyrie" and TEXT.eyrieTitle or TEXT.saramedTitle

	setStage(TEXT.stageLoading)
	updateOverlay()

	screenGui.Enabled = true

	track(runService.Heartbeat:Connect(updateOverlay))

	spawnTracked(runRoutine)

	Logger.notify(TEXT.started, titleLabel.Text)
end

---Stop the PvE farm and clear its saved state.
function PveFarm.stop()
	if not PveFarm.running and not PersistentData.get("pfdata") then
		return
	end

	teardown()

	PersistentData.set("pfdata", nil)

	Logger.notify(TEXT.stopped)
end

-- Return PveFarm module.
return PveFarm

end)
__bundle_register("Game/PlayerScanning", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Player scanning is handled here.
local PlayerScanning = {
	scanQueue = {},
	scanDataCache = {},
	friendCache = {},
	waitingForLoad = {},
	readyList = {},
	scanning = false,
}

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.ModeratorMap
local ModeratorMap = require("Game/ModeratorMap")

-- Deepwoken Staff group.
local STAFF_GROUP_ID = 5212858

-- Services.
local players = game:GetService("Players")
local collectionService = game:GetService("CollectionService")
local runService = game:GetService("RunService")

-- Instances.
local moderatorSound = CoreGuiManager.imark(Instance.new("Sound"))

-- Maid.
local playerScanningMaid = Maid.new()

-- Timestamp.
local lastCheckedTimestamp = os.clock()
local lastPlayerScanTimestamp = os.clock()

-- Seen tools.
local seenTools = {}

---Fetch name.
local function fetchName(player)
	local spoofName = Configuration.expectToggleValue("InfoSpoofing")
		and Configuration.expectToggleValue("SpoofOtherPlayers")

	return spoofName and "[REDACTED]"
		or string.format("(%s) %s", player:GetAttribute("CharacterName") or "Unknown Character Name", player.Name)
end

---Partial look for string in list. Returns the string that got matched.
---@param list table<string, any>
---@param value string
---@return string?
local partialStringFind = LPH_NO_VIRTUALIZE(function(list, value)
	for _, str in next, list do
		if not value:match(str) then
			continue
		end

		return str
	end

	return nil
end)

---Check inventories for tools.
local function checkInventoriesForTools()
	for _, player in next, players:GetPlayers() do
		if not Configuration.expectToggleValue("NotifyItems") then
			continue
		end

		if player == players.LocalPlayer then
			continue
		end

		local backpack = player:FindFirstChild("Backpack")
		if not backpack then
			continue
		end

		local notifyItemsList = Options.NotifyItemsList and Options.NotifyItemsList.Values
		if not notifyItemsList then
			continue
		end

		-- Check if the player has any items that match the notify items list.
		for _, tool in next, backpack:GetChildren() do
			if seenTools[tool] then
				continue
			end

			local itemName = tool:GetAttribute("ItemName")
			if typeof(itemName) ~= "string" or itemName == "" then
				continue
			end

			local matchedString = partialStringFind(notifyItemsList, itemName)
			if not matchedString then
				continue
			end

			seenTools[tool] = matchedString

			Logger.longNotify("%s has item '%s' in their inventory.", fetchName(player), itemName)
		end

		-- If the matched string that filtered this item is no longer in the list, remove it.
		for tool, matched in next, seenTools do
			if table.find(notifyItemsList, matched) then
				continue
			end

			seenTools[tool] = nil
		end
	end

	lastCheckedTimestamp = os.clock()
end

---Run player scans.
local runPlayerScans = LPH_NO_VIRTUALIZE(function()
	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	for player, _ in next, PlayerScanning.scanQueue do
		if shared.Lycoris.dpscanning then
			continue
		end

		if not PlayerScanning.scanDataCache[player] then
			local handledSuccess, handledResult = nil, nil

			local unhandledSuccess, unhandledResult = pcall(function()
				handledSuccess, handledResult = PlayerScanning.getStaffRank(player)
			end)

			if not unhandledSuccess then
				Logger.warn(
					"Scan player %s ran into error '%s' while getting staff rank.",
					player.Name,
					unhandledResult
				)

				Logger.mnnotify("Failed to scan player %s for moderator status.", fetchName(player), unhandledResult)

				PlayerScanning.scanQueue[player] = nil

				continue
			end

			if not handledSuccess then
				continue
			end

			if Configuration.expectToggleValue("NotifyMod") and handledResult then
				Logger.mnnotify("%s is a staff member with the rank '%s' in group.", fetchName(player), handledResult)

				if Configuration.expectToggleValue("NotifyModSound") then
					moderatorSound.SoundId = "rbxassetid://6045346303"
					moderatorSound.PlaybackSpeed = 1
					moderatorSound.Volume = Configuration.expectToggleValue("NotifyModSoundVolume") or 10
					moderatorSound:Play()
				end
			end

			PlayerScanning.scanDataCache[player] = { staffRank = handledResult }
		end

		local backpack = player:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		if not collectionService:HasTag(backpack, "Loaded") or #backpack:GetChildren() < 1 then
			if not PlayerScanning.waitingForLoad[player] then
				Logger.warn("Player scanning is waiting for %s to load in the game.", fetchName(player))
			end

			PlayerScanning.waitingForLoad[player] = true

			continue
		end

		if
			Configuration.expectToggleValue("NotifyVoidWalker")
			and backpack:FindFirstChild("Talent:Voidwalker Contract")
		then
			Logger.longNotify("%s has the Voidwalker Contract talent.", fetchName(player))
		end

		PlayerScanning.scanQueue[player] = nil

		PlayerScanning.friendCache[player] = localPlayer:GetFriendStatus(player) == Enum.FriendStatus.Friend

		Logger.warn("Player scanning finished scanning %s in queue.", fetchName(player))
	end
end)

---Are there moderators in the server?
---@return table
function PlayerScanning.hasModerators()
	for _, scanData in next, PlayerScanning.scanDataCache do
		if not scanData.staffRank then
			continue
		end

		return true
	end

	return false
end

---Is a player an ally?
---@param player Player
---@return boolean
function PlayerScanning.isAlly(player)
	---@note: bruh we can call ReputationSystem
	local localPlayerGuild = players.LocalPlayer:GetAttribute("Guild")
	local usernameList = Options["UsernameList"]

	if usernameList then
		local displayNameFound = player and table.find(usernameList.Values, player.DisplayName)
		local usernameFound = player and table.find(usernameList.Values, player.Name)

		if displayNameFound or usernameFound then
			return true
		end
	end

	return PlayerScanning.friendCache[player]
		or ((localPlayerGuild and #localPlayerGuild >= 1) and player:GetAttribute("Guild") == localPlayerGuild)
end

---Get staff rank - nil if they're not a staff.
---@param player Player
---@return boolean, string?
function PlayerScanning.getStaffRank(player)
	local mapped = ModeratorMap[player.UserId]
	if mapped then
		return true, mapped
	end

	local rankSuccess, rank = pcall(player.GetRankInGroup, player, STAFF_GROUP_ID)
	if not rankSuccess then
		return false, rank
	end

	if typeof(rank) ~= "number" or rank <= 0 then
		return true, nil
	end

	local roleSuccess, role = pcall(player.GetRoleInGroup, player, STAFF_GROUP_ID)
	if not roleSuccess or typeof(role) ~= "string" then
		return true, "Staff"
	end

	return true, role
end

---Update player scanning.
---@note: Request will yield - so we need a debounce to prevent multiple scan loops.
---@note: We must defer the error back to the caller and reset the scanning debounce so errors will not break the scanning loop.
function PlayerScanning.update()
	if os.clock() - lastCheckedTimestamp >= 5.0 then
		checkInventoriesForTools()
	end

	if os.clock() - lastPlayerScanTimestamp <= 1.0 then
		return
	end

	lastPlayerScanTimestamp = os.clock()

	if PlayerScanning.scanning then
		return
	end

	PlayerScanning.scanning = true

	local success, result = pcall(runPlayerScans)

	PlayerScanning.scanning = false

	if success then
		return
	end

	return error(result)
end

---On friend status changed.
---@param player Player
---@param status Enum.FriendStatus
function PlayerScanning.friend(player, status)
	PlayerScanning.friendCache[player] = status == Enum.FriendStatus.Friend
end

---On player added.
---@param player Player
function PlayerScanning.onPlayerAdded(player)
	if player == players.LocalPlayer then
		return
	end

	PlayerScanning.scanQueue[player] = true
end

---On player removing.
---@param player Player
function PlayerScanning.onPlayerRemoving(player)
	PlayerScanning.scanQueue[player] = nil
	PlayerScanning.scanDataCache[player] = nil
	PlayerScanning.friendCache[player] = nil
	PlayerScanning.waitingForLoad[player] = nil
end

---Initialize PlayerScanning.
function PlayerScanning.init()
	-- Signals.
	local playerAddedSignal = Signal.new(players.PlayerAdded)
	local playerRemovingSignal = Signal.new(players.PlayerRemoving)
	local renderSteppedSignal = Signal.new(runService.RenderStepped)
	local friendStatusChanged = Signal.new(players.LocalPlayer.FriendStatusChanged)

	-- Connect events.
	playerScanningMaid:add(friendStatusChanged:connect("PlayerScanning_OnFriendStatusChanged", PlayerScanning.friend))
	playerScanningMaid:add(renderSteppedSignal:connect("PlayerScanning_Update", PlayerScanning.update))
	playerScanningMaid:add(playerAddedSignal:connect("PlayerScanning_OnPlayerAdded", PlayerScanning.onPlayerAdded))
	playerScanningMaid:add(
		playerRemovingSignal:connect("PlayerScanning_OnPlayerRemoving", PlayerScanning.onPlayerRemoving)
	)

	-- Run event(s) for existing players.
	for _, player in next, players:GetPlayers() do
		PlayerScanning.onPlayerAdded(player)
	end
end

---Detach PlayerScanning.
function PlayerScanning.detach()
	playerScanningMaid:clean()
end

-- Return PlayerScanning module.
return PlayerScanning

end)
