	function Library:SetWatermark(Text)
		local X, Y = Library:GetTextBounds(Text, Library.Font, 14)
		Library.WatermarkText.Text = Text
		Library.Watermark.Size = UDim2.new(0, X + 15, 0, (Y * 1.5) + 3)
	end

	function Library:ManuallyManagedNotify(Text)
		if shared.Lycoris.silent then
			return
		end

		local NotifScale = tonumber(Options["NotificationScale"] and Options["NotificationScale"].Value) or 100
		NotifScale = NotifScale / 100

		local ScaledTextSize = 14 * NotifScale
		local XSize, YSize = Library:GetTextBounds(Text, Library.Font, ScaledTextSize)

		YSize = YSize + (7 * NotifScale)

		local NotifyOuter = Library:Create("Frame", {
			BorderColor3 = Color3.new(0, 0, 0),
			Position = UDim2.new(0, 100, 0, 10),
			Size = UDim2.new(0, 0, 0, YSize),
			ClipsDescendants = true,
			ZIndex = 100,
			Parent = Library.NotificationArea,
		})

		local NotifyInner = Library:Create("Frame", {
			BackgroundColor3 = Library.MainColor,
			BorderColor3 = Library.OutlineColor,
			BorderMode = Enum.BorderMode.Inset,
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = 101,
			Parent = NotifyOuter,
		})

		Library:AddToRegistry(NotifyInner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
		}, true)

		local InnerFrame = Library:Create("Frame", {
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			Position = UDim2.new(0, 1, 0, 1),
			Size = UDim2.new(1, -2, 1, -2),
			ZIndex = 102,
			Parent = NotifyInner,
		})

		local Gradient = Library:Create("UIGradient", {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Library:GetDarkerColor(Library.MainColor)),
				ColorSequenceKeypoint.new(1, Library.MainColor),
			}),
			Rotation = -90,
			Parent = InnerFrame,
		})

		Library:AddToRegistry(Gradient, {
			Color = function()
				return ColorSequence.new({
					ColorSequenceKeypoint.new(0, Library:GetDarkerColor(Library.MainColor)),
					ColorSequenceKeypoint.new(1, Library.MainColor),
				})
			end,
		})

		local NotifyLabel = Library:CreateLabel({
			Position = UDim2.new(0, 4, 0, 0),
			Size = UDim2.new(1, -4, 1, 0),
			Text = Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextSize = ScaledTextSize,
			ZIndex = 103,
			Parent = InnerFrame,
		})

		local LeftColor = Library:Create("Frame", {
			BackgroundColor3 = Library.AccentColor,
			BorderSizePixel = 0,
			Position = UDim2.new(0, -1, 0, -1),
			Size = UDim2.new(0, 3, 1, 2),
			ZIndex = 104,
			Parent = NotifyOuter,
		})

		Library:AddToRegistry(LeftColor, {
			BackgroundColor3 = "AccentColor",
		}, true)

		local TweenTime = 0.4
		local ScaledXSize = XSize + 8 + 4

		pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, ScaledXSize, 0, YSize), "Out", "Quad", TweenTime, true)

		local function TweenOut()
			pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, 0, 0, YSize), "Out", "Quad", TweenTime, true)

			task.wait(TweenTime)

			NotifyOuter:Destroy()
		end

		local Connection = nil
		local Connection2 = nil

		Connection = InnerFrame.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				TweenOut()
				Connection:Disconnect()
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
				pcall(setclipboard, Text)
				Library:Notify("Copied to clipboard!", 1.5)
			end
		end)

		Connection2 = InnerFrame.MouseEnter:Connect(function()
			if game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
				TweenOut()
				Connection2:Disconnect()
			end
		end)

		return TweenOut
	end

	function Library:Notify(Text, Time)
		if shared.Lycoris.silent then
			return
		end

		local NotifScale = tonumber(Options["NotificationScale"] and Options["NotificationScale"].Value) or 100
		NotifScale = NotifScale / 100

		local ScaledTextSize = 14 * NotifScale
		local XSize, YSize = Library:GetTextBounds(Text, Library.Font, ScaledTextSize)

		YSize = YSize + (7 * NotifScale)

		local NotifyOuter = Library:Create("Frame", {
			BorderColor3 = Color3.new(0, 0, 0),
			Position = UDim2.new(0, 100, 0, 10),
			Size = UDim2.new(0, 0, 0, YSize),
			ClipsDescendants = true,
			ZIndex = 100,
			Parent = Library.NotificationArea,
		})

		local NotifyInner = Library:Create("Frame", {
			BackgroundColor3 = Library.MainColor,
			BorderColor3 = Library.OutlineColor,
			BorderMode = Enum.BorderMode.Inset,
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = 101,
			Parent = NotifyOuter,
		})

		Library:AddToRegistry(NotifyInner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
		}, true)

		local InnerFrame = Library:Create("Frame", {
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			Position = UDim2.new(0, 1, 0, 1),
			Size = UDim2.new(1, -2, 1, -2),
			ZIndex = 102,
			Parent = NotifyInner,
		})

		local Gradient = Library:Create("UIGradient", {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Library:GetDarkerColor(Library.MainColor)),
				ColorSequenceKeypoint.new(1, Library.MainColor),
			}),
			Rotation = -90,
			Parent = InnerFrame,
		})

		Library:AddToRegistry(Gradient, {
			Color = function()
				return ColorSequence.new({
					ColorSequenceKeypoint.new(0, Library:GetDarkerColor(Library.MainColor)),
					ColorSequenceKeypoint.new(1, Library.MainColor),
				})
			end,
		})

		local NotifyLabel = Library:CreateLabel({
			Position = UDim2.new(0, 4, 0, 0),
			Size = UDim2.new(1, -4, 1, 0),
			Text = Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextSize = ScaledTextSize,
			ZIndex = 103,
			Parent = InnerFrame,
		})

		local LeftColor = Library:Create("Frame", {
			BackgroundColor3 = Library.AccentColor,
			BorderSizePixel = 0,
			Position = UDim2.new(0, -1, 0, -1),
			Size = UDim2.new(0, 3, 1, 2),
			ZIndex = 104,
			Parent = NotifyOuter,
		})

		Library:AddToRegistry(LeftColor, {
			BackgroundColor3 = "AccentColor",
		}, true)

		local MovingReallyFast = Time and (Time - 0.8) <= 0.3 or false
		local TweenTime = MovingReallyFast and 0.1 or 0.4

		local ScaledXSize = XSize + 8 + 4

		pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, ScaledXSize, 0, YSize), "Out", "Quad", TweenTime, true)

		local function TweenOut()
			pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, 0, 0, YSize), "Out", "Quad", TweenTime, true)

			task.wait(TweenTime)

			NotifyOuter:Destroy()
		end

		local Connection = nil
		local Connection2 = nil

		Connection = InnerFrame.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				TweenOut()
				Connection:Disconnect()
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
				pcall(setclipboard, Text)
				Library:Notify("Copied to clipboard!", 1.5)
			end
		end)

		Connection2 = InnerFrame.MouseEnter:Connect(function()
			if game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
				TweenOut()
				Connection2:Disconnect()
			end
		end)

		task.spawn(function()
			task.wait(Time or 5)

			TweenOut()
		end)
	end

	function Library:CreateWindow(...)
		local Arguments = { ... }
		local Config = { AnchorPoint = Vector2.zero }

		if type(...) == "table" then
			Config = ...
		else
			Config.Title = Arguments[1]
			Config.AutoShow = Arguments[2] or false
		end

		if type(Config.Title) ~= "string" then
			Config.Title = "No title"
		end
		if type(Config.TabPadding) ~= "number" then
			Config.TabPadding = 0
		end
		if type(Config.MenuFadeTime) ~= "number" then
			Config.MenuFadeTime = 0.2
		end

		if typeof(Config.Position) ~= "UDim2" then
			Config.Position = UDim2.fromOffset(175, 50)
		end
		if typeof(Config.Size) ~= "UDim2" then
			Config.Size = UDim2.fromOffset(550, 600)
		end

		if Config.Center then
			Config.AnchorPoint = Vector2.new(0.5, 0.5)
			Config.Position = UDim2.fromScale(0.5, 0.5)
		end

		local Window = {
			Tabs = {},
		}

		local Outer = Library:Create("Frame", {
			AnchorPoint = Config.AnchorPoint,
			BackgroundColor3 = Color3.new(0, 0, 0),
			BorderSizePixel = 0,
			Position = Config.Position,
			Size = Config.Size,
			Visible = false,
			ZIndex = 1,
			Parent = ScreenGui,
		})

		Library:MakeDraggable(Outer, 25)

		local GlowLayers = {}
		local GlowConfig = {
			{ BaseExpand = 0.166, BaseTrans = 0.75 },
			{ BaseExpand = 0.388, BaseTrans = 0.85 },
			{ BaseExpand = 0.666, BaseTrans = 0.92 },
			{ BaseExpand = 1.0,   BaseTrans = 0.96 },
		}

		for i, cfg in ipairs(GlowConfig) do
			local GlowLayer = Library:Create("Frame", {
				Name = "GlowLayer" .. i,
				AnchorPoint = Vector2.new(0.5, 0.5),
				BackgroundColor3 = Library.AccentColor,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Position = UDim2.new(0.5, 0, 0.5, 0),
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 0,
				Visible = false,
				Parent = Outer,
			})

			Library:Create("UICorner", {
				Name = "UICorner",
				CornerRadius = UDim.new(0, 0),
				Parent = GlowLayer,
			})

			GlowLayers[i] = GlowLayer
		end

		local BreatheStep = 0
		local GlowShown = false
		Library:GiveSignal(RunService.RenderStepped:Connect(function(deltaTime)
			local enabled = Toggles and Toggles.EdgeGlow and Toggles.EdgeGlow.Value or false
			if not enabled then
				if GlowShown then
					for _, layer in ipairs(GlowLayers) do
						layer.Visible = false
					end
					GlowShown = false
				end
				return
			end

			GlowShown = true

			local color = Options and Options.EdgeGlowColor and Options.EdgeGlowColor.Value or Library.AccentColor
			local maxSize = Options and Options.EdgeGlowSize and Options.EdgeGlowSize.Value or 60
			local opacity = Options and Options.EdgeGlowOpacity and Options.EdgeGlowOpacity.Value / 100 or 1
			local breathe = Toggles and Toggles.EdgeGlowBreathe and Toggles.EdgeGlowBreathe.Value or false

			local currentSize = maxSize
			local currentOpacity = opacity

			if breathe then
				BreatheStep = BreatheStep + deltaTime * 2
				local breatheMod = 0.8 + (math.sin(BreatheStep) * 0.5 + 0.5) * 0.2
				currentSize = maxSize * breatheMod
				currentOpacity = opacity * breatheMod
			end

			for i, cfg in ipairs(GlowConfig) do
				local layer = GlowLayers[i]
				local corner = layer.UICorner
				
				layer.Visible = true
				layer.BackgroundColor3 = color
				
				local targetAlpha = (1 - cfg.BaseTrans) * currentOpacity
				layer.BackgroundTransparency = 1 - targetAlpha
				
				local expand = math.round(cfg.BaseExpand * currentSize)
				layer.Size = UDim2.new(1, expand * 2, 1, expand * 2)
				corner.CornerRadius = UDim.new(0, expand)
			end
		end))

		local Inner = Library:Create("Frame", {
			BackgroundColor3 = Library.MainColor,
			BorderColor3 = Library.AccentColor,
			BorderMode = Enum.BorderMode.Inset,
			Position = UDim2.new(0, 1, 0, 1),
			Size = UDim2.new(1, -2, 1, -2),
			ZIndex = 1,
			Parent = Outer,
		})

		Library:AddToRegistry(Inner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "AccentColor",
		})

		local WindowLabel = Library:CreateLabel({
			Position = UDim2.new(0, 7, 0, 0),
			Size = UDim2.new(0, 0, 0, 25),
			Text = Config.Title or "",
			TextColor3 = Library.AccentColor,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 1,
			Parent = Inner,
		})

		Library:AddToRegistry(WindowLabel, {
			TextColor3 = "AccentColor",
		})

		do
			local SearchOuter = Library:Create("Frame", {
				BackgroundColor3 = Color3.new(0, 0, 0),
				BorderColor3 = Color3.new(0, 0, 0),
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, -7, 0, 4),
				Size = UDim2.new(0, 140, 0, 17),
				ZIndex = 2,
				Parent = Inner,
			})

			Library:AddToRegistry(SearchOuter, {
				BorderColor3 = "Black",
			})

			local SearchInner = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BorderColor3 = Library.OutlineColor,
				BorderMode = Enum.BorderMode.Inset,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 3,
				Parent = SearchOuter,
			})

			Library:AddToRegistry(SearchInner, {
				BackgroundColor3 = "MainColor",
				BorderColor3 = "OutlineColor",
			})

			Library:OnHighlight(
				SearchOuter,
				SearchOuter,
				{ BorderColor3 = "AccentColor" },
				{ BorderColor3 = "Black" }
			)

			local SearchBox = Library:Create("TextBox", {
				BackgroundTransparency = 1,
				Position = UDim2.new(0, 5, 0, 0),
				Size = UDim2.new(1, -8, 1, 0),
				FontFace = Library.Font,
				PlaceholderColor3 = Color3.fromRGB(190, 190, 190),
				PlaceholderText = "Search...",
				Text = "",
				TextColor3 = Library.FontColor,
				TextSize = 14,
				TextStrokeTransparency = 0,
				TextXAlignment = Enum.TextXAlignment.Left,
				ClearTextOnFocus = false,
				ZIndex = 4,
				Parent = SearchInner,
			})

			Library:ApplyTextStroke(SearchBox)
			Library:AddToRegistry(SearchBox, {
				TextColor3 = "FontColor",
			})

			local MAX_SEARCH_RESULTS = 10

			local ListOuter = Library:Create("Frame", {
				BackgroundColor3 = Color3.new(0, 0, 0),
				BorderColor3 = Color3.new(0, 0, 0),
				ZIndex = 40,
				Visible = false,
				Name = "SearchListOuter",
				Parent = ScreenGui,
			})

			local ListInner = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BorderColor3 = Library.OutlineColor,
				BorderMode = Enum.BorderMode.Inset,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 41,
				Parent = ListOuter,
			})

			Library:AddToRegistry(ListInner, {
				BackgroundColor3 = "MainColor",
				BorderColor3 = "OutlineColor",
			})

			local Scrolling = Library:Create("ScrollingFrame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				CanvasSize = UDim2.new(0, 0, 0, 0),
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 41,
				Parent = ListInner,

				TopImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
				BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",

				ScrollBarThickness = 3,
				ScrollBarImageColor3 = Library.AccentColor,
			})

			Library:AddToRegistry(Scrolling, {
				ScrollBarImageColor3 = "AccentColor",
			})

			Library:Create("UIListLayout", {
				Padding = UDim.new(0, 0),
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = Scrolling,
			})

			local RESULTS_WIDTH = 220

			local function PositionResults()
				ListOuter.Position = UDim2.fromOffset(
					SearchOuter.AbsolutePosition.X + SearchOuter.AbsoluteSize.X - RESULTS_WIDTH,
					SearchOuter.AbsolutePosition.Y + SearchOuter.AbsoluteSize.Y + 1
				)
			end

			local function RecalculateListPosition()
				if not ListOuter.Visible then
					return
				end

				PositionResults()
			end

			SearchOuter:GetPropertyChangedSignal("AbsolutePosition"):Connect(RecalculateListPosition)

			local function CloseResults()
				ListOuter.Visible = false
				Library.OpenedFrames[ListOuter] = nil
			end

			local function OpenResults()
				PositionResults()
				ListOuter.Visible = true
				Library.OpenedFrames[ListOuter] = true
			end

			local function RunSearch()
				local Query = SearchBox.Text:gsub("^%s+", ""):gsub("%s+$", "")

				for _, Element in next, Scrolling:GetChildren() do
					if not Element:IsA("UIListLayout") then
						Element:Destroy()
					end
				end

				if Query == "" then
					CloseResults()
					return
				end

				local LowerQuery = Query:lower()
				local QueryWords = {}
				for Word in LowerQuery:gmatch("%S+") do
					table.insert(QueryWords, Word)
				end

				local Matches = {}

				for _, Entry in next, Library.SearchIndex do
					local Haystack = ((Entry.GroupName or "") .. " " .. Entry.Text):lower()

					local AllWordsMatch = true
					for _, Word in next, QueryWords do
						if not Haystack:find(Word, 1, true) then
							AllWordsMatch = false
							break
						end
					end

					if AllWordsMatch then
						table.insert(Matches, Entry)
					end
				end

				if #Matches == 0 then
					CloseResults()
					return
				end

				table.sort(Matches, function(a, b)
					local aTextHit = a.Text:lower():find(LowerQuery, 1, true) ~= nil
					local bTextHit = b.Text:lower():find(LowerQuery, 1, true) ~= nil
					if aTextHit ~= bTextHit then
						return aTextHit
					end
					return false
				end)

				if #Matches > MAX_SEARCH_RESULTS then
					for i = #Matches, MAX_SEARCH_RESULTS + 1, -1 do
						Matches[i] = nil
					end
				end

				for _, Entry in next, Matches do
					local ResultLabel = Entry.GroupName and (Entry.GroupName .. ": " .. Entry.Text) or Entry.Text

					local Button = Library:Create("Frame", {
						BackgroundColor3 = Library.MainColor,
						BorderColor3 = Library.OutlineColor,
						BorderMode = Enum.BorderMode.Middle,
						Size = UDim2.new(1, -1, 0, 20),
						ZIndex = 43,
						Active = true,
						Parent = Scrolling,
					})

					Library:AddToRegistry(Button, {
						BackgroundColor3 = "MainColor",
						BorderColor3 = "OutlineColor",
					})

					local ButtonLabel = Library:CreateLabel({
						Active = false,
						Size = UDim2.new(1, -6, 1, 0),
						Position = UDim2.new(0, 6, 0, 0),
						TextSize = 13,
						Text = ResultLabel,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
						ZIndex = 45,
						Parent = Button,
					})

					Library:OnHighlight(
						Button,
						Button,
						{ BorderColor3 = "AccentColor", ZIndex = 44 },
						{ BorderColor3 = "OutlineColor", ZIndex = 43 }
					)

					ButtonLabel.InputBegan:Connect(function(Input)
						if Input.UserInputType == Enum.UserInputType.MouseButton1 then
							SearchBox.Text = ""
							CloseResults()
							Library:JumpToSearchResult(Entry)
						end
					end)
				end

				local Count = #Matches
				Scrolling.CanvasSize = UDim2.fromOffset(0, (Count * 20) + 1)
				ListOuter.Size = UDim2.fromOffset(RESULTS_WIDTH, math.clamp(Count * 20, 0, MAX_SEARCH_RESULTS * 20) + 1)

				OpenResults()
			end

			SearchBox:GetPropertyChangedSignal("Text"):Connect(RunSearch)

			SearchBox.Focused:Connect(function()
				if SearchBox.Text ~= "" then
					RunSearch()
				end
			end)

			InputService.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 and ListOuter.Visible then
					local AbsPos, AbsSize = ListOuter.AbsolutePosition, ListOuter.AbsoluteSize
					local SearchPos, SearchSize = SearchOuter.AbsolutePosition, SearchOuter.AbsoluteSize

					local OverList = Mouse.X >= AbsPos.X
						and Mouse.X <= AbsPos.X + AbsSize.X
						and Mouse.Y >= AbsPos.Y
						and Mouse.Y <= AbsPos.Y + AbsSize.Y

					local OverSearch = Mouse.X >= SearchPos.X
						and Mouse.X <= SearchPos.X + SearchSize.X
						and Mouse.Y >= SearchPos.Y
						and Mouse.Y <= SearchPos.Y + SearchSize.Y

					if not OverList and not OverSearch then
						CloseResults()
					end
				end
			end)
