    ["Ascension"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local distance = self:distance(self.entity)
        	local when = 1020 + distance * 10

        	local hitbox = Vector3.new(30, 35, 30)

        	timing.mat = when + 500
        	timing.hitbox = hitbox

        	local action = Action.new()
        	action._when = when
        	action._type = "Forced Full Dodge"
        	action.hitbox = hitbox
        	action.name = string.format("(%.2f) Dynamic Ascension Timing", distance)

        	return self:action(timing, action)
        end
    end,
    ["AstralWind"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.uif = true
        	timing.pfh = true
        	timing.pfht = 0.25
        	timing.phd = true
        	timing.phds = 1.0

        	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
        	local speed = hrp and math.clamp(hrp.Velocity.Magnitude, 0, 25) or 0

        	local action = Action.new()
        	action._when = 300
        	action._type = "Parry"
        	action.hitbox = Vector3.new(40, 20, 40) + Vector3.new(0, 0, speed)
        	action.name = "Astral Wind Parry"
        	return self:action(timing, action)
        end
    end,
    ["BigBell"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Utility.Finder
        local Finder = getfenv().Finder

        ---Module function.
        ---@param self PartDefender
        ---@param timing PartTiming
        return function(self, timing)
        	if Finder.entity("knell") then
        		return
        	end

        	timing.duih = true
        	timing.fhb = false
        	timing.hso = 0
        	timing.hitbox = Vector3.new(20, 20, 20)

        	local action = Action.new()
        	action._when = 500
        	action._type = "Dodge"
        	action.hitbox = Vector3.new(20, 20, 20)
        	action.name = "Dynamic Big Bell Timing"
        	return self:action(timing, action)
        end
    end,
    ["BlindingDawn"] = function()
        ---@module Modules.Globals.Waiter
        local Waiter = getfenv().Waiter

        ---@module Features.Combat.Objects.RepeatInfo
        local RepeatInfo = getfenv().RepeatInfo

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local humanoid = self.entity:FindFirstChild("Humanoid")
        	if not humanoid then
        		return
        	end

        	local animator = humanoid:FindFirstChild("Animator")
        	if not animator then
        		return
        	end

        	timing.fhb = false
        	timing.duih = true
        	timing.rpue = true
        	timing._rsd = 500
        	timing._rpd = 150
        	timing.iae = true
        	timing.mat = 2300
        	timing.hitbox = Vector3.new(60, 20, 60)

        	local track = Waiter.fet("rbxassetid://10622235550", animator)
        	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
        	info.track = track
        	self:srpue(self.entity, timing, info)
        end
    end,
