    ["GenericTelegraph"] = function()
        ---@type Action
        local Action = getfenv().Action

        -- Services.
        local players = game:GetService("Players")

        ---Module function.
        ---@param self EffectDefender
        ---@param timing EffectTiming
        return function(self, timing)
            local selfCharacter = players.LocalPlayer.Character;
        	if self.owner ~= selfCharacter then
        		return
        	end


            local effectData = self.data;

            local telegraphType = effectData.telegraph;
            local part = effectData.part;

            if part and part:IsDescendantOf(selfCharacter) and part.Name == "HumanoidRootPart" then --Weapon Manual Telegraph (caster: self.character & part: hrp)
                local dur = effectData.dur; --note: if you are working on this module, the real game code has a or 0.5 here, but it's not needed for weapon manual.
                if dur ~= 1 then
                    return;
                end

                if not table.find({
                    "dodge_only",
                    "block_only",
                    "parry_only"
                }, telegraphType) then return; end

        	    self:hook("target", function(_)
        	    	return true
        	    end)

        	    local action = Action.new()
        	    action._when = 950 -- it is 1s but we do want to parry earlier due to the fact the user might not have 'Ping Compensation' on.
        	    action._type = telegraphType == "dodge_only" and "Dodge" or "Parry"
        	    action.ihbc = true
        	    action.name = "Dynamic Weapon Manual Timing"       

                return self:action(timing, action)
            end

        	return;
        end
    end,
    ["GlacialArc"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self PartDefender
        ---@param timing PartTiming
        return function(self, timing)
        	-- Glacial Arc starts creating new parts that are ordered least to smallest
        	local model = self.part.Parent
        	if not model then
        		return
        	end

        	if #model:GetChildren() <= 2 then
        		return
        	end

        	if self:distance(self.part) >= 15 then
        		return
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Start Block"
        	action.ihbc = true
        	action.name = "Dynamic Glacial Arc Timing"
        	self:action(timing, action)

        	local actionEnd = Action.new()
        	actionEnd._when = 300
        	actionEnd._type = "End Block"
        	actionEnd.ihbc = true
        	actionEnd.name = "Dynamic Glacial Arc End Timing"
        	return self:action(timing, actionEnd)
        end
    end,
    ["GolemBeam"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self EffectDefender
        ---@param timing EffectTiming
        return function(self, timing)
        	local entity = self.owner
        	if not entity then
        		return
        	end

        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	---@todo: Prime Golem is a special case.
