        		return self:action(timing, action)
        	end
        end
    end,
    ["IceForgeCast"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        ---Check if cubes have all been destroyed.
        local function areCubesStillAlive(cubes)
        	for _, cube in next, cubes do
        		if not cube.Parent then
        			continue
        		end

        		if cube.Transparency >= 0.5 then
        			continue
        		end

        		return true
        	end

        	return false
        end

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local entity = self.entity
        	if not entity then
        		return
        	end

        	local hrp = entity:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	timing.iae = false

        	if hrp:WaitForChild("REP_SOUND_15214335898", 0.1) then
        		local action = Action.new()
        		action._when = 0
        		action._type = "Parry"
        		action.hitbox = Vector3.new(50, 50, 50)
        		action.name = "Storm Blades Timing"
        		return self:action(timing, action)
        	end

        	TaskSpawner.spawn("IceCubes_Spawn", function()
        		task.wait(1.9 - Latency.rtt())

        		if not hrp:FindFirstChild("REP_SOUND_13692212248") then
        			return
        		end

        		local thrown = workspace:FindFirstChild("Thrown")
        		if not thrown then
        			return
        		end

        		local cubes = {}

        		for _, part in pairs(thrown:GetChildren()) do
        			if not part:IsA("BasePart") then
        				continue
        			end

        			if not part.Name:match("Cube") then
        				continue
        			end

        			cubes[#cubes + 1] = part
        		end

        		if #cubes <= 0 then
        			return
        		end

        		local fcube = cubes[1]

        		repeat
        			task.wait()
        		until fcube:FindFirstChild("BodyVelocity")

        		local blockStarted = false

        		timing.mat = 5000
        		timing.iae = true

        		while task.wait() do
        			for _, cube in next, cubes do
        				if not areCubesStillAlive(cubes) then
        					local secondAction = Action.new()
        					secondAction._when = 0
        					secondAction._type = "End Block"
        					secondAction.name = "Ice Cubes End"
        					secondAction.ihbc = true
        					return self:action(timing, secondAction)
        				end

        				if not cube or not cube.Parent then
        					continue
        				end

        				if self:distance(cube) >= 16 then
        					continue
        				end

        				if blockStarted then
        					continue
        				end

        				local action = Action.new()
        				action._when = 0
        				action._type = "Start Block"
        				action.name = "Ice Cubes Start"
        				action.ihbc = true
        				self:action(timing, action)

        				blockStarted = true
        			end
        		end
        	end)
        end
    end,
    ["IceForgeNewCharge"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	task.spawn(function()
        		local thrown = workspace:FindFirstChild("Thrown")
        		if not thrown then
        			return
        		end

        		local tracker = ProjectileTracker.new(function(candidate)
        			return candidate.Name == "IceShuriken"
        		end)

        		task.wait(0.9 - Latency.rtt())

        		if self:distance(self.entity) <= 15 then
        			local action = Action.new()
        			action._type = "Start Block"
        			action._when = 800
        			action.name = "Ice Forge Close Timing"
        			action.fhb = true
        			action.ihbc = false
        			self:action(timing, action)

        			local actionTwo = Action.new()
        			actionTwo._type = "End Block"
        			actionTwo._when = 1000
        			actionTwo.fhb = true
        			actionTwo.ihbc = false
        			self:action(timing, actionTwo)
        		end

        		local action = Action.new()
        		action._when = 0
        		action._type = "Start Block"
