    ["WhalingCrit"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local distance = self:distance(self.entity)
        	local action = Action.new()
        	action._when = math.min(300 + distance * 6.5)
        	action._type = "Parry"
        	action.hitbox = Vector3.new(17, 10, 18)
        	action.name = string.format("(%.2f) Dynamic Whaling Crit Timing", distance)
        	return self:action(timing, action)
        end
    end,
    ["WindBlade"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name == "WindSlashProjectile"
        	end)

        	task.wait(0.5 - Latency.rtt())

        	if self:distance(self.entity) <= 20 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 0
        		action.name = "Arc Beam Close Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.name = "Wind Slash Part"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = true
        	pt.name = "WindSlashProjectile"
        	pt.hitbox = Vector3.new(10, 10, 10)
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
    end,
    ["WindCarve"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---@class Signal
        local Signal = getfenv().Signal

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:CarveWind{{Wind Carve}}")
        	local range = data.stratus * 1.4 + data.cloud * 0.9

        	timing.ffh = true
        	timing.pfh = true
        	timing.fhb = true
        	timing.rpue = false
        	timing.duih = true
        	timing.hitbox = Vector3.new(20 + range, 20 + range, 20 + range)

        	local action = Action.new()
        	action._when = 400
        	action._type = "Start Block"
        	action.name = "Wind Carve Start"
        	self:action(timing, action)

        	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
        	if not hrp then
        		return
        	end

        	local onDescendantAdded = Signal.new(self.entity.DescendantAdded)

        	self.tmaid:add(onDescendantAdded:connect("WindCarve_StopCarve", function(child)
        		if child.Name == "StopCarve" then
        			local actionTwo = Action.new()
        			actionTwo._when = 0
        			actionTwo._type = "End Block"
        			actionTwo.ihbc = true
        			actionTwo.name = "Wind Carve End"
        			self:action(timing, actionTwo)
        		end
        	end))
        end
    end,
    ["WindGun"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.ffh = true

        	local distance = self:distance(self.entity)
        	local action = Action.new()
        	action._when = 400

        	if distance >= 20 then
        		action._when = 550
        	end

        	action._type = "Parry"
        	action.name = string.format("(%.2f) Dynamic Wind Gun Timing", distance)
        	action.hitbox = Vector3.new(30, 20, 40)

        	return self:action(timing, action)
        end
    end,
    ["WraithclawCrit"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Features.Combat.Objects.RepeatInfo
        local RepeatInfo = getfenv().RepeatInfo

        ---@module Game.Latency
        local Latency = getfenv().Latency

