        	end

        	local actionTwo = Action.new()
        	actionTwo._when = 650
        	actionTwo._type = "Parry"
        	actionTwo.ihbc = true
        	actionTwo.name = string.format("(%.2f) Far Wyrm Crit Timing", dist)
        	return self:action(timing, actionTwo)
        end
    end
