		hso = self.hso,
		nvfb = self.nvfb,
		bfht = self.bfht,
		rpue = self.rpue,
		rsd = self._rsd,
		rpd = self._rpd,
		nbfb = self.nbfb,
		ibi = self.ibi,
		iapf = self.iapf,
		uif = self.uif,
		rsc = self.rsc,
		rsaid = self.rsaid,
		rsaw = self.rsaw,
	}
end

---Create new Timing object.
---@param values table?
---@return Timing
function Timing.new(values)
	local self = setmetatable({}, Timing)

	self.tag = "Undefined"
	self.name = "N/A"
	self.imdd = 0
	self.imxd = 0
	self.smn = false
	self.punishable = 0
	self.after = 0
	self.rpue = false
	self._rsd = 0
	self._rpd = 0
	self.duih = false
	self.actions = ActionContainer.new()
	self.hitbox = Vector3.zero
	self.umoa = false
	self.srpn = false
	self.smod = "N/A"
	self.aatk = false
	self.fhb = true
	self.ndfb = false
	self.hso = 0
	self.nvfb = false
	self.bfht = 0.3
	self.nbfb = false
	self.ibi = false
	self.iapf = false
	self.uif = false
	self.rsc = false
	self.rsaid = ""
	self.rsaw = 4.0

	if values then
		self:load(values)
	end

	return self
end

-- Return Timing module.
return Timing

