__bundle_register("Features/Game/RevealAnimations", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Maid = require("Utility/Maid")

	local Signal = require("Utility/Signal")

	local Configuration = require("Utility/Configuration")

	local Logger = require("Utility/Logger")

	local SaveManager = require("Game/Timings/SaveManager")

	local RevealAnimations = {}

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")
	local collectionService = game:GetService("CollectionService")

	local revealAnimationsMaid = Maid.new()

	local renderStepped = Signal.new(runService.RenderStepped)

	local lastUpdateTime = 0
	local updateThrottleTime = 0.03
	local weightValue = 1
	local modifiedAnimations = {}

	local function checkAnimationTrack(animationTrack)
		local priority = animationTrack.Priority

		if
			priority == Enum.AnimationPriority.Action2
			or priority == Enum.AnimationPriority.Action3
			or priority == Enum.AnimationPriority.Action4
		then
			return 0
		end

		if priority == Enum.AnimationPriority.Core or priority == Enum.AnimationPriority.Idle then
			return weightValue
		end

		if animationTrack.WeightCurrent <= 0.01 then
			return weightValue
		end

		local threshold = tonumber(Configuration.expectOptionValue("RevealWeightThreshold")) or 0.5

		if animationTrack.WeightCurrent < threshold then
			return weightValue
		end

		return nil
	end

	local function updateRevealAnimations()
		if not Configuration.expectToggleValue("RevealAnimations") then
			for animationTrack in pairs(modifiedAnimations) do
				if animationTrack.Parent then
					pcall(function()
						collectionService:RemoveTag(animationTrack, "RevealAnimationsModified")
					end)
				end
			end
			modifiedAnimations = {}
			return
		end

		local currentTime = os.clock()

		if currentTime - lastUpdateTime < updateThrottleTime then
			return
		end

		lastUpdateTime = currentTime

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		for _, player in ipairs(players:GetPlayers()) do
			if player == localPlayer then
				continue
			end

			local character = player.Character

			if not character then
				continue
			end

			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid then
				continue
			end

			local animator = humanoid:FindFirstChildOfClass("Animator")
			if not animator then
				continue
			end

			local success, animationTracks = pcall(function()
				return animator:GetPlayingAnimationTracks()
			end)

			if not success then
				continue
			end

			for _, animationTrack in ipairs(animationTracks) do
				if SaveManager.as:index(tostring(animationTrack.Animation.AnimationId)) ~= nil then
					continue
				end

				local adjustWeight = checkAnimationTrack(animationTrack)

				if adjustWeight ~= nil then
					pcall(function()
						animationTrack:AdjustWeight(adjustWeight, 0)
						if not collectionService:HasTag(animationTrack, "RevealAnimationsModified") then
							collectionService:AddTag(animationTrack, "RevealAnimationsModified")
							modifiedAnimations[animationTrack] = true
						end
					end)
				end
			end
		end
	end

	function RevealAnimations.init()
		if not LPH_OBFUSCATED or shared.Lycoris.verbose then
			Logger.warn("RevealAnimations initialized.")
		end
		revealAnimationsMaid:add(renderStepped:connect("RevealAnimations_RenderStepped", updateRevealAnimations))
	end

	function RevealAnimations.detach()
		Logger.warn("RevealAnimations detached.")
		for animationTrack in pairs(modifiedAnimations) do
			if animationTrack.Parent then
				pcall(function()
					collectionService:RemoveTag(animationTrack, "RevealAnimationsModified")
				end)
			end
		end
		modifiedAnimations = {}
		revealAnimationsMaid:clean()
	end

	return RevealAnimations
end)

end)
__bundle_register("Features/Game/FakeVoid", function(require, _LOADED, __bundle_register, __bundle_modules)
local FakeVoid = {}

local Signal = require("Utility/Signal")

local Logger = require("Utility/Logger")

local Configuration = require("Utility/Configuration")

local Maid = require("Utility/Maid")

local runService = game:GetService("RunService")
local players = game:GetService("Players")

local fakeVoidMaid = Maid.new()

local preSimulation = Signal.new(runService.PreSimulation)
local workspaceDescendantAdded = Signal.new(workspace.DescendantAdded)
local workspaceDescendantRemoving = Signal.new(workspace.DescendantRemoving)

local TRIGGER_HEIGHT = 100
local DEPTHS_ROOF_Y = -600
local DEPTHS_RAY_LENGTH = 1000
local ROOF_OFFSET = 3
local TELEPORT_COOLDOWN = 1.0

local killPlanes = {}

local lastTeleport = 0

local function isKillPlane(instance)
	return instance:IsA("BasePart") and (instance.Name == "KillPlane" or instance.Name:match("Chasm") ~= nil)
end

local function getBounds(part)
	local cframe = part.CFrame
	if cframe.Y ~= cframe.Y or math.abs(cframe.Y) == math.huge then
		return nil
	end

	local size = part.Size
	local right, up, look = cframe.RightVector, cframe.UpVector, cframe.LookVector
	local extents = Vector3.new(
		math.abs(right.X) * size.X + math.abs(up.X) * size.Y + math.abs(look.X) * size.Z,
		math.abs(right.Y) * size.X + math.abs(up.Y) * size.Y + math.abs(look.Y) * size.Z,
		math.abs(right.Z) * size.X + math.abs(up.Z) * size.Y + math.abs(look.Z) * size.Z
	) / 2

	return { min = cframe.Position - extents, max = cframe.Position + extents }
end

local function onWorkspaceDescendantAdded(descendant)
	if not isKillPlane(descendant) then
		return
	end

	killPlanes[descendant] = getBounds(descendant) or false
end

local function onWorkspaceDescendantRemoving(descendant)
	killPlanes[descendant] = nil
end

local function getKillPlaneY(position)
	local fpdh = workspace:GetAttribute("OriginalFPDH") or workspace.FallenPartsDestroyHeight
	local best = (typeof(fpdh) == "number" and fpdh == fpdh) and fpdh or nil

	for part, cached in next, killPlanes do
		local data = getBounds(part) or cached
		if not data then
			continue
		end

		killPlanes[part] = data

		if position.X < data.min.X or position.X > data.max.X then
			continue
		end

		if position.Z < data.min.Z or position.Z > data.max.Z then
			continue
		end

		if not best or data.max.Y > best then
			best = data.max.Y
		end
	end

	return best
end

local function getDepthsRoofY(position)
	local map = workspace:FindFirstChild("Map")
	if not map then
		return DEPTHS_ROOF_Y
	end

	local params = RaycastParams.new()
	params.FilterDescendantsInstances = { map }
	params.FilterType = Enum.RaycastFilterType.Include

	local result = workspace:Raycast(
		Vector3.new(position.X, DEPTHS_ROOF_Y, position.Z),
		Vector3.new(0, -DEPTHS_RAY_LENGTH, 0),
		params
	)

	return result and result.Position.Y + ROOF_OFFSET or DEPTHS_ROOF_Y
end

local function updateFakeVoid()
	if not Configuration.expectToggleValue("FakeVoid") then
		return
	end

	if os.clock() - lastTeleport <= TELEPORT_COOLDOWN then
		return
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	local rootPart = character and character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	local position = rootPart.Position

	local killPlaneY = getKillPlaneY(position)

	if not killPlaneY or position.Y - killPlaneY > TRIGGER_HEIGHT then
		return
	end

	local targetY = getDepthsRoofY(position)
	if targetY - killPlaneY <= TRIGGER_HEIGHT then
		return
	end

	lastTeleport = os.clock()

	Logger.warn(
		"(FakeVoid) Teleporting from Y %.1f to Y %.1f (kill Y %.1f).",
		position.Y,
		targetY,
		killPlaneY
	)

	rootPart.CFrame = rootPart.CFrame + Vector3.new(0, targetY - position.Y, 0)
	rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
end

function FakeVoid.init()
	for _, descendant in next, workspace:GetDescendants() do
		onWorkspaceDescendantAdded(descendant)
	end

	fakeVoidMaid:add(
		workspaceDescendantAdded:connect("FakeVoid_WorkspaceDescendantAdded", onWorkspaceDescendantAdded)
	)
	fakeVoidMaid:add(
		workspaceDescendantRemoving:connect("FakeVoid_WorkspaceDescendantRemoving", onWorkspaceDescendantRemoving)
	)
	fakeVoidMaid:add(preSimulation:connect("FakeVoid_PreSimulation", updateFakeVoid))

	if not LPH_OBFUSCATED or shared.Lycoris.verbose then
		local count = 0

		for _ in next, killPlanes do
			count = count + 1
		end

		Logger.warn("FakeVoid initialized with %d kill planes.", count)
	end
end

function FakeVoid.detach()
	fakeVoidMaid:clean()
	table.clear(killPlanes)

	Logger.warn("FakeVoid detached.")
end

return FakeVoid

end)
__bundle_register("Features/Game/OptimizeGame", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local OptimizeGame = {}

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	-- Maids.
	local optimizeGameMaid = Maid.new()

	-- Low-res replacement texture.
	local LOW_TEXTURE = "rbxassetid://130143779"

	-- State.
	local initialized = false
	local ranVisuals = false

	---Downgrade a single instance for performance.
	---@param obj Instance
	local function downgradeObject(obj)
		-- Simplify parts: plastic material, no reflectance, no cast shadow.
		if obj:IsA("BasePart") then
			obj.Material = Enum.Material.Plastic
			obj.Reflectance = 0
			obj.CastShadow = false
		end

		-- Replace textures/decals with low-res placeholder.
		if obj:IsA("Texture") or obj:IsA("Decal") then
			obj.Texture = LOW_TEXTURE
		elseif obj:IsA("SurfaceAppearance") then
			obj.ColorMap = LOW_TEXTURE
			obj.MetalnessMap = ""
			obj.RoughnessMap = ""
			obj.NormalMap = ""
		end

		-- Disable particle emitters.
		if obj:IsA("ParticleEmitter") then
			obj.Enabled = false
			obj.Rate = 0
			obj.Speed = NumberRange.new(0)
		end

		-- Disable lights.
		if obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
			obj.Enabled = false
			obj.Brightness = 0
			obj.Range = 2
		end
	end

	---Run the aggressive optimization pass.
	function OptimizeGame.runAggressive()
		if ranVisuals then
			return
		end
		ranVisuals = true
		task.spawn(function()
			local count = 0
			for _, obj in next, game:GetDescendants() do
				downgradeObject(obj)
				count = count + 1
				-- Yield every 1000 objects to prevent freezing.
				if count % 1000 == 0 then
					task.wait()
				end
			end
			Logger.notify("Aggressively optimized %d objects.", count)
		end)
	end

	---SeaClient optimization.
	local function setupSeaClient()
		local sea_client_func

		local function scan(objects)
			for _, object in next, objects do
				if typeof(object) ~= "function" or not getinfo(object).source:find("SeaClient") then
					continue
				end
				if not table.find(getconstants(object), "getWaveAt") then
					continue
				end

				sea_client_func = object
				break
			end
		end
		
		if filtergc then
			pcall(function()
				scan(filtergc("function", {
					IgnoreExecutor = false,
					Constants = { "getWaveAt" },
				}))
			end)
		end

		if not sea_client_func then
			scan(getgc(false))
		end

		if not sea_client_func then
			return Logger.warn("Failed to get SeaClient function.")
		end

		local last_allowed_call = tick()
		local old
		old = hookfunction(sea_client_func, function(...)
			if Configuration.expectToggleValue("OptimizeGame") and tick() - last_allowed_call < 1 / 20 then
				return
			end

			last_allowed_call = tick()
			return old(...)
		end)
	end

	-- LowGraphics attribute state.
	local forcingLowGraphics = false
	local originalLowGraphics = nil

	---Force the LowGraphics player attribute while optimizing. WorldClient skips ambient VFX
	---(wind trails, glitches, bubbles, meteors, sail bones, despawn tweens) when it's set.
	---@param enabled boolean
	local function updateLowGraphics(enabled)
		local localPlayer = game:GetService("Players").LocalPlayer
		if not localPlayer then
			return
		end

		if enabled then
			if not forcingLowGraphics then
				originalLowGraphics = localPlayer:GetAttribute("LowGraphics")
				forcingLowGraphics = true
			end

			if localPlayer:GetAttribute("LowGraphics") ~= true then
				localPlayer:SetAttribute("LowGraphics", true)
			end
		elseif forcingLowGraphics then
			forcingLowGraphics = false
			localPlayer:SetAttribute("LowGraphics", originalLowGraphics)
		end
	end

	---WorldClient optimization.
	local function setupWorldClient()
		local last_world_client_func
		local function apply()
			task.wait(1)

			local hi = "WorldClient"
			local cns = getconnections(game:GetService("RunService").PreRender)

			local conn
			for _, object in next, cns do
				local func = object.Function
				if not func or not getinfo(func).source:find(hi) then
					continue
				end

				if last_world_client_func == func then
					return task.delay(1, apply)
				end

				last_world_client_func = func
				object:Disable()
				conn = object
			end

			if not conn then
				return
			end

			---@note: Re-enable the original connection on cleanup, otherwise WorldClient stays dead after detach.
			optimizeGameMaid["WorldClientRestore"] = function()
				pcall(conn.Enable, conn)
			end

			local last_update = tick()
			optimizeGameMaid["WorldClientRender"] = game:GetService("RunService").PreRender:Connect(function()
				local now = tick()
				local enabled = Configuration.expectToggleValue("OptimizeGame")

				updateLowGraphics(enabled)

				if enabled and now - last_update < 1 / 15 then
					return
				end

				---@note: WorldClient feeds this into SmoothDamp - it must be the real elapsed time.
				local dt = now - last_update
				last_update = now

				return conn:Fire(dt)
			end)
		end

		apply()

		-- Watch for new WorldClient UIs.
		local players = game:GetService("Players")
		local localPlayer = players.LocalPlayer
		if localPlayer then
			optimizeGameMaid:add(localPlayer.PlayerGui.ChildAdded:Connect(function(object)
				if not Configuration.expectToggleValue("OptimizeGame") then
					return
				end
				if object.Name ~= "WorldClient" then
					return
				end

				apply()
			end))
		end
	end

	---Initialize OptimizeGame.
	function OptimizeGame.init()
		if initialized then
			return
		end
		initialized = true

		-- Setup hooks/throttles (these handle toggle state internally).
		task.spawn(setupSeaClient)
		task.spawn(setupWorldClient)

		-- Hook DescendantAdded.
		local descendantAddedSignal = Signal.new(game.DescendantAdded)
		optimizeGameMaid:add(descendantAddedSignal:connect("OptimizeGame_DescendantAdded", function(obj)
			if ranVisuals then
				task.defer(downgradeObject, obj)
			end
		end))

		if not LPH_OBFUSCATED or shared.Lycoris.verbose then
			Logger.warn("OptimizeGame initialized.")
		end
	end

	---Detach OptimizeGame.
	function OptimizeGame.detach()
		optimizeGameMaid:clean()
		updateLowGraphics(false)
		initialized = false
		ranVisuals = false
		Logger.warn("OptimizeGame detached.")
	end

	-- Return OptimizeGame module.
	return OptimizeGame
end)()

end)
__bundle_register("Features/Game/Teleport", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Teleport module.
---@note: Teleports in Deepwoken do not work the same. They lag you back, obviously. This is a utility module to handle repeatedly teleporting for a specific purpose.
local Teleport = { destination = nil, gdp = nil }

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")
local players = game:GetService("Players")

-- Maids.
local tmaid = Maid.new()

-- Constants
Teleport.activeTween = nil

-- Teleport state.
local RUBBERBAND_THRESHOLD = 1000
local teleportFrameCount = 0
local SPAM_FRAMES = 30
local PAUSE_FRAMES = 15
local STREAM_REQUEST_INTERVAL = 1.0
local REALM_ALIASES = {
	EasternLuminant = { "EastLuminant", "East Luminant", "EasternLuminant", "Eastern Luminant" },
	EtreanLuminant = { "EtreanLuminant", "Etrean Luminant" },
}
local REALM_TELEPORTER_PATHS = {
	{ "ValleyExit", "RealmTeleport" },
	{ "ValleyExit", "RealmTeleporter" },
}
local teleporterCache = {}
local streamRequestTimes = {}

---@note: Ported from Project Rain. Rather than waiting for the realm teleporter
local LUMINANT_TARGETS = {
	EasternLuminant = CFrame.new(
		-2637.4563,
		721.632935,
		-6722.51953,
		-0.757481456,
		0,
		-0.652856648,
		0,
		1,
		0,
		0.652856648,
		0,
		-0.757481456
	),
	EtreanLuminant = CFrame.new(-528.434814, 704.674194, -4760.4292),
}

local noClipSetByTeleport = false

---On player GUI descendant added.
---@param child Instance
local function onPlayerGuiDescendantAdded(child)
	if not child:IsA("TextLabel") then
		return
	end

	local coords = string.split(child.Text, ", ")
	local x, y, z = tonumber(coords[1]), tonumber(coords[2]), tonumber(coords[3])
	if not x or not y or not z then
		return
	end

	local position = Vector3.new(x, y, z)

	if (position - Vector3.new(-20000, 20000, -20000)).Magnitude <= 20 and Teleport.destination == "Voidheart" then
		return Teleport.stop()
	end

	if (position - Vector3.new(1596.1, 555.7, 2849.9)).Magnitude <= 20 and Teleport.destination == "LowerErisia" then
		return Teleport.stop()
	end

	if Teleport.gdp and (position - Teleport.gdp).Magnitude <= 20 and Teleport.destination == "GuildDoor" then
		return Teleport.stop()
	end
end

---Get guild doors from partial or exact name.
---@note: First instance is the entrance door. The second instance is the exit door.
---@param name string
---@return Instance?, Instance?
local function getGuildDoors(name)
	for _, instance in next, workspace:GetChildren() do
		if not instance.Name:match("GuildDoor") then
			continue
		end

		local guildName = instance:GetAttribute("GuildName")
		if not guildName then
			continue
		end

		if not guildName:lower():match(name:lower()) then
			continue
		end

		return instance, workspace:FindFirstChild(string.gsub(instance.Name, "GuildDoor", "GuildExitDoor"))
	end

	return nil
end

---Fire touch interest on a part.
---@param character Model
---@param part BasePart
local function fireTouchOn(character, part)
	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	pcall(firetouchinterest, hrp, part, 0)
	pcall(firetouchinterest, hrp, part, 1)
	pcall(firetouchinterest, hrp, part, 0)
	pcall(firetouchinterest, hrp, part, 1)
end

---@note: Ported from Project Rain -- deliberately no 'Realm' attribute check.
---@return BasePart?
local function getValleyRealmTeleport()
	local valleyExit = workspace:FindFirstChild("ValleyExit")
	if not valleyExit then
		return nil
	end

	local teleporter = valleyExit:FindFirstChild("RealmTeleport") or valleyExit:FindFirstChild("RealmTeleporter")
	if not teleporter or not teleporter:IsA("BasePart") then
		return nil
	end

	return teleporter
end

---@note: Ported from Project Rain. The game rubber-bands a character it thinks
---@param character Model
local function spoofMoveDirection(character)
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	pcall(sethiddenproperty, humanoid, "MoveDirectionInternal", Vector3.one)
end

---@note: Ported from Project Rain -- stops geometry from blocking the run.
local function ensureNoClip()
	if noClipSetByTeleport then
		return
	end

	if not Toggles or not Toggles.NoClip then
		return
	end

	if Toggles.NoClip.Value then
		return
	end

	noClipSetByTeleport = true
	Toggles.NoClip:SetValue(true)
end

local function restoreNoClip()
	if not noClipSetByTeleport then
		return
	end

	noClipSetByTeleport = false

	if Toggles and Toggles.NoClip then
		Toggles.NoClip:SetValue(false)
	end
end

---Reset teleport state.
local function resetTeleportState()
	teleportFrameCount = 0
	teleporterCache = {}
	streamRequestTimes = {}

	restoreNoClip()
end

---Request stream around a position.
---@param label string
---@param position Vector3
local function requestStreamAround(label, position)
	local timestamp = os.clock()
	local lastRequestTime = streamRequestTimes[label]
	if lastRequestTime and timestamp - lastRequestTime < STREAM_REQUEST_INTERVAL then
		return
	end

	streamRequestTimes[label] = timestamp
	tmaid:add(
		TaskSpawner.spawn(
			label,
			players.LocalPlayer.RequestStreamAroundAsync,
			players.LocalPlayer,
			position,
			0.1
		)
	)
end

---Check if realm name matches a destination.
---@param realm string
---@param destination string
---@return boolean
local function isRealmName(realm, destination)
	for _, alias in next, REALM_ALIASES[destination] or { destination } do
		if realm == alias then
			return true
		end
	end

	return false
end

---Get workspace child from path.
---@param path table
---@return Instance?
local function getWorkspacePath(path)
	local current = workspace
	for _, name in next, path do
		current = current:FindFirstChild(name)
		if not current then
			return nil
		end
	end

	return current
end

---Get realm teleporter from direct workspace paths.
---@param realm string
---@return BasePart?
local function getRealmTeleporter(realm)
	local cachedTeleporter = teleporterCache[realm]
	if cachedTeleporter and cachedTeleporter.Parent and isRealmName(cachedTeleporter:GetAttribute("Realm"), realm) then
		return cachedTeleporter
	end

	for _, path in next, REALM_TELEPORTER_PATHS do
		local teleporter = getWorkspacePath(path)
		if not teleporter or not teleporter:IsA("BasePart") then
			continue
		end

		if not isRealmName(teleporter:GetAttribute("Realm"), realm) then
			continue
		end

		teleporterCache[realm] = teleporter
		return teleporter
	end

	return nil
end

---Scan voidheart teleporter.
---@return BasePart?
local function scanVoidheartTeleporter()
	local warpPoints = workspace:FindFirstChild("WarpPoints")
	local voidheartWarpPoint = warpPoints and warpPoints:FindFirstChild("Voidheart")
	if voidheartWarpPoint and voidheartWarpPoint:IsA("BasePart") then
		return voidheartWarpPoint
	end

	local voidheart = workspace:FindFirstChild("Voidheart")
	local voidheartVoidWarp = voidheart and voidheart:FindFirstChild("VoidheartVoidWarp", true)
	if voidheartVoidWarp and voidheartVoidWarp:IsA("BasePart") then
		return voidheartVoidWarp
	end

	return nil
end

---Get voidheart teleporter.
---@return BasePart?
local function getVoidheartTeleporter()
	local cachedTeleporter = teleporterCache.Voidheart
	if cachedTeleporter and cachedTeleporter.Parent then
		return cachedTeleporter
	end

	local teleporter = scanVoidheartTeleporter()
	if teleporter then
		teleporterCache.Voidheart = teleporter
	end

	return teleporter
end

---Loop for teleport module.
local onTeleportLoop = LPH_NO_VIRTUALIZE(function()
	local dest = Teleport.destination
	if not dest then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer.Character
	if not character then
		return
	end

	---@note: Ported from Project Rain. We move onto the destination every frame
	local luminantTarget = LUMINANT_TARGETS[dest]
	if luminantTarget then
		requestStreamAround(string.format("Teleport_%sStream", dest), luminantTarget.Position)

		ensureNoClip()
		spoofMoveDirection(character)

		local hrp = character:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return
		end

		hrp.AssemblyLinearVelocity = Vector3.one * (math.random() / 100)
		hrp.CFrame = luminantTarget * CFrame.new(math.random() / 100, math.random() / 100, math.random() / 100)

		local realmTeleport = getValleyRealmTeleport()
		if realmTeleport then
			fireTouchOn(character, realmTeleport)
		end

		return
	end

	if dest == "Depths" then
		tmaid:add(
			TaskSpawner.spawn(
				"Teleport_DepthsStream",
				players.LocalPlayer.RequestStreamAroundAsync,
				players.LocalPlayer,
				Vector3.new(39911.3672, 39980.9375, 39708.3203),
				0.1
			)
		)

		local modOffice = workspace:FindFirstChild("ModOffice")
		local officePit = modOffice and modOffice:FindFirstChild("OfficePit")
		if not officePit then
			return
		end

		character:PivotTo(officePit.CFrame)
	end

	if dest == "Voidheart" then
		local voidheartTeleporter = getVoidheartTeleporter()
		requestStreamAround(
			"Teleport_VoidheartStream",
			voidheartTeleporter and voidheartTeleporter.Position or Vector3.new(-20000.0, 19713.9609, -20000.0)
		)

		if not voidheartTeleporter then
			return
		end

		local vhCFrame = voidheartTeleporter.CFrame
		teleportFrameCount = teleportFrameCount + 1
		local cycleFrame = (teleportFrameCount - 1) % (SPAM_FRAMES + PAUSE_FRAMES)

		-- Spam phase: PivotTo + touch.
		if cycleFrame < SPAM_FRAMES then
			character:PivotTo(vhCFrame)
			fireTouchOn(character, voidheartTeleporter)
			return
		end

		-- Pause phase: let server respond. Check on the last pause frame.
		if cycleFrame == SPAM_FRAMES + PAUSE_FRAMES - 1 then
			local hrp = character:FindFirstChild("HumanoidRootPart")
			if hrp and (hrp.Position - vhCFrame.Position).Magnitude <= RUBBERBAND_THRESHOLD then
				return Teleport.stop()
			end
		end
	end

	if dest == "TrialOfOne" then
		tmaid:add(
			TaskSpawner.spawn(
				"Teleport_TrialStream",
				players.LocalPlayer.RequestStreamAroundAsync,
				players.LocalPlayer,
				Vector3.new(-959.787659, 146.996887, -6659.63037),
				0.1
			)
		)

		local oneEntrance = workspace:FindFirstChild("OneEntrance")
		if not oneEntrance then
			return
		end

		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		if not effectReplicator then
			return
		end

		local effectReplicatorModule = require(effectReplicator)
		if not effectReplicatorModule then
			return
		end

		if effectReplicatorModule:FindEffect("Knocked") then
			return Teleport.stop()
		end

		character:PivotTo(oneEntrance.CFrame)
	end

	---@note: Ported from Project Rain. Instead of dropping below the base bounds
	if dest == "GuildDoor" then
		local guildName = Configuration.expectOptionValue("GuildDoorName")
		if not guildName or #guildName <= 0 then
			return
		end

		local entranceDoor, exitDoor = getGuildDoors(guildName)
		if not entranceDoor or not exitDoor then
			return
		end

		local hrp = character:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return
		end

		if (hrp.Position - entranceDoor.Position).Magnitude < 20 then
			hrp.AssemblyLinearVelocity = Vector3.zero
			return Teleport.stop()
		end

		requestStreamAround("Teleport_GuildBaseStream", exitDoor.Position)

		ensureNoClip()
		spoofMoveDirection(character)

		hrp.CFrame = exitDoor.CFrame

		local interactPrompt = exitDoor:FindFirstChild("InteractPrompt")
			or exitDoor:FindFirstChildWhichIsA("ProximityPrompt", true)

		if interactPrompt then
			pcall(fireproximityprompt, interactPrompt)
		end

		return
	end
end)

---Starts a safe tween to a specific destination at a high altitude.
---@param target_cframe CFrame
---@param speed number? (Optional, defaults to 190)
function Teleport.Safetweenstart(target_cframe, speed)
    Teleport.Safetweenstop()
    task.wait()

	local function internalSafeNAN(val)
        if val == val then return val end
        if typeof(val) == "Vector3" then
            return Vector3.new(val.X == val.X and val.X or 0, val.Y == val.Y and val.Y or 0, val.Z == val.Z and val.Z or 0)
        elseif typeof(val) == "CFrame" then
            local pos = val.Position
            local rot = val.Rotation
            return CFrame.new(pos.X == pos.X and pos.X or 0, pos.Y == pos.Y and pos.Y or 0, pos.Z == pos.Z and pos.Z or 0) * (rot == rot and rot or CFrame.identity)
        elseif typeof(val) == "number" then
            return val == val and val or 0
        end
        return val
    end

    speed = speed or 190
    local heightOffset = 8000
    local target_pos = target_cframe.Position
    local travel_pos = target_pos + Vector3.new(0, heightOffset, 0)
    local local_player = players.LocalPlayer

    local conn
    conn = runService.PreSimulation:Connect(function(dt)
        local character = local_player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root then return end

        local current_pos = root.Position
        local offset = travel_pos - current_pos 
        local distance = offset.Magnitude

        if distance <= 1 or distance ~= distance then return end

        root.AssemblyLinearVelocity = Vector3.zero
        
        root.CFrame = CFrame.new(root.CFrame.X, travel_pos.Y, root.CFrame.Z) 

        local dir = offset.Unit
        local step = speed * dt

        if step > distance then step = distance end

        root.CFrame = internalSafeNAN(root.CFrame + internalSafeNAN(dir * step))
    end)

    task.spawn(function()
        local character = local_player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        
    
        while root and (Vector2.new(travel_pos.X, travel_pos.Z) - Vector2.new(root.Position.X, root.Position.Z)).Magnitude > 15 do
            task.wait()
            root = character and character:FindFirstChild("HumanoidRootPart")
        end

        if root and conn then
            root.CFrame = target_cframe
        end

        if conn then
            conn:Disconnect()
            conn = nil
        end
    end)

    Teleport.activeTween = {
        stop = function()
            if conn then
                conn:Disconnect()
                conn = nil
            end
            
            local character = players.LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if root then
                root.CFrame = CFrame.new(root.Position.X, target_cframe.Y, root.Position.Z)
            end
        end
    }
end

function Teleport.Safetweenstop()
    if Teleport.activeTween then
        Teleport.activeTween.stop()
        Teleport.activeTween = nil
    end
end

---Start teleport module.
---@param destination string
function Teleport.start(destination)
	if not destination then
		return error("Destination must be provided for teleporting.")
	end

	resetTeleportState()
	Teleport.destination = destination
end

---Stop teleport module.
function Teleport.stop()
	resetTeleportState()
	Teleport.destination = nil
end

---Initialize Teleport module.
function Teleport.init()
	local localPlayer = players.LocalPlayer
	local playerGui = localPlayer:WaitForChild("PlayerGui")
	local descendantAddedSignal = Signal.new(playerGui.DescendantAdded)
	tmaid:mark(descendantAddedSignal:connect("Teleport_PlayerGui_DescendantAdded", onPlayerGuiDescendantAdded))

	local renderStepped = Signal.new(runService.RenderStepped)
	tmaid:mark(renderStepped:connect("Teleport_RenderStepped", onTeleportLoop))
end

---Detach Teleport module.
function Teleport.detach()
	Teleport.Safetweenstop()
	tmaid:clean()
end

-- Return Teleport module.
return Teleport

end)
__bundle_register("Features/Automation/FishFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Fish farming.
local FishFarm = {}

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")

-- Signals.
local renderStepped = Signal.new(runService.RenderStepped)

-- Maids.
local fishFarmMaid = Maid.new()

-- Timestamp.
local fishFarmTimestamp = os.clock()

-- State.
local wasActivated = false

---Update fish farm.
local updateFishFarm = LPH_NO_VIRTUALIZE(function()
	if os.clock() - fishFarmTimestamp < 0.1 then
		return
	end

	fishFarmTimestamp = os.clock()

	AntiAFK.stop("FishFarm")

	if not Configuration.expectToggleValue("AutoFish") then
		return
	end

	AntiAFK.start("FishFarm")

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	local humanoid = localPlayerCharacter:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return
	end

	local characterRod = localPlayerCharacter:FindFirstChild("Fishing Rod")
	local backpackRod = backpack:FindFirstChild("Fishing Rod")

	if not characterRod then
		return backpackRod and humanoid:EquipTool(backpackRod)
	end

	local handle = characterRod:FindFirstChild("Handle")
	local rod = handle and handle:FindFirstChild("Rod")
	local bobby = rod and rod:FindFirstChild("bobby")
	if not bobby then
		return
	end

	local addBait = characterRod:FindFirstChild("AddBait")
	if not addBait then
		return
	end

	---@todo: add fish meat lol
	local baitTable = {
		"Plumfruit",
		"Pomar",
		"Gobletto",
		"Squid",
		"Dentifilo",
		"Seaweed Bundle",
		"Urchin",
		"Browncap",
		"Chum",
		"Calabash",
		"Pufferfish",
		"Redd",
	}

	for _, baitName in next, baitTable do
		local bait = backpack:FindFirstChild(baitName)
		if not bait then
			continue
		end

		if bobby:FindFirstChild("bait") then
			break
		end

		return addBait:FireServer(bait)
	end

	local hook = bobby:FindFirstChild("hook")
	if not hook then
		return
	end

	if hook.Transparency ~= 1.0 then
		wasActivated = not wasActivated
		return wasActivated and characterRod:Deactivate() or characterRod:Activate()
	end

	local inputUpdate = characterRod:FindFirstChild("InputUpdate")
	if not inputUpdate then
		return
	end

	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	if not playerGui then
		return
	end

	local fishingGui = playerGui:FindFirstChild("FishingGui")
	if not fishingGui or not fishingGui.Enabled then
		return
	end

	local mainFrame = fishingGui:FindFirstChild("MainFrame")
	if not mainFrame then
		return
	end

	local holdA = mainFrame:FindFirstChild("HoldA")
	local holdS = mainFrame:FindFirstChild("HoldS")
	local holdD = mainFrame:FindFirstChild("HoldD")
	if not holdA or not holdS or not holdD then
		return
	end

	inputUpdate:FireServer({
		a = holdA.Visible,
		s = holdS.Visible,
		d = holdD.Visible,
	})
end)

---Fish farming.
function FishFarm.init()
	-- Attach the fish farm.
	fishFarmMaid:add(renderStepped:connect("FishFarm_RenderStepped", updateFishFarm))

	-- Log.
	if not LPH_OBFUSCATED or shared.Lycoris.verbose then
		Logger.warn("Fish Farm initialized.")
	end
end

---Detach the fish farm.
function FishFarm.detach()
	-- Clean the maid.
	fishFarmMaid:clean()

	-- Log.
	Logger.warn("Fish Farm detached.")
end

-- Return FishFarm module.
return FishFarm

end)
