local function updateTesterBreaker(rootPart, humanoid, dt)
    if tick() - lastApTick < 1/8 then 
        return 
    end
    lastApTick = tick()

    if not humanoid then return end

	local isMoving = humanoid.MoveDirection.Magnitude > 0.1
	if not isMoving then return end

    local animation_instance = Instance.new("Animation")
    animation_instance.AnimationId = tester_breaker_anims[math.random(1, #tester_breaker_anims)]
    
    local track = humanoid:LoadAnimation(animation_instance)
    
    track.Priority = rand:NextNumber() > 0.5 and Enum.AnimationPriority.Movement or Enum.AnimationPriority.Action
    track:Play(rand:NextNumber(0.6, 0.7), rand:NextNumber(0.4, 0.6), rand:NextNumber(0.5, 0.6))

    task.spawn(function()
        task.wait(1 / 15)
        if track and track.IsPlaying then
            track.Priority = Enum.AnimationPriority.Core
            track:AdjustWeight(rand:NextNumber(0.5, 1), 0)
        end
    end)

    task.delay(1, function()
        if track then
            track:Stop()
            track:Destroy()
        end
    end)

    track.Ended:Once(function()
    end)
end

