---Initialize Cheat Settings section.
---@param groupbox table
function LycorisTab.initCheatSettingsSection(groupbox)
	groupbox:AddButton("Toggle Silent Mode", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Lycoris.silent = not shared.Lycoris.silent

		if not shared.Lycoris.silent then
			Logger.notify("Silent mode was disabled.")
		end

		if isfile("Jawless Jockey Hub/Settings/smarker.txt") then
			delfile("Jawless Jockey Hub/Settings/smarker.txt")
		else
			writefile(
				"Jawless Jockey Hub/Settings/smarker.txt",
				"Hello, if you're reading this, that means you have Jawless Jockey Hub (Deepwoken) silent mode turned on. Deleting this file will turn it off."
			)
		end
	end)

	groupbox:AddButton("Toggle Player Scanning", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Lycoris.dpscanning = not shared.Lycoris.dpscanning

		if shared.Lycoris.dpscanning then
			Logger.notify("Player scanning was disabled.")
		else
			Logger.notify("Player scanning was enabled.")
		end

		if isfile("Jawless Jockey Hub/Settings/dpscanning.txt") then
			delfile("Jawless Jockey Hub/Settings/dpscanning.txt")
		else
			writefile(
				"Jawless Jockey Hub/Settings/dpscanning.txt",
				"Hello, if you're reading this, that means you have Jawless Jockey Hub (Deepwoken) player scanning turned off. Deleting this file will turn it on."
			)
		end
	end)

	groupbox:AddButton("Toggle Bloxstrap RPC", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Lycoris.norpc = not shared.Lycoris.norpc

		if not shared.Lycoris.norpc then
			Logger.notify("Bloxstrap RPC was enabled.")
		else
			Logger.notify("Bloxstrap RPC was disabled.")
		end

		if isfile("Jawless Jockey Hub/Settings/norpc.txt") then
			delfile("Jawless Jockey Hub/Settings/norpc.txt")
		else
			writefile(
				"Jawless Jockey Hub/Settings/norpc.txt",
				"Hello, if you're reading this, that means you have Jawless Jockey Hub (Deepwoken) Bloxstrap RPC turned off. Deleting this file will turn it on."
			)
		end
	end)

	groupbox:AddButton("Toggle Debug Logs", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Lycoris.verbose = not shared.Lycoris.verbose

		if shared.Lycoris.verbose then
			Logger.notify("Debug logs were enabled.")
		else
			Logger.notify("Debug logs were disabled.")
		end

		if isfile("Jawless Jockey Hub/Settings/verbose.txt") then
			delfile("Jawless Jockey Hub/Settings/verbose.txt")
		else
			writefile(
				"Jawless Jockey Hub/Settings/verbose.txt",
				"Hello, if you're reading this, that means you have Jawless Jockey Hub (Deepwoken) debug logs turned on. Deleting this file will turn it off."
			)
		end
	end)

	groupbox:AddButton("Unload Cheat", function()
		shared.Lycoris.detach()
	end)
end

function LycorisTab.initSpotifySection(groupbox)
	groupbox:AddButton("Copy Auth URL", function()
		setclipboard(SpotifyClient.getAuthUrl())
		Logger.notify("Auth URL copied. Open it in a browser, log in, click Allow, then copy the URL it redirects to (even if the page fails to load).")
	end)

	local redirectUrlInput = groupbox:AddInput("SpotifyRedirectUrl", {
		Text = "Redirect URL",
		Placeholder = "Paste the full URL you were redirected to here.",
	})

	groupbox:AddButton("Authorize", function()
		local ok, err = SpotifyClient.completeAuth(redirectUrlInput.Value)
		if ok then
			Logger.notify("Spotify authorized successfully.")
		else
			Logger.notify("Spotify authorization failed: " .. tostring(err))
		end
	end)

	SpotifyWidget.init(Library)

	local showWidgetToggle = groupbox:AddToggle("ShowSpotifyWidget", {
		Text = "Show Spotify Widget",
		Default = false,
	})

	showWidgetToggle:OnChanged(function(state)
		SpotifyWidget.setVisible(state)
	end)
end

---Initialize UI Settings section.
---@param groupbox table
function LycorisTab.initUISettingsSection(groupbox)
	local edgeGlowToggle = groupbox:AddToggle("EdgeGlow", {
		Text = "Edge Glow",
		Default = true,
	})

	edgeGlowToggle:AddColorPicker("EdgeGlowColor", {
		Default = Color3.fromRGB(0, 0, 0),
	})

	local egDepBox = groupbox:AddDependencyBox()

	egDepBox:AddSlider("EdgeGlowSize", {
		Text = "Glow Size",
		Min = 0,
		Max = 15,
		Default = 7,
		Rounding = 0,
		Suffix = "px",
	})

	egDepBox:AddSlider("EdgeGlowOpacity", {
		Text = "Glow Opacity",
		Min = 0,
		Max = 100,
		Default = 100,
		Rounding = 0,
		Suffix = "%",
	})

	egDepBox:SetupDependencies({
		{ Toggles.EdgeGlow, true },
	})

	groupbox:AddSlider("NotificationScale", {
		Text = "Notification Scale",
		Min = 50,
		Max = 300,
		Default = 100,
		Rounding = 0,
		Suffix = "%",
	})

	groupbox:AddSlider("QuickNotificationSpeed", {
		Text = "Quick Notification Speed",
		Min = 0.1,
		Max = 2.0,
		Default = 0.5,
		Rounding = 2,
		Suffix = "s",
	})

	local menuBindLabel = groupbox:AddLabel("Menu Bind")

	menuBindLabel:AddKeyPicker("MenuKeybind", { Default = "LeftAlt", NoUI = true, Text = "Menu Keybind" })

	local keybindFrameLabel = groupbox:AddLabel("Keybind List Bind")

	keybindFrameLabel:AddKeyPicker("KeybindList", {
		Default = "N/A",
		Mode = "Off",
		NoUI = true,
		Text = "Keybind List",
		Callback = function(Value)
			Library.KeybindFrame.Visible = Value
		end,
	})

	local watermarkFrameLabel = groupbox:AddLabel("Watermark Bind")

	watermarkFrameLabel:AddKeyPicker("Watermark", {
		Default = "N/A",
		Mode = "Off",
		NoUI = true,
		Text = "Watermark",
		Callback = function(Value)
			Library:SetWatermarkVisibility(Value)
		end,
	})

	groupbox:AddToggle("HideUIInMenus", {
		Text = "Hide UI In Menus",
		Tooltip = "Hide the keybind list and watermark while the inventory or other in-game menus are open.",
		Default = false,
	})
end

---Initialize tab.
function LycorisTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Settings", "Settings", Icons.Settings) -- dont change the name, it's more confusing if its named that way

	-- Initialize sections.
	LycorisTab.initCheatSettingsSection(tab:AddLeftGroupbox("Cheat Settings"))
	LycorisTab.initUISettingsSection(tab:AddRightGroupbox("UI Settings"))

	if not LPH_OBFUSCATED then
		LycorisTab.initSpotifySection(tab:AddDynamicGroupbox("Spotify"))
	end

	-- Configure SaveManager & ThemeManager.
	ThemeManager:ApplyToTab(tab)
	SaveManager:BuildConfigSection(tab)
end

-- Return LycorisTab module.
return LycorisTab

end)
__bundle_register("GUI/SpotifyWidget", function(require, _LOADED, __bundle_register, __bundle_modules)
local SpotifyClient = require("Utility/SpotifyClient")
local Filesystem = require("Utility/Filesystem")
local Logger = require("Utility/Logger")

local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Players = game:GetService("Players")
local Mouse = Players.LocalPlayer:GetMouse()

local artStorage = Filesystem.new("Jawless Jockey Hub/Spotify/Art")
local artCache = {}

local POLL_INTERVAL = 2

local SpotifyWidget = {}

local built = false
local library = nil

local outer, inner, artLabel, titleLabel, artistLabel
local barBack, barFill, scrubberDot, currentTimeLabel, durationLabel
local playPauseLabel

local lastPoll = 0
local nowPlaying = nil
local lastProgressMs = 0
local lastProgressAt = 0
local fetchingArt = {}
local scrubbing = false

local function formatTime(ms)
	local totalSeconds = math.floor((ms or 0) / 1000)
	local minutes = math.floor(totalSeconds / 60)
	local seconds = totalSeconds % 60
	return string.format("%d:%02d", minutes, seconds)
end

local function fetchAlbumArt(trackId, url)
	if not trackId or not url or artCache[trackId] or fetchingArt[trackId] then
		return
	end

	fetchingArt[trackId] = true

	task.spawn(function()
		local filename = trackId .. ".png"
		local contentId = nil

		local ok = pcall(function()
			if not artStorage:file(filename) then
				local response = request({ Url = url, Method = "GET" })
				if not response or not response.Success or not response.Body then
					return
				end
				artStorage:write(filename, response.Body)
			end

			contentId = getcustomasset(artStorage:append(filename))
		end)

		if ok and contentId then
			artCache[trackId] = contentId
			if nowPlaying and nowPlaying.trackId == trackId then
				artLabel.Image = contentId
			end
		end

		fetchingArt[trackId] = nil
	end)
end

local function makeControlButton(parent, text, position, callback)
	local buttonOuter = library:Create("Frame", {
		BackgroundTransparency = 1,
		Position = position,
		Size = UDim2.new(0, 30, 0, 24),
		ZIndex = 210,
		Parent = parent,
	})

	local label = library:CreateLabel({
		Active = false,
		Size = UDim2.new(1, 0, 1, 0),
		TextSize = 18,
		Text = text,
		ZIndex = 211,
		Parent = buttonOuter,
	})

	library:OnHighlight(buttonOuter, label, { TextColor3 = "AccentColor" }, { TextColor3 = "FontColor" })

	label.InputBegan:Connect(function(Input)
		if Input.UserInputType == Enum.UserInputType.MouseButton1 and not library:MouseIsOverOpenedFrame() then
			callback()
		end
	end)

	return buttonOuter, label
end

function SpotifyWidget.init(Library)
	if built then
		return
	end
	built = true
	library = Library

	outer = library:Create("Frame", {
		BackgroundColor3 = Color3.new(0, 0, 0),
		BorderColor3 = library.AccentColor,
		Position = UDim2.new(0, 100, 0, 100),
		Size = UDim2.new(0, 230, 0, 300),
		Visible = false,
		ZIndex = 205,
		Parent = library.ScreenGui,
	})

	library:AddToRegistry(outer, {
		BorderColor3 = "AccentColor",
	})

	library:Create("UICorner", {
		CornerRadius = UDim.new(0, 10),
		Parent = outer,
	})

	library:MakeDraggable(outer)

	inner = library:Create("Frame", {
		BackgroundColor3 = library.MainColor,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 1, 0, 1),
		Size = UDim2.new(1, -2, 1, -2),
		ZIndex = 206,
		Parent = outer,
	})

	library:AddToRegistry(inner, {
		BackgroundColor3 = "MainColor",
	})

	library:Create("UICorner", {
		CornerRadius = UDim.new(0, 9),
		Parent = inner,
	})

	artLabel = library:Create("ImageLabel", {
		BackgroundColor3 = library:GetDarkerColor(library.MainColor),
		BorderSizePixel = 0,
		Position = UDim2.new(0, 6, 0, 6),
		Size = UDim2.new(1, -12, 0, 180),
		Image = "",
		ScaleType = Enum.ScaleType.Crop,
		ZIndex = 207,
		Parent = inner,
	})

	library:AddToRegistry(artLabel, {
		BackgroundColor3 = "MainColor",
	})

	library:Create("UICorner", {
		CornerRadius = UDim.new(0, 8),
		Parent = artLabel,
	})

	titleLabel = library:CreateLabel({
		Position = UDim2.new(0, 6, 0, 190),
		Size = UDim2.new(1, -12, 0, 18),
		TextSize = 14,
		Text = "Nothing playing",
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 207,
		Parent = inner,
	})

	artistLabel = library:CreateLabel({
		Position = UDim2.new(0, 6, 0, 208),
		Size = UDim2.new(1, -12, 0, 16),
		TextSize = 12,
		Text = "",
		TextColor3 = Color3.fromRGB(170, 170, 170),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 207,
		Parent = inner,
	})

	barBack = library:Create("Frame", {
		BackgroundColor3 = library.OutlineColor,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 6, 0, 236),
		Size = UDim2.new(1, -12, 0, 3),
		ZIndex = 207,
		Parent = inner,
	})

	library:AddToRegistry(barBack, {
		BackgroundColor3 = "OutlineColor",
	})

	library:Create("UICorner", {
		CornerRadius = UDim.new(1, 0),
		Parent = barBack,
	})

	barFill = library:Create("Frame", {
		BackgroundColor3 = library.AccentColor,
		BorderSizePixel = 0,
		Size = UDim2.new(0, 0, 1, 0),
		ZIndex = 208,
		Parent = barBack,
	})

	library:AddToRegistry(barFill, {
		BackgroundColor3 = "AccentColor",
	})

	library:Create("UICorner", {
		CornerRadius = UDim.new(1, 0),
		Parent = barFill,
	})

	scrubberDot = library:Create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.new(0, 8, 0, 8),
		ZIndex = 209,
		Parent = barFill,
	})

	library:Create("UICorner", {
		CornerRadius = UDim.new(1, 0),
		Parent = scrubberDot,
	})

	-- Bigger invisible hit area than the 3px bar itself, so it's actually grabbable.
	local barHitArea = library:Create("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, 16),
		ZIndex = 212,
		Parent = barBack,
	})

	local function seekToMouseX()
		if not nowPlaying or nowPlaying.durationMs <= 0 then
			return nil
		end

		local relativeX = Mouse.X - barBack.AbsolutePosition.X
		local percent = math.clamp(relativeX / barBack.AbsoluteSize.X, 0, 1)

		barFill.Size = UDim2.new(percent, 0, 1, 0)
		currentTimeLabel.Text = formatTime(percent * nowPlaying.durationMs)

		return percent
	end

	barHitArea.InputBegan:Connect(function(Input)
		if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		scrubbing = true
		local finalPercent

		repeat
			finalPercent = seekToMouseX() or finalPercent
			RunService.RenderStepped:Wait()
		until not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)

		scrubbing = false

		if finalPercent and nowPlaying and nowPlaying.durationMs > 0 then
			local seekMs = math.floor(finalPercent * nowPlaying.durationMs)
			lastProgressMs = seekMs
			lastProgressAt = os.clock()
			SpotifyClient.seek(seekMs)
		end
	end)

	currentTimeLabel = library:CreateLabel({
		Position = UDim2.new(0, 6, 0, 242),
		Size = UDim2.new(0.5, -8, 0, 14),
		TextSize = 11,
		Text = "0:00",
		TextColor3 = Color3.fromRGB(170, 170, 170),
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 207,
		Parent = inner,
	})

	durationLabel = library:CreateLabel({
		Position = UDim2.new(0.5, 2, 0, 242),
		Size = UDim2.new(0.5, -8, 0, 14),
		TextSize = 11,
		Text = "0:00",
		TextColor3 = Color3.fromRGB(170, 170, 170),
		TextXAlignment = Enum.TextXAlignment.Right,
		ZIndex = 207,
		Parent = inner,
	})

	-- Actions take a moment to actually change Spotify's server-side state, so polling
	-- immediately after firing one would often just read back the pre-action state.
	-- Force a fresh poll shortly after instead of waiting out the full interval.
	local function forcePollSoon(delaySeconds)
		task.delay(delaySeconds or 0.4, function()
			lastPoll = 0
		end)
	end

	makeControlButton(inner, "<", UDim2.new(0.5, -55, 0, 264), function()
		SpotifyClient.previous()
		forcePollSoon(0.5)
	end)

	local _, resolvedPlayPauseLabel = makeControlButton(inner, "||", UDim2.new(0.5, -15, 0, 264), function()
		if nowPlaying then
			-- Optimistic flip so the icon changes instantly instead of waiting on the
			-- next poll; the forced re-poll below will correct it if the action failed.
			nowPlaying.isPlaying = not nowPlaying.isPlaying
			playPauseLabel.Text = nowPlaying.isPlaying and "||" or "▶"

			if nowPlaying.isPlaying then
				SpotifyClient.play()
			else
				SpotifyClient.pause()
			end
		else
			SpotifyClient.play()
		end

		forcePollSoon()
	end)
	playPauseLabel = resolvedPlayPauseLabel

	makeControlButton(inner, ">", UDim2.new(0.5, 25, 0, 264), function()
		SpotifyClient.next()
		forcePollSoon(0.5)
	end)

	RunService.Heartbeat:Connect(function()
		if not outer.Visible then
			return
		end

		if os.clock() - lastPoll >= POLL_INTERVAL then
			lastPoll = os.clock()

			task.spawn(function()
				local result = SpotifyClient.getCurrentlyPlaying()
				nowPlaying = result

				if result then
					if not scrubbing then
						lastProgressMs = result.progressMs
						lastProgressAt = os.clock()
					end

					titleLabel.Text = result.trackName
					artistLabel.Text = result.artistName
					durationLabel.Text = formatTime(result.durationMs)
					playPauseLabel.Text = result.isPlaying and "||" or "▶"

					if not artCache[result.trackId] then
						artLabel.Image = ""
					end
					fetchAlbumArt(result.trackId, result.albumArtUrl)
				else
					titleLabel.Text = "Nothing playing"
					artistLabel.Text = ""
					durationLabel.Text = "0:00"
					currentTimeLabel.Text = "0:00"
					barFill.Size = UDim2.new(0, 0, 1, 0)
					artLabel.Image = ""
				end
			end)
		end

		if not nowPlaying or scrubbing then
			return
		end

		local elapsedMs = nowPlaying.isPlaying and ((os.clock() - lastProgressAt) * 1000) or 0
		local displayedMs = math.clamp(lastProgressMs + elapsedMs, 0, nowPlaying.durationMs)
		local percent = nowPlaying.durationMs > 0 and (displayedMs / nowPlaying.durationMs) or 0

		currentTimeLabel.Text = formatTime(displayedMs)
		barFill.Size = UDim2.new(percent, 0, 1, 0)
	end)
end

function SpotifyWidget.setVisible(visible)
	if outer then
		outer.Visible = visible
	end
end

return SpotifyWidget

end)
__bundle_register("Utility/SpotifyClient", function(require, _LOADED, __bundle_register, __bundle_modules)
local JSON = require("Utility/JSON")
local Filesystem = require("Utility/Filesystem")
local Logger = require("Utility/Logger")

local storage = Filesystem.new("Jawless Jockey Hub/Spotify")

local DEBUG = false
local function dbg(fmt, ...)
	if DEBUG then
		Logger.warn("[Spotify] " .. fmt, ...)
	end
end

local SpotifyClient = {}

-- Register one app at developer.spotify.com/dashboard, set its Redirect URI to
-- REDIRECT_URI below, and paste the Client ID here. No client secret needed (PKCE) --
-- a Client ID isn't sensitive, so this can ship hardcoded and every end user just
-- authorizes with their own Spotify account, no dashboard access required.
local CLIENT_ID = "70dfc46fe4294dfcb51b5879f021f9d1"

local REDIRECT_URI = "http://127.0.0.1:8888/callback"
local SCOPES = "user-read-playback-state user-modify-playback-state user-read-currently-playing"
local TOKEN_URL = "https://accounts.spotify.com/api/token"
local API_BASE = "https://api.spotify.com/v1/me/player"

local BASE64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local VERIFIER_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"

local state = {
	clientId = CLIENT_ID,
	refreshToken = "",
	codeVerifier = nil,
	accessToken = nil,
	accessTokenExpiresAt = 0,
}

local function base64Encode(input)
	local out = {}
	local length = #input

	for i = 1, length, 3 do
		local b1, b2, b3 = string.byte(input, i, i + 2)
		b2 = b2 or 0
		b3 = b3 or 0

		local n = b1 * 65536 + b2 * 256 + b3

		local c1 = math.floor(n / 262144) % 64
		local c2 = math.floor(n / 4096) % 64
		local c3 = math.floor(n / 64) % 64
		local c4 = n % 64

		local chunk = string.sub(BASE64_CHARS, c1 + 1, c1 + 1)
			.. string.sub(BASE64_CHARS, c2 + 1, c2 + 1)
			.. (i + 1 <= length and string.sub(BASE64_CHARS, c3 + 1, c3 + 1) or "=")
			.. (i + 2 <= length and string.sub(BASE64_CHARS, c4 + 1, c4 + 1) or "=")

		table.insert(out, chunk)
	end

	return table.concat(out)
end

local function base64UrlEncode(input)
	return (base64Encode(input):gsub("[+/=]", { ["+"] = "-", ["/"] = "_", ["="] = "" }))
end

local function urlEncode(value)
	return (tostring(value):gsub("[^%w%-%.%_%~]", function(char)
		return string.format("%%%02X", string.byte(char))
	end))
end

local function encodeForm(fields)
	local parts = {}
	for key, value in next, fields do
		table.insert(parts, urlEncode(key) .. "=" .. urlEncode(value))
	end
	return table.concat(parts, "&")
end

local SHA256_K = {
	0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
	0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
	0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
	0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
	0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
	0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
	0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
	0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
}

local function sha256(msg)
	local band, bxor, bnot, rshift, rrotate = bit32.band, bit32.bxor, bit32.bnot, bit32.rshift, bit32.rrotate

	local h0, h1, h2, h3, h4, h5, h6, h7 =
		0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19

	local msgLen = #msg
	local bitLen = msgLen * 8

	msg = msg .. "\128"
	while #msg % 64 ~= 56 do
		msg = msg .. "\0"
	end

	for i = 7, 0, -1 do
		msg = msg .. string.char(band(rshift(bitLen, i * 8), 0xFF))
	end

	for chunkStart = 1, #msg, 64 do
		local w = {}
		for i = 0, 15 do
			local o = chunkStart + i * 4
			local b1, b2, b3, b4 = string.byte(msg, o, o + 3)
			w[i + 1] = b1 * 16777216 + b2 * 65536 + b3 * 256 + b4
		end

		for i = 17, 64 do
			local w15, w2 = w[i - 15], w[i - 2]
			local s0 = bxor(rrotate(w15, 7), rrotate(w15, 18), rshift(w15, 3))
			local s1 = bxor(rrotate(w2, 17), rrotate(w2, 19), rshift(w2, 10))
			w[i] = (w[i - 16] + s0 + w[i - 7] + s1) % 4294967296
		end

		local a, b, c, d, e, f, g, h = h0, h1, h2, h3, h4, h5, h6, h7

		for i = 1, 64 do
			local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
			local ch = bxor(band(e, f), band(bnot(e), g))
			local temp1 = (h + S1 + ch + SHA256_K[i] + w[i]) % 4294967296
			local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
			local maj = bxor(band(a, b), band(a, c), band(b, c))
			local temp2 = (S0 + maj) % 4294967296

			h, g, f = g, f, e
			e = (d + temp1) % 4294967296
			d, c, b = c, b, a
			a = (temp1 + temp2) % 4294967296
		end

		h0 = (h0 + a) % 4294967296
		h1 = (h1 + b) % 4294967296
		h2 = (h2 + c) % 4294967296
		h3 = (h3 + d) % 4294967296
		h4 = (h4 + e) % 4294967296
		h5 = (h5 + f) % 4294967296
		h6 = (h6 + g) % 4294967296
		h7 = (h7 + h) % 4294967296
	end

	local out = {}
	for _, v in next, { h0, h1, h2, h3, h4, h5, h6, h7 } do
		out[#out + 1] = string.char(
			band(rshift(v, 24), 0xFF),
			band(rshift(v, 16), 0xFF),
			band(rshift(v, 8), 0xFF),
			band(v, 0xFF)
		)
	end

	return table.concat(out)
end

local function generateCodeVerifier()
	local rng = Random.new()
	local chars = {}
	for i = 1, 64 do
		local idx = rng:NextInteger(1, #VERIFIER_CHARS)
		chars[i] = VERIFIER_CHARS:sub(idx, idx)
	end
	return table.concat(chars)
end

function SpotifyClient.load()
	if not storage:file("auth.json") then
		return
	end

	local ok, decoded = pcall(JSON.decode, storage:read("auth.json"))
	if not ok or type(decoded) ~= "table" then
		return
	end

	if type(decoded.clientId) == "string" and decoded.clientId ~= "" then
		state.clientId = decoded.clientId
	end
	state.refreshToken = decoded.refreshToken or ""
end

function SpotifyClient.save()
	storage:write(
		"auth.json",
		JSON.encode({
			clientId = state.clientId,
			refreshToken = state.refreshToken,
		})
	)
end

function SpotifyClient.setClientId(clientId)
	if clientId and clientId ~= "" then
		state.clientId = clientId
		SpotifyClient.save()
	end
end

function SpotifyClient.getClientId()
	return state.clientId
end

function SpotifyClient.isAuthorized()
	return state.refreshToken ~= ""
end

function SpotifyClient.getAuthUrl()
	state.codeVerifier = generateCodeVerifier()
	local codeChallenge = base64UrlEncode(sha256(state.codeVerifier))

	return "https://accounts.spotify.com/authorize?"
		.. encodeForm({
			client_id = state.clientId,
			response_type = "code",
			redirect_uri = REDIRECT_URI,
			scope = SCOPES,
			code_challenge_method = "S256",
			code_challenge = codeChallenge,
		})
end

local function extractCode(pastedUrl)
	return pastedUrl:match("[?&]code=([^&#]+)")
end

function SpotifyClient.completeAuth(pastedUrl)
	if not state.codeVerifier then
		return false, "Click 'Copy Auth URL' first -- authorization needs to start from there."
	end

	local code = extractCode(pastedUrl)
	if not code then
		return false, "Couldn't find a 'code' parameter in that URL."
	end

	local response = request({
		Url = TOKEN_URL,
		Method = "POST",
		Headers = {
			["Content-Type"] = "application/x-www-form-urlencoded",
		},
		Body = encodeForm({
			grant_type = "authorization_code",
			code = code,
			redirect_uri = REDIRECT_URI,
			client_id = state.clientId,
			code_verifier = state.codeVerifier,
		}),
	})

	state.codeVerifier = nil

	if not response or not response.Success then
		return false, "Token exchange request failed."
	end

	local ok, decoded = pcall(JSON.decode, response.Body)
	if not ok or not decoded or not decoded.refresh_token then
		return false, "Token exchange returned an unexpected response."
	end

	state.refreshToken = decoded.refresh_token
	state.accessToken = decoded.access_token
	state.accessTokenExpiresAt = os.clock() + (decoded.expires_in or 3600) - 30
	SpotifyClient.save()

	return true
end

local function refreshAccessToken()
	if state.refreshToken == "" then
		return false
	end

	local response = request({
		Url = TOKEN_URL,
		Method = "POST",
		Headers = {
			["Content-Type"] = "application/x-www-form-urlencoded",
		},
		Body = encodeForm({
			grant_type = "refresh_token",
			refresh_token = state.refreshToken,
			client_id = state.clientId,
		}),
	})

	if not response or not response.Success then
		return false
	end

	local ok, decoded = pcall(JSON.decode, response.Body)
	if not ok or not decoded or not decoded.access_token then
		return false
	end

	state.accessToken = decoded.access_token
	state.accessTokenExpiresAt = os.clock() + (decoded.expires_in or 3600) - 30

	if decoded.refresh_token then
		state.refreshToken = decoded.refresh_token
		SpotifyClient.save()
	end

	return true
end

local function ensureToken()
	if state.accessToken and os.clock() < state.accessTokenExpiresAt then
		return true
	end

	return refreshAccessToken()
end

local function authorizedRequest(method, path, body)
	if not ensureToken() then
		dbg("%s %s: ensureToken() failed, no valid access token", method, path)
		return nil
	end

	-- Spotify's frontend rejects PUT/POST with no body at all (411 Length Required --
	-- it wants a Content-Length even for an empty payload), so always send something.
	local response = request({
		Url = API_BASE .. path,
		Method = method,
		Headers = {
			["Authorization"] = "Bearer " .. state.accessToken,
			["Content-Type"] = "application/json",
		},
		Body = body or "{}",
	})

	if not response then
		dbg("%s %s: request() returned nil", method, path)
	elseif not response.Success then
		dbg("%s %s: failed, status=%s body=%s", method, path, tostring(response.StatusCode), tostring(response.Body))
	else
		dbg("%s %s: ok, status=%s", method, path, tostring(response.StatusCode))
	end

	return response
end

function SpotifyClient.getCurrentlyPlaying()
	local response = authorizedRequest("GET", "/currently-playing")
	if not response or not response.Success or response.StatusCode == 204 or not response.Body or response.Body == "" then
		return nil
	end

	local ok, decoded = pcall(JSON.decode, response.Body)
	if not ok or not decoded or not decoded.item then
		return nil
	end

	local images = decoded.item.album and decoded.item.album.images or {}
	local artists = {}
	for _, artist in next, decoded.item.artists or {} do
		table.insert(artists, artist.name)
	end

	return {
		trackId = decoded.item.id,
		trackName = decoded.item.name,
		artistName = table.concat(artists, ", "),
		albumArtUrl = images[1] and images[1].url,
		progressMs = decoded.progress_ms or 0,
		durationMs = decoded.item.duration_ms or 0,
		isPlaying = decoded.is_playing or false,
	}
end

function SpotifyClient.play()
	authorizedRequest("PUT", "/play")
end

function SpotifyClient.pause()
	authorizedRequest("PUT", "/pause")
end

function SpotifyClient.next()
	authorizedRequest("POST", "/next")
end

function SpotifyClient.previous()
	authorizedRequest("POST", "/previous")
end

function SpotifyClient.seek(positionMs)
	authorizedRequest("PUT", "/seek?position_ms=" .. math.floor(positionMs))
end

SpotifyClient.load()

return SpotifyClient

end)
__bundle_register("GUI/SaveManager", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local httpService = game:GetService("HttpService")

	---Export UDim2 to a serializable table.
	---@param udim2 UDim2
	---@return table
	local function uDIm2Export(udim2)
		return {
			xScale = udim2.X.Scale,
			xOffset = udim2.X.Offset,
			yScale = udim2.Y.Scale,
			yOffset = udim2.Y.Offset,
		}
	end

	---Import UDim2 from a serializable table.
	---@param serialized table
	---@return UDim2
	local function uDim2Import(serialized)
		return UDim2.new(serialized.xScale, serialized.xOffset, serialized.yScale, serialized.yOffset)
	end

	local SaveManager = {}
	do
		SaveManager.Folder = "Jawless Jockey Hub/Configs"
		SaveManager.Ignore = {}
		SaveManager.Parser = {
			Toggle = {
				Save = function(idx, object)
					return { type = "Toggle", idx = idx, value = object.Value }
				end,
				Load = function(idx, data)
					if Toggles[idx] then
						Toggles[idx]:SetValue(data.value)
					end
				end,
			},
			Slider = {
				Save = function(idx, object)
					return { type = "Slider", idx = idx, value = tostring(object.Value) }
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue(data.value)
					end
				end,
			},
			Dropdown = {
				Save = function(idx, object)
					return {
						type = "Dropdown",
						idx = idx,
						value = object.Value,
						values = object.SaveValues and object.Values or nil,
						mutli = object.Multi,
					}
				end,
				Load = function(idx, data)
					if Options[idx] then
						if data.values then
							Options[idx]:SetValues(data.values)
						end

						Options[idx]:SetValue(data.value)
					end
				end,
			},
			ColorPicker = {
				Save = function(idx, object)
					return {
						type = "ColorPicker",
						idx = idx,
						hue = object.Hue,
						sat = object.Sat,
						vib = object.Vib,
						transparency = object.Transparency,
						rainbow = object.Rainbow,
					}
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx].Rainbow = data.rainbow
						Options[idx]:SetValue({ data.hue, data.sat, data.vib }, data.transparency)
						Options[idx]:Display()
					end
				end,
			},
			KeyPicker = {
				Save = function(idx, object)
					return { type = "KeyPicker", idx = idx, mode = object.Mode, key = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue({ data.key, data.mode })
					end
				end,
			},

			Input = {
				Save = function(idx, object)
					return { type = "Input", idx = idx, text = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] and type(data.text) == "string" then
						Options[idx]:SetValue(data.text)
					end
				end,
			},
		}

		function SaveManager:SetIgnoreIndexes(list)
			for _, key in next, list do
				self.Ignore[key] = true
			end
		end

		function SaveManager:SetFolder(folder)
			self.Folder = folder
			self:BuildFolderTree()
		end

		function SaveManager:Save(name)
			if not name then
				return false, "no config file is selected"
			end

			local fullPath = self.Folder .. "/" .. name .. ".json"

			local data = {
				objects = {},
				keybindFramePosition = uDIm2Export(self.Library.KeybindFrame.Position),
				watermarkFramePosition = uDIm2Export(self.Library.Watermark.Position),
				infoLoggerFramePosition = uDIm2Export(self.Library.InfoLoggerFrame.Position),
				infoLoggerBlacklistHistory = self.Library.InfoLoggerData.KeyBlacklistHistory,
				infoLoggerBlacklist = self.Library.InfoLoggerData.KeyBlacklistList,
				infoLoggerCycle = self.Library.InfoLoggerData.InfoLoggerCycle,
				animationVisualizerFramePosition = uDIm2Export(self.Library.AnimationVisualizerFrame.Position),
				overrideData = self.Library.OverrideData,
			}

			for idx, toggle in next, Toggles do
				if self.Ignore[idx] then
					continue
				end

				table.insert(data.objects, self.Parser[toggle.Type].Save(idx, toggle))
			end

			for idx, option in next, Options do
				if not self.Parser[option.Type] then
					continue
				end
				if self.Ignore[idx] then
					continue
				end

				table.insert(data.objects, self.Parser[option.Type].Save(idx, option))
			end

			local success, encoded = pcall(httpService.JSONEncode, httpService, data)
			if not success then
				return false, "failed to encode data"
			end

			writefile(fullPath, encoded)
			return true
		end

		function SaveManager:Load(name)
			if not name then
				return false, "no config file is selected"
			end

			local file = self.Folder .. "/" .. name .. ".json"
			if not isfile(file) then
				return false, "invalid file"
			end

			local success, decoded = pcall(httpService.JSONDecode, httpService, readfile(file))
			if not success then
				return false, "decode error"
			end

			if decoded.keybindFramePosition then
				self.Library.KeybindFrame.Position = uDim2Import(decoded.keybindFramePosition)
			end

			if decoded.watermarkFramePosition then
				self.Library.Watermark.Position = uDim2Import(decoded.watermarkFramePosition)
			end

			if decoded.infoLoggerFramePosition then
				self.Library.InfoLoggerFrame.Position = uDim2Import(decoded.infoLoggerFramePosition)
			end

			if decoded.infoLoggerBlacklistHistory then
				self.Library.InfoLoggerData.KeyBlacklistHistory = decoded.infoLoggerBlacklistHistory
			end

			if decoded.animationVisualizerFramePosition then
				self.Library.AnimationVisualizerFrame.Position = uDim2Import(decoded.animationVisualizerFramePosition)
			end

			local timingList = Options["TimingOverrideList"]

			if decoded.overrideData and timingList then
				self.Library.OverrideData = decoded.overrideData

				local values = {}

				for rname, _ in next, decoded.overrideData do
					values[#values + 1] = rname
				end

				timingList:SetValues(values)
			end

			local applied = 0
			for _, option in next, decoded.objects do
				if self.Parser[option.type] then
					task.spawn(function()
						self.Parser[option.type].Load(option.idx, option)
					end) -- task.spawn() so the config loading wont get stuck.

					applied = applied + 1
					if applied % 25 == 0 then
						task.wait()
					end
				end
			end

			if decoded.infoLoggerBlacklist then
				self.Library.InfoLoggerData.KeyBlacklistList = decoded.infoLoggerBlacklist
				self.Library:RefreshInfoLogger()
				if Options and Options.BlacklistedKeys then
					Options.BlacklistedKeys:SetValues(self.Library:KeyBlacklists())
				end
			end

			if decoded.infoLoggerCycle then
				self.Library.InfoLoggerData.InfoLoggerCycle = decoded.infoLoggerCycle
				self.Library:RefreshInfoLogger()
				if Options and Options.BlacklistedKeys then
					Options.BlacklistedKeys:SetValues(self.Library:KeyBlacklists())
				end
			end

			return true
		end

		function SaveManager:IgnoreThemeSettings()
			self:SetIgnoreIndexes({
				"BackgroundColor",
				"MainColor",
				"AccentColor",
				"OutlineColor",
				"FontColor", -- themes
				"ThemeManager_ThemeList",
				"ThemeManager_CustomThemeList",
				"ThemeManager_CustomThemeName", -- themes
			})
		end

		function SaveManager:BuildFolderTree()
			local paths = {
				self.Folder,
			}

			for i = 1, #paths do
				local str = paths[i]
				if not isfolder(str) then
					makefolder(str)
				end
			end
		end

		function SaveManager:RefreshConfigList()
			local list = listfiles(self.Folder)

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == ".json" then
					-- i hate this but it has to be done ...

					local pos = file:find(".json", 1, true)
					local start = pos

					local char = file:sub(pos, pos)
					while char ~= "/" and char ~= "\\" and char ~= "" do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == "/" or char == "\\" then
						table.insert(out, file:sub(pos + 1, start - 1))
					end
				end
			end

			return out
		end

		function SaveManager:SetLibrary(library)
			self.Library = library
		end

		function SaveManager:LoadAutoloadConfig()
			if isfile(self.Folder .. "/autoload.txt") then
				local name = readfile(self.Folder .. "/autoload.txt")

				local success, err = self:Load(name)
				if not success then
					return self.Library:Notify("Failed to load autoload config: " .. err)
				end

				self.Library:Notify(string.format("Auto loaded config %q", name))
			end
		end

		function SaveManager:BuildConfigSection(tab)
			assert(self.Library, "Must set SaveManager.Library")

			local section = tab:AddRightGroupbox("Config Manager")

			section:AddInput("SaveManager_ConfigName", { Text = "Config name" })
			section:AddDropdown(
				"SaveManager_ConfigList",
				{ Text = "Config list", Values = self:RefreshConfigList(), AllowNull = true }
			)

			section:AddDivider()

			section
				:AddButton("Create config", function()
					local name = Options.SaveManager_ConfigName.Value

					if name:gsub(" ", "") == "" then
						return self.Library:Notify("Invalid config name (empty)", 2)
					end

					local success, err = self:Save(name)
					if not success then
						return self.Library:Notify("Failed to save config: " .. err)
					end

					self.Library:Notify(string.format("Created config %q", name))

					Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
					Options.SaveManager_ConfigList:SetValue(nil)
				end)
				:AddButton("Load config", function()
					local name = Options.SaveManager_ConfigList.Value

					local success, err = self:Load(name)
					if not success then
						return self.Library:Notify("Failed to load config: " .. err)
					end

					self.Library:Notify(string.format("Loaded config %q", name))
				end)

			section:AddButton("Overwrite config", function()
				local name = Options.SaveManager_ConfigList.Value

				local success, err = self:Save(name)
				if not success then
					return self.Library:Notify("Failed to overwrite config: " .. err)
				end

				self.Library:Notify(string.format("Overwrote config %q", name))
			end)

			section:AddButton("Refresh list", function()
				Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
				Options.SaveManager_ConfigList:SetValue(nil)
			end)

			section:AddButton("Set as autoload", function()
				local name = Options.SaveManager_ConfigList.Value
				writefile(self.Folder .. "/autoload.txt", name)
				SaveManager.AutoloadLabel:SetText("Current autoload config: " .. name)
				self.Library:Notify(string.format("Set %q to auto load", name))
			end)

			SaveManager.AutoloadLabel = section:AddLabel("Current autoload config: none", true)

			if isfile(self.Folder .. "/autoload.txt") then
				local name = readfile(self.Folder .. "/autoload.txt")
				SaveManager.AutoloadLabel:SetText("Current autoload config: " .. name)
			end

			SaveManager:SetIgnoreIndexes({ "SaveManager_ConfigList", "SaveManager_ConfigName" })
		end

		SaveManager:BuildFolderTree()
	end

	return SaveManager
end)()

end)
__bundle_register("GUI/ThemeManager", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local httpService = game:GetService("HttpService")
	local ThemeManager = {}
	do
		ThemeManager.Folder = "Jawless Jockey Hub/Themes"
		ThemeManager.Library = nil
		ThemeManager.BuiltInThemes = {
			["Default"] = {
				1,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"1c1c1c","AccentColor":"0055ff","BackgroundColor":"141414","OutlineColor":"323232"}'
				),
			},
			["BBot"] = {
				2,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"1e1e1e","AccentColor":"7e48a3","BackgroundColor":"232323","OutlineColor":"141414"}'
				),
			},
			["Fatality"] = {
				3,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"1e1842","AccentColor":"c50754","BackgroundColor":"191335","OutlineColor":"3c355d"}'
				),
			},
			["Jester"] = {
				4,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"242424","AccentColor":"db4467","BackgroundColor":"1c1c1c","OutlineColor":"373737"}'
				),
			},
			["Mint"] = {
				5,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"242424","AccentColor":"3db488","BackgroundColor":"1c1c1c","OutlineColor":"373737"}'
				),
			},
			["Tokyo Night"] = {
				6,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"191925","AccentColor":"6759b3","BackgroundColor":"16161f","OutlineColor":"323232"}'
				),
			},
			["Ubuntu"] = {
				7,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"3e3e3e","AccentColor":"e2581e","BackgroundColor":"323232","OutlineColor":"191919"}'
				),
			},
			["Quartz"] = {
				8,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"232330","AccentColor":"426e87","BackgroundColor":"1d1b26","OutlineColor":"27232f"}'
				),
			},
			["Matte Black"] = {
				9,
				httpService:JSONDecode(
					'{"FontColor":"e6e6e6","MainColor":"121212","AccentColor":"4a4a4a","BackgroundColor":"0a0a0a","OutlineColor":"1f1f1f"}'
				),
			},
			["Intellect"] = {
				10,
				httpService:JSONDecode(
					'{"FontColor":"ffffff","MainColor":"141414","AccentColor":"e0263f","BackgroundColor":"0b0b0b","OutlineColor":"242424"}'
				),
			},
		}

		function ThemeManager:ApplyTheme(theme)
			local customThemeData = self:GetCustomTheme(theme)
			local data = customThemeData or self.BuiltInThemes[theme]

			if not data then
				return
			end

			for idx, themeData in next, customThemeData or data[2] do
				if type(themeData) == "string" then
					self.Library[idx] = Color3.fromHex(themeData)

					if Options[idx] then
						Options[idx]:SetValueRGB(Color3.fromHex(themeData))
					end
				else
					self.Library[idx] = Color3.fromHSV(themeData.hue, themeData.sat, themeData.vib)

					if Options[idx] then
						Options[idx].Rainbow = themeData.rainbow
						Options[idx]:SetValue({ themeData.hue, themeData.sat, themeData.vib }, themeData.transparency)
						Options[idx]:Display()
					end
				end
			end

			self:ThemeUpdate()
		end

		function ThemeManager:ThemeUpdate()
			-- This allows us to force apply themes without loading the themes tab :)
			local options = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }
			for i, field in next, options do
				if Options and Options[field] then
					self.Library[field] = Options[field].Value
				end
			end

			self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor)
			self.Library:UpdateColorsUsingRegistry()
		end

		function ThemeManager:LoadDefault()
			local theme = "Default"
			local content = isfile(self.Folder .. "/default.txt") and readfile(self.Folder .. "/default.txt")

			local isDefault = true
			if content then
				if self.BuiltInThemes[content] then
					theme = content
				elseif self:GetCustomTheme(content) then
					theme = content
					isDefault = false
				end
			elseif self.BuiltInThemes[self.DefaultTheme] then
				theme = self.DefaultTheme
			end

			if isDefault then
				Options.ThemeManager_ThemeList:SetValue(theme)
			else
				self:ApplyTheme(theme)
			end
		end

		function ThemeManager:SaveDefault(theme)
			writefile(self.Folder .. "/default.txt", theme)
		end

		function ThemeManager:CreateThemeManager(groupbox)
			groupbox
				:AddLabel("Background color")
				:AddColorPicker("BackgroundColor", { Default = self.Library.BackgroundColor })
			groupbox:AddLabel("Main color"):AddColorPicker("MainColor", { Default = self.Library.MainColor })
			groupbox:AddLabel("Accent color"):AddColorPicker("AccentColor", { Default = self.Library.AccentColor })
			groupbox:AddLabel("Outline color"):AddColorPicker("OutlineColor", { Default = self.Library.OutlineColor })
			groupbox:AddLabel("Font color"):AddColorPicker("FontColor", { Default = self.Library.FontColor })

			local ThemesArray = {}
			for Name, Theme in next, self.BuiltInThemes do
				table.insert(ThemesArray, Name)
			end

			table.sort(ThemesArray, function(a, b)
				return self.BuiltInThemes[a][1] < self.BuiltInThemes[b][1]
			end)

			groupbox:AddDivider()
			groupbox:AddDropdown("ThemeManager_ThemeList", { Text = "Theme list", Values = ThemesArray, Default = 1 })

			groupbox:AddButton("Set as default", function()
				self:SaveDefault(Options.ThemeManager_ThemeList.Value)
				self.Library:Notify(string.format("Set default theme to %q", Options.ThemeManager_ThemeList.Value))
			end)

			Options.ThemeManager_ThemeList:OnChanged(function()
				self:ApplyTheme(Options.ThemeManager_ThemeList.Value)
			end)

			groupbox:AddDivider()
			groupbox:AddInput("ThemeManager_CustomThemeName", { Text = "Custom theme name" })
			groupbox:AddDropdown(
				"ThemeManager_CustomThemeList",
				{ Text = "Custom themes", Values = self:ReloadCustomThemes(), AllowNull = true, Default = 1 }
			)
			groupbox:AddDivider()

			groupbox
				:AddButton("Save theme", function()
					self:SaveCustomTheme(Options.ThemeManager_CustomThemeName.Value)

					Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
					Options.ThemeManager_CustomThemeList:SetValue(nil)
				end)
				:AddButton("Load theme", function()
					self:ApplyTheme(Options.ThemeManager_CustomThemeList.Value)
				end)

			groupbox:AddButton("Refresh list", function()
				Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
				Options.ThemeManager_CustomThemeList:SetValue(nil)
			end)

			groupbox:AddButton("Set as default", function()
				if
					Options.ThemeManager_CustomThemeList.Value ~= nil
					and Options.ThemeManager_CustomThemeList.Value ~= ""
				then
					self:SaveDefault(Options.ThemeManager_CustomThemeList.Value)
					self.Library:Notify(
						string.format("Set default theme to %q", Options.ThemeManager_CustomThemeList.Value)
					)
				end
			end)

			ThemeManager:LoadDefault()

			local function UpdateTheme()
				self:ThemeUpdate()
			end

			Options.BackgroundColor:OnChanged(UpdateTheme)
			Options.MainColor:OnChanged(UpdateTheme)
			Options.AccentColor:OnChanged(UpdateTheme)
			Options.OutlineColor:OnChanged(UpdateTheme)
			Options.FontColor:OnChanged(UpdateTheme)
		end

		function ThemeManager:GetCustomTheme(file)
			local path = self.Folder .. "/" .. file
			if not isfile(path) then
				return nil
			end

			local data = readfile(path)
			local success, decoded = pcall(httpService.JSONDecode, httpService, data)

			if not success then
				return nil
			end

			return decoded
		end

		function ThemeManager:SaveCustomTheme(file)
			if file:gsub(" ", "") == "" then
				return self.Library:Notify("Invalid file name for theme (empty)", 3)
			end

			local theme = {}
			local fields = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }

			for _, field in next, fields do
				local option = Options[field]

				theme[field] = {
					type = "ColorPicker",
					hue = option.Hue,
					sat = option.Sat,
					vib = option.Vib,
					transparency = option.Transparency,
					rainbow = option.Rainbow,
				}
			end

			writefile(self.Folder .. "/" .. file .. ".json", httpService:JSONEncode(theme))
		end

		function ThemeManager:ReloadCustomThemes()
			local list = listfiles(self.Folder)

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == ".json" then
					-- i hate this but it has to be done ...

					local pos = file:find(".json", 1, true)
					local char = file:sub(pos, pos)

					while char ~= "/" and char ~= "\\" and char ~= "" do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == "/" or char == "\\" then
						table.insert(out, file:sub(pos + 1))
					end
				end
			end

			return out
		end

		function ThemeManager:SetLibrary(lib)
			self.Library = lib
		end

		function ThemeManager:BuildFolderTree()
			makefolder(self.Folder)
		end

		function ThemeManager:SetFolder(folder)
			self.Folder = folder
			self:BuildFolderTree()
		end

		function ThemeManager:CreateGroupBox(tab)
			assert(self.Library, "Must set ThemeManager.Library first!")
			return tab:AddLeftGroupbox("Theme Manager")
		end

		function ThemeManager:ApplyToTab(tab)
			assert(self.Library, "Must set ThemeManager.Library first!")
			local groupbox = self:CreateGroupBox(tab)
			self:CreateThemeManager(groupbox)
		end

		function ThemeManager:ApplyToGroupbox(groupbox)
			assert(self.Library, "Must set ThemeManager.Library first!")
			self:CreateThemeManager(groupbox)
		end

		ThemeManager:BuildFolderTree()
	end

	return ThemeManager
end)()

end)
